import{j as e,L as r}from"./index-CWEE_cfb.js";import{g as s}from"./beginnerCourseLanding-Q34l_stc.js";const v="https://www.icbc.com/driver-licensing/new-drivers/Get-your-L",w="https://www.icbc.com/driver-licensing/new-drivers/you-have-a-class-7l-licence",x="https://www.icbc.com/driver-licensing/driving-guides/Tuning-Up-for-Drivers",y="https://www.icbc.com/driver-licensing/moving-bc",b="https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school",j="https://www.google.com/maps/place/Shanaya's+Driving+School/@48.4514745,-123.5207662,17z/data=!4m8!3m7!1s0x548f0dbc0a227e83:0xf890ce589bc36216!8m2!3d48.451471!4d-123.5181913!9m1!1b1!16s%2Fg%2F11nk25xtf2",d=[{question:"Am I too old to start learning to drive in Victoria?",answer:"Starting as an adult is not a reason to rush or feel embarrassed. Begin with the licence path that applies to you, explain your experience honestly and use specific skill checkpoints instead of comparing your progress with another learner's timeline."},{question:"What if I do not have a family member available for practice?",answer:"Tell the instructor before choosing a lesson plan. Paid instruction can provide practice and feedback, while any practice outside lessons must still follow the conditions on your licence, including the Class 7L supervisor rules when they apply."},{question:"What happens during a first adult driving lesson?",answer:"Confirm the meeting point, vehicle, lesson length and goal in advance. At the start, describe your licence status, previous experience and concerns. The instructor can then choose an appropriate starting environment and identify practical next steps."}],k={slug:"learning-to-drive-as-an-adult-victoria",title:"Learning to Drive as an Adult in Victoria: A Practical Starting Guide",seoTitle:"Adult Driving Lessons in Victoria, BC",description:"A practical guide for adult learners in Victoria, BC: choose the right licence path, prepare for a first lesson, manage nerves and plan practice without guessing.",heroImage:"/landing/nervous-driver-lessons-victoria.webp",author:"Shanaya's Driving School",date:"September 7, 2026",datePublished:"2026-09-07",dateModified:"2026-09-07",readTime:"7 min read",category:"Adult Learners",relatedSlugs:["choosing-driving-school-first-time-victoria-langford","how-many-driving-lessons-before-victoria-driving-test","newcomers-guide-bc"],faqs:d,content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Learning to drive as an adult in Victoria can begin with basic vehicle control, a return after years away, or adapting experience from another country. Your age does not determine the right lesson plan. Your licence status, current skills, access to legal practice and the situations that make you hesitate are more useful starting points."}),e.jsx("p",{children:"Start by identifying which path below applies to you. Then use a first lesson to establish what you can already do, what needs attention and how you will practise between sessions. There is no universal number of paid lessons that guarantees road-test readiness."}),e.jsx("h2",{children:"Choose the adult-learning path that fits your situation"}),e.jsx("h3",{children:"You have never held a licence"}),e.jsxs("p",{children:["Begin with ICBC's current"," ",e.jsx("a",{href:v,target:"_blank",rel:"noopener noreferrer",children:"Get your L requirements"}),". Passing the knowledge test starts the learner stage; it does not mean you must immediately drive in busy traffic. Early practice can focus on becoming familiar with the controls, smooth starts and stops, steering, observation and simple decisions in a suitable environment."]}),e.jsxs("p",{children:["A ",e.jsx(r,{to:"/courses/beginner-driving-course",children:"beginner driving course"})," can provide a structured starting point. Ask how the instructor will adapt the first session if you have never sat in the driver's seat or if you need more time with one skill."]}),e.jsx("h3",{children:"You are returning after a long break"}),e.jsxs("p",{children:["Do not assume you need to begin again or that one quick drive will restore every habit. Bring your valid licence, explain when and where you last drove, and identify situations you have been avoiding. A"," ",e.jsx(r,{to:"/courses/refresher-driving-course",children:"refresher driving course"})," can focus on observed gaps such as scanning, lane changes, parking or managing denser traffic."]}),e.jsx("h3",{children:"You learned outside British Columbia"}),e.jsxs("p",{children:["Your next licensing step depends on where your licence was issued and your documented experience. Check ICBC's"," ",e.jsx("a",{href:y,target:"_blank",rel:"noopener noreferrer",children:"moving to B.C. guidance"})," ","before booking a course or test. Our ",e.jsx(r,{to:"/blog/newcomers-guide-bc",children:"newcomer driving guide"})," ","explains the main paths and links back to the official requirements."]}),e.jsx("h2",{children:"What to tell the instructor before your first lesson"}),e.jsx("p",{children:"A short, honest summary helps the lesson start at the right level. Share:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"your current licence and any restrictions;"}),e.jsx("li",{children:"where, when and how much you have driven;"}),e.jsx("li",{children:"whether you can practise legally between lessons;"}),e.jsx("li",{children:"specific concerns, such as traffic, parking, speed or being observed; and"}),e.jsx("li",{children:"your goal, without treating a planned test date as proof of readiness."})]}),e.jsx("p",{children:"Confirm the lesson length, vehicle, meeting point, total price and cancellation terms before paying. If you need pickup from home, work or another Victoria-area location, ask whether it is available for your address and preferred time rather than assuming it is included."}),e.jsx("h2",{children:"If you feel nervous, make the next step smaller and specific"}),e.jsx("p",{children:"Nervousness is information, not a verdict on whether you can learn. Tell the instructor what triggers it. “Traffic” is broad; “I rush when another vehicle waits behind me” gives the instructor something concrete to plan around. Ask for short instructions during demanding moments and detailed feedback once the vehicle is parked."}),e.jsxs("blockquote",{children:["“He taught very well and explained everything clearly and in great detail, which made the lesson easy to understand.” — Amita, in a saved"," ",e.jsx("a",{href:j,target:"_blank",rel:"noopener noreferrer",children:"Google review"})]}),e.jsxs("p",{children:["That is one learner's account, not a promised result. It does illustrate useful questions to ask: Will the instructor explain why a skill matters? Can they adjust the pace? Will they tell you what to practise next? Adults who want a lower-pressure start can also review our"," ",e.jsx(r,{to:"/nervous-driver-lessons-victoria",children:"nervous-driver lesson information"}),"."]}),e.jsx("h2",{children:"How to practise when family or friends cannot supervise"}),e.jsxs("p",{children:["If you hold a Class 7L licence, every practice drive must follow ICBC's current"," ",e.jsx("a",{href:w,target:"_blank",rel:"noopener noreferrer",children:"learner restrictions"}),", including its supervisor requirements. Do not practise alone or with someone who is not eligible to supervise you."]}),e.jsxs("p",{children:["When suitable private practice is limited, tell the instructor before choosing a package. Prioritize the skills that need professional feedback, keep notes after each lesson and use ICBC's free"," ",e.jsx("a",{href:x,target:"_blank",rel:"noopener noreferrer",children:"Tuning Up for Drivers guide"})," ","if an eligible supervisor becomes available. Our guide to"," ",e.jsx(r,{to:"/blog/how-many-driving-lessons-before-victoria-driving-test",children:"planning lesson numbers"})," ","explains why instruction hours and supervised practice are not interchangeable totals."]}),e.jsx("h2",{children:"Choose clear terms instead of a confident sales promise"}),e.jsx("p",{children:"ICBC advises learners to verify the school and instructor licences, discuss the course outline and obtain written information before deciding."}),e.jsxs("blockquote",{children:["“Request a written copy of the school's statement of services and policy statement.” —"," ",e.jsx("a",{href:b,target:"_blank",rel:"noopener noreferrer",children:"ICBC, Choosing your driving school"})]}),e.jsxs("p",{children:["Ask what each session includes, how progress will be reviewed and which fees or policies apply. Be cautious of guaranteed passes, fixed lesson counts presented as universal, or claims of access to an official test route. Our"," ",e.jsx(r,{to:"/blog/choosing-driving-school-first-time-victoria-langford",children:"Victoria driving-school comparison checklist"})," ","gives you seven questions to use before booking."]}),e.jsx("h2",{children:"A practical first-week plan"}),e.jsxs("ol",{children:[e.jsx("li",{children:"Confirm your current ICBC licence path and restrictions."}),e.jsx("li",{children:"Write down your experience, concerns, practice access and goal."}),e.jsx("li",{children:"Choose a licensed school and request its service and policy details."}),e.jsx("li",{children:"Book a first lesson at a suitable level instead of predicting a complete lesson total."}),e.jsx("li",{children:"Afterward, record one strength, one priority and the next safe practice step."})]}),e.jsxs("p",{children:["Shanaya's Driving School publishes this guide and offers paid instruction. You can review current ",e.jsx(r,{to:"/pricing",children:"lesson pricing"})," and"," ",e.jsx(r,{to:"/contact",children:"contact the school"})," with your licence stage, availability and preferred starting location. A useful first conversation should leave you with a clearer next step, not a guarantee about how quickly you will finish."]}),e.jsx("h2",{children:"Frequently asked questions"}),d.map(i=>e.jsxs("section",{children:[e.jsx("h3",{children:i.question}),e.jsx("p",{children:i.answer})]},i.question))]})},h=[{question:"How much are driving lessons in Victoria, BC in 2026?",answer:"Shanaya’s standard rate is $89 CAD per hour before GST. We are currently running a 30% promotion on eligible lessons. If it applies to your booking, a one-hour lesson works out to $62.30 before GST. Call 250-542-3673 to confirm eligible lessons, available dates and the final price."},{question:"Do you offer monthly or festival discounts?",answer:"Yes. We run monthly and festival promotions. Past offers included up to 50% off throughout April 2026 and a later 40% promotion. Our current promotion is 30% off eligible lessons. Past offers have ended; call 250-542-3673 to check the offer available for your booking and whether it can be combined with anything else."},{question:"Can I try a lesson before committing?",answer:"We have offered free trial lessons so learners can experience our teaching approach before choosing paid instruction. Call 250-542-3673 to ask whether a trial is currently available, who qualifies and what it includes. Trial availability and any follow-on discount should be confirmed before booking."},{question:"What makes professional driving lessons worth the cost?",answer:"The value is individual feedback: understanding what you already do well, working on the areas that need attention and leaving with a clearer practice plan. Patient explanations and a lesson paced to your experience can make learning more manageable. Progress varies, so choose instruction around your needs rather than a promised number of lessons or a guaranteed pass."},{question:"Does the lesson price include a car for my road test?",answer:"A standard lesson includes the school car during that lesson. Road-test-day vehicle use is a separate service unless your chosen package includes it. Ask for the preparation time, vehicle use, applicable discount and final total to be itemised. ICBC test and licensing fees are separate."}],u="tel:+12505423673",C="inline-flex min-h-12 items-center justify-center rounded-lg bg-[#1d52a1] px-5 py-3 text-center !text-white !no-underline hover:bg-[#17488d] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-blue-700",I={slug:"driving-lessons-cost-victoria-bc-2026",title:"How Much Do Driving Lessons Cost in Victoria, BC in 2026?",seoTitle:"Driving Lesson Costs in Victoria, BC (2026)",description:"Explore supportive driving lessons in Victoria, BC, current savings, student experiences and practical ways to get more value from every lesson in 2026.",heroImage:"/landing/pricing.webp",author:"Shanaya's Driving School",date:"September 6, 2026",datePublished:"2026-09-05",dateModified:"2026-09-06",readTime:"7 min read",category:"Lesson Costs",faqs:h,relatedSlugs:["pass-road-test","icbc-road-test-victoria-mckenzie-office","newcomers-guide-bc"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Picture the first drive you can make on your own schedule: getting to work without arranging a ride, helping your family when they need you or simply feeling calm on a busy Victoria road. That freedom starts before the road test. It begins when each lesson turns uncertainty into a skill you understand and can use again."}),e.jsx("p",{children:"Whether you are taking the wheel for the first time, returning after a long break or preparing for your test, the real question is not simply what an hour costs. It is what you can take from that hour. This guide will help you recognise worthwhile instruction, plan a realistic budget and find available savings without choosing lessons on price alone."}),e.jsx("h2",{children:"Start with the progress you want to feel"}),e.jsx("p",{children:"An hour behind the wheel is most useful when you understand what you are practising and why. Personal instruction gives you someone who can explain an unfamiliar task, notice a habit you have missed and help you decide what to work on next. That is the value to look for when comparing driving lessons in Victoria, BC."}),e.jsx("p",{children:"For a beginner, that might mean learning the foundations without feeling rushed. For a nervous driver, it may be the chance to ask questions in a patient setting. For someone preparing for a road test, it can mean getting specific feedback instead of wondering whether more practice is helping. The lesson should meet you at your current stage."}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:s,children:"“The lessons were professional, supportive, and helped build my son’s skills and confidence behind the wheel.”"}),e.jsxs("figcaption",{className:"text-sm",children:["Vanessa Nicdao · excerpt from a Google review · ",e.jsx("a",{href:s,target:"_blank",rel:"noopener noreferrer",children:"Read reviews on Google"})]})]}),e.jsx("p",{children:"Vanessa’s experience captures what many parents want from lessons: progress they can see and a learning environment their child feels comfortable in. It is one family’s experience, rather than a promise that every learner will progress at the same pace."}),e.jsx("h2",{children:"Monthly discounts, festival offers and free trials"}),e.jsxs("p",{children:["Once you know what kind of support will move you forward, it becomes easier to plan what to spend. Our standard 60-minute lesson is ",e.jsx("strong",{children:"$89 CAD before GST"}),". That hour is built around your current ability, the skills you want to strengthen and useful feedback for your next practice session."]}),e.jsxs("p",{children:["Affordability matters when lessons need to fit around school, rent or family expenses, so we run promotions through the year. In ",e.jsx("strong",{children:"April 2026, we offered up to 50% off for the full month"}),". A later promotion offered 40% off. Those are past offers; our current promotion is 30% off eligible lessons. If it applies to your booking, a one-hour lesson is $62.30 before GST, saving $26.70."]}),e.jsx("p",{children:"We have also introduced free trials so learners can experience the teaching before choosing paid lessons. If you are unsure whether the instructor’s approach will suit you, ask about trying a session. It is a practical way to discuss your goals and find out how comfortable you feel asking questions."}),e.jsxs("p",{children:["Call ",e.jsx("a",{href:u,children:"250-542-3673"})," for available discounts and trial options. We will confirm what applies to your chosen course and dates, including any eligibility conditions. Please check before paying rather than assuming an earlier offer is still running or that separate discounts can be combined."]}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:s,children:"“The school was also very flexible in scheduling my lessons around my availability, which made the whole learning process stress-free.”"}),e.jsxs("figcaption",{className:"text-sm",children:["Divya Pandya · excerpt from a Google review · ",e.jsx("a",{href:s,target:"_blank",rel:"noopener noreferrer",children:"Explore more student experiences"})]})]}),e.jsx("p",{children:"Divya also described the instruction as offering “great value for the quality of instruction they provide.” Price matters, but so does finding lessons you can attend and a teaching approach that helps you learn."}),e.jsx("h2",{children:"How discounts can change your lesson budget"}),e.jsx("p",{children:"To understand driving lessons prices in 2026, compare actual instruction time and the offer available to you. Here is how our standard hourly rate compares with a 30% reduction when the selected instruction qualifies. All figures are CAD before GST; test-day services and ICBC fees are separate."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Standard and eligible discounted lesson budgets",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"Illustrations using the current 30% promotion if applicable to every hour booked; not package quotes."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Instruction time"}),e.jsx("th",{scope:"col",children:"Standard subtotal"}),e.jsx("th",{scope:"col",children:"With 30% off"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"1 hour"}),e.jsx("td",{children:"$89"}),e.jsx("td",{children:"$62.30"})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"5 hours"}),e.jsx("td",{children:"$445"}),e.jsx("td",{children:"$311.50"})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"10 hours"}),e.jsx("td",{children:"$890"}),e.jsx("td",{children:"$623"})]})]})]})}),e.jsx("p",{children:"Choose the hours around your learning needs. These examples show what a discount could mean for your budget, not how many lessons you must buy. Confirm the current offer and itemised total when booking; a suitable starting plan is more useful than buying hours simply because they are on sale."}),e.jsx("h2",{children:"Choose the right lessons for your stage"}),e.jsxs("p",{children:["If you are looking for ",e.jsx(r,{to:"/courses/beginner-driving-course",children:"beginner driving lessons in Victoria"}),", ask how the first sessions build foundations and how your instructor will explain progress. Our standard lessons include a licensed instructor and a dual-control school car. Pickup and drop-off are available within the service area, subject to scheduling; confirm your address and arrangement when booking."]}),e.jsxs("p",{children:["Individual lessons can be a useful starting point when you want to experience the teaching or focus on a particular concern. A ",e.jsx(r,{to:"/packages",children:"lesson package"})," may suit a learner who wants a planned sequence. Ask which option fits your experience and whether the current discount applies to that choice."]}),e.jsxs("p",{children:["If your test is approaching, compare a preparation lesson with a",e.jsx(r,{to:"/courses/lesson-road-test-prep-course",children:" road-test package"}),". Check how much instruction and vehicle use each contains. Keeping those details clear helps you choose useful support without paying for services you do not need."]}),e.jsx("h2",{children:"Get more value from every appointment"}),e.jsxs("p",{children:["Tell your instructor what feels difficult, ask questions while an explanation is fresh and leave knowing your next practice priority. When legal supervised practice is available, use it to build on the feedback from your lesson. ICBC’s free",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driving-guides/Tuning-Up-for-Drivers",target:"_blank",rel:"noopener noreferrer",children:" Tuning Up for Drivers guide"}),"is another resource you can use alongside instruction."]}),e.jsxs("p",{children:["When comparing a driving instructor in Victoria, BC, look for a clear course outline, patient communication and written booking terms. ICBC’s",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school",target:"_blank",rel:"noopener noreferrer",children:" advice on choosing a driving school"}),"explains the licensing and service information to check. A good price becomes good value when you understand what you are buying and how it supports your goals."]}),e.jsxs("p",{children:["Before you book, confirm the lesson length, applicable discount, pickup arrangement and final total. Read the ",e.jsx(r,{to:"/policies/cancellation-and-rescheduling",children:"cancellation terms"}),"so the schedule fits your commitments. No lesson count can guarantee a test result, but a clear plan gives you a more useful starting point than guesswork."]}),e.jsx("h2",{children:"Frequently asked questions"}),e.jsx("div",{className:"my-6 space-y-3",children:h.map(i=>e.jsxs("details",{className:"group rounded-xl border border-slate-200 bg-white open:border-blue-300 open:bg-blue-50/40",children:[e.jsxs("summary",{className:"flex min-h-14 cursor-pointer list-none items-center justify-between gap-4 rounded-xl p-5 font-bold text-slate-900 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700 [&::-webkit-details-marker]:hidden",children:[e.jsx("span",{children:i.question}),e.jsx("span",{"aria-hidden":"true",className:"shrink-0 text-2xl text-blue-700 group-open:hidden",children:"+"}),e.jsx("span",{"aria-hidden":"true",className:"hidden shrink-0 text-2xl text-blue-700 group-open:inline",children:"−"})]}),e.jsx("p",{className:"!mb-0 px-5 pb-5",children:i.answer})]},i.question))}),e.jsx("h2",{children:"Find a lesson plan that feels right for you"}),e.jsx("p",{children:"You do not need to arrive with every lesson planned. Tell us where you are starting, what you want to feel more confident doing and the budget you have in mind. We can talk through suitable lessons, the current 30% promotion and whether a free trial is available."}),e.jsxs("aside",{"aria-label":"Ask about lessons and discounts",className:"my-6 rounded-xl border border-blue-200 bg-blue-50 p-6",children:[e.jsx("p",{className:"text-xl font-bold text-slate-900",children:"Your next step can be a simple conversation."}),e.jsx("p",{children:"Call for today’s offers and trial availability, or send a booking enquiry with your preferred dates."}),e.jsxs("div",{className:"flex flex-wrap gap-3",children:[e.jsx("a",{href:u,className:C,children:"Call 250-542-3673"}),e.jsx(r,{to:"/apply",className:"inline-flex min-h-12 items-center justify-center rounded-lg border border-blue-700 px-5 py-3 text-center !no-underline hover:bg-blue-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-blue-700",children:"Enquire about lessons and offers"})]})]}),e.jsx("p",{className:"text-sm text-slate-500",children:"Prices and promotion information checked September 6, 2026. Offers can change; confirm eligibility, dates and the final amount before payment. Review excerpts reflect individual experiences."})]})},p=[{question:"Are five driving lessons enough before a Victoria road test?",answer:"They may help an experienced learner address specific gaps. For a beginner, five lessons should not be treated as a promise of readiness. Ask an instructor what you can do consistently and what still needs practice before deciding whether to book more."},{question:"Does ICBC recommend 60 driving lessons?",answer:"No. Its Learn to Drive Smart manual recommends at least 60 hours of practice before the Class 7 road test. That means practice time, not 60 purchased lessons, and reaching the total does not guarantee a pass."},{question:"How many more lessons should I take after failing a road test?",answer:"Bring your examiner’s feedback to an instructor and work out what needs attention. One specific difficulty and several recurring problems call for different plans. Reassess those skills before your next attempt rather than choosing an arbitrary number of extra lessons."}],B={slug:"how-many-driving-lessons-before-victoria-driving-test",title:"How Many Driving Lessons Do You Need Before a Victoria Driving Test?",seoTitle:"How Many Driving Lessons Before a Victoria Road Test?",description:"Plan driving lessons before your Victoria, BC road test. Understand ICBC’s practice guidance, lesson lengths and how to assess your readiness.",heroImage:"/landing/road-test-prep-victoria.webp",author:"Shanaya's Driving School",date:"September 6, 2026",datePublished:"2026-09-06",dateModified:"2026-09-06",readTime:"7 min read",category:"Lesson Planning",faqs:p,relatedSlugs:["driving-lessons-cost-victoria-bc-2026","icbc-road-test-tips-victoria","pass-road-test"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"You’re comparing lesson packages, looking at your budget and wondering whether five lessons will be enough before your Victoria driving test. Booking ten might feel reassuring, but you want to know what you actually need."}),e.jsxs("p",{children:[e.jsx("strong",{children:"There is no single lesson count that makes every learner ready."})," ICBC’s"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"Class 7 preparation guidance"})," recommends supervised practice and suggests driver training without setting a fixed paid-lesson total. Your starting skills and practice opportunities matter. An assessment lesson can help you turn that uncertainty into a plan."]}),e.jsxs("p",{children:["This guide focuses on the ",e.jsx("strong",{children:"Class 7 road test for your novice, or N, licence"})," ","in Victoria, British Columbia. Confirm your own ICBC requirements if you are taking another test or transferring a licence."]}),e.jsx("h2",{children:"Does ICBC require a minimum number of driving lessons?"}),e.jsxs("p",{children:["The published guidance does not prescribe a universal lesson package. You still need to meet ICBC’s ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"learner-stage conditions"}),". Being eligible to take the test and being comfortable making safe decisions are separate milestones."]}),e.jsxs("p",{children:["A separate ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driver-training/New-drivers-or-riders",target:"_blank",rel:"noopener noreferrer",children:"ICBC-approved Graduated Licensing Program (GLP) course"})," has its own hours: at least 16 classroom, 12 on-road and four flexible hours. Those describe that course format, not a requirement for every Class 7 candidate."]}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:"https://www.icbc.com/assets/en/40I9m5k2Tqnf7aNs5kqPHj/drivers9.pdf#page=1",children:"“Professional training can help you learn faster and avoid developing bad driving habits.”"}),e.jsxs("figcaption",{className:"text-sm",children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/assets/en/40I9m5k2Tqnf7aNs5kqPHj/drivers9.pdf#page=1",target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart, page 135"}),"."]})]}),e.jsx("h2",{children:"What does ICBC’s 60-hour practice recommendation mean?"}),e.jsxs("p",{children:["ICBC’s ",e.jsx("a",{href:"https://www.icbc.com/assets/en/40I9m5k2Tqnf7aNs5kqPHj/drivers9.pdf#page=5",target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart manual, page 139"})," ","recommends ",e.jsx("strong",{children:"at least 60 hours of practice"})," before the Class 7 road test. This is a practice recommendation, not a requirement to buy 60 lessons. Reaching that total also does not automatically mean you are ready to pass."]}),e.jsx("p",{children:"Keep a record of driving time with your instructor and qualified supervisor, listing them separately. Follow your learner restrictions on every drive. Alongside the minutes, note what became easier and where you still needed help."}),e.jsxs("p",{children:["For example, a note about needing observation reminders while parking gives your next lesson a useful starting point. ICBC’s ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driving-guides/Tuning-Up-for-Drivers",target:"_blank",rel:"noopener noreferrer",children:"Tuning up for Drivers guide"})," provides a structure for working through driving skills with your supervisor."]}),e.jsx("h2",{children:"Start with your experience: what kind of learner are you?"}),e.jsx("p",{children:"Someone learning to steer for the first time needs a different conversation from someone polishing familiar skills. Find your starting point below. These are planning examples, not predicted lesson totals."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Lesson planning by driving experience",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"Use your starting point to guide the first conversation with an instructor."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Your situation"}),e.jsx("th",{scope:"col",children:"What to discuss"}),e.jsx("th",{scope:"col",children:"How to decide the next step"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Starting from scratch"}),e.jsx("td",{children:"Foundations and access to supervised practice."}),e.jsx("td",{children:"Agree on progress checkpoints before predicting a test date."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Already practising with family"}),e.jsx("td",{children:"Skills that still need reminders."}),e.jsx("td",{children:"Get an assessment and focus lessons on the gaps."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Experienced but unfamiliar with B.C. roads"}),e.jsx("td",{children:"Local rules and your specific ICBC requirements."}),e.jsx("td",{children:"Have your driving assessed before choosing a course."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Preparing for another attempt"}),e.jsx("td",{children:"Examiner feedback and recurring difficulties."}),e.jsx("td",{children:"Work on those issues, then reassess."})]})]})]})}),e.jsx("p",{children:"If lessons are your only chance to drive, say so. Your plan needs to fit the vehicle, qualified supervisor and time you actually have. If you feel nervous, explain what makes you uneasy so you can discuss a manageable pace."}),e.jsxs("p",{children:["Building your foundations? Explore our"," ",e.jsx(r,{to:"/beginner-driving-lessons-victoria",children:"beginner driving lessons in Victoria"})," and discuss which starting point suits you."]}),e.jsx("h2",{children:"Are five or ten driving lessons enough?"}),e.jsx("p",{children:"Imagine two learners buying five sessions. One has practised regularly with family; the other has barely driven. They are buying the same number of appointments, but starting with very different needs."}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:"https://www.icbc.com/about-icbc/newsroom/2022-jul-21",children:"“Even one or two lessons can make a difference in passing your road test.”"}),e.jsxs("figcaption",{className:"text-sm",children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/about-icbc/newsroom/2022-jul-21",target:"_blank",rel:"noopener noreferrer",children:"road-test tips, July 21, 2022"}),"."]})]}),e.jsx("p",{children:"That is encouragement to get useful instruction, not a promise that a beginner can prepare in two lessons. Ask what each session should help you improve."}),e.jsx("h3",{children:"Compare instruction hours as well as lesson counts"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Five 60-minute lessons:"})," five hours of instruction."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Five 90-minute lessons:"})," seven and a half hours of instruction."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Ten 90-minute lessons:"})," fifteen hours of instruction."]})]}),e.jsxs("p",{children:["These are calculations, not recommended totals. Ask how much appointment time is spent driving and what feedback is included. Our"," ",e.jsx(r,{to:"/blog/driving-lessons-cost-victoria-bc-2026",children:"Victoria lesson-cost guide"})," can help you compare spending."]}),e.jsx("h3",{children:"Ask for a reason behind each additional lesson"}),e.jsx("p",{children:"If another lesson is suggested, ask what it will address. A specific goal, such as working on gap choices at intersections, gives you something to track. Agree on what to practise with your supervisor and when to review progress."}),e.jsx("h2",{children:"What should your lessons prepare you for in Victoria?"}),e.jsxs("p",{children:["A familiar journey can feel easy until the signs or traffic change. The"," ",e.jsx("a",{href:"https://www.victoria.ca/getting-around/driving/lower-speed-limits",target:"_blank",rel:"noopener noreferrer",children:"City of Victoria’s speed-limit update"})," says local-street reductions to 30 km/h were completed in December 2025, with most major streets moving to 40 km/h during 2026, subject to exceptions. This concerns the City of Victoria, not every municipality in Greater Victoria."]}),e.jsxs("p",{children:["Discuss whether you can respond to changing signs, traffic, pedestrians and cyclists beyond your usual practice journey. Those are useful topics to discuss when considering our"," ",e.jsx(r,{to:"/courses/road-test-prep-course",children:"Road Test Prep Course"}),"."]}),e.jsxs("p",{children:["Be cautious about anyone selling a supposed official test route: ICBC"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"does not share routes outside ICBC"}),". Our ",e.jsx(r,{to:"/blog/icbc-road-test-tips-victoria",children:"Victoria road-test preparation guide"})," covers local driving considerations in more detail."]}),e.jsx("h2",{children:"How do you know you’re getting closer to test-ready?"}),e.jsxs("p",{children:["Ask your instructor to discuss the five areas in ICBC’s"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"}),": observation, space margin, speed, steering and communication. Make the feedback specific:"]}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Observation:"})," Do I notice hazards and make the necessary checks without reminders?"]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Space margin:"})," Are my following distances, road position and gap choices appropriate?"]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Speed:"})," Do I respond to limits and conditions consistently?"]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Steering:"})," Is my control reliable through turns and manoeuvres?"]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Communication:"})," Are my signals timely and clear to other road users?"]})]}),e.jsxs("p",{children:["Use these questions for discussion, not self-scoring. Ask whether you still need coaching or safety interventions, and whether improvements hold across different drives. A"," ",e.jsx(r,{to:"/courses/mock-test-evaluation",children:"mock test evaluation"})," can reveal remaining work; it cannot guarantee a pass."]}),e.jsx("h2",{children:"How to plan lessons without buying more than you need"}),e.jsxs("ol",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Explain your starting point."})," Share your experience, practice access, budget and any planned test date."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Ask for an initial assessment."})," Request specific feedback and priorities for your next sessions."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Agree on a review point."})," Decide when you will revisit the plan instead of treating the first estimate as a fixed total."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Keep a practice record."})," Bring questions and recurring difficulties to the next lesson."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Confirm the purchase details."})," Get lesson duration, inclusions, fees and cancellation terms in writing."]})]}),e.jsxs("p",{children:["ICBC’s ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school",target:"_blank",rel:"noopener noreferrer",children:"school-selection guidance"})," recommends checking school and instructor licensing and requesting written service and policy details. Clear terms help you compare instruction on the same basis."]}),e.jsx("h2",{children:"Frequently asked questions about lesson numbers"}),e.jsx("div",{className:"my-6 space-y-3",children:p.map(i=>e.jsxs("details",{className:"group rounded-xl border border-slate-200 bg-white open:border-blue-300 open:bg-blue-50/40",children:[e.jsxs("summary",{className:"flex min-h-14 cursor-pointer list-none items-center justify-between gap-4 rounded-xl p-5 font-bold text-slate-900 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700 [&::-webkit-details-marker]:hidden",children:[e.jsx("span",{children:i.question}),e.jsx("span",{"aria-hidden":"true",className:"shrink-0 text-2xl text-blue-700 group-open:hidden",children:"+"}),e.jsx("span",{"aria-hidden":"true",className:"hidden shrink-0 text-2xl text-blue-700 group-open:inline",children:"−"})]}),e.jsx("p",{className:"!mb-0 px-5 pb-5",children:i.answer})]},i.question))}),e.jsx("h2",{children:"Make your next lesson count"}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:s,children:"“…put together a clear plan to help me sharpen my driving skills.”"}),e.jsxs("figcaption",{className:"text-sm",children:["Harriet, ",e.jsx("a",{href:s,target:"_blank",rel:"noopener noreferrer",children:"Google review excerpt"}),"."]})]}),e.jsx("p",{children:"Harriet describes an individual experience, but a clear plan is something you can ask about too. Tell Shanaya’s Driving School what feels comfortable, what still feels difficult and how much practice you can arrange. We can discuss suitable instruction and availability."}),e.jsxs("p",{children:[e.jsx("a",{href:s,target:"_blank",rel:"noopener noreferrer",children:"Read our Google reviews"})," to see how other learners describe their lessons and instructor feedback."]}),e.jsxs("p",{children:[e.jsx(r,{to:"/contact",children:"Start a conversation about your lesson plan"})," or call"," ",e.jsx("a",{href:"tel:+12505423673",children:"250-542-3673"}),". Bring your questions. You can work out your next step without guessing your entire lesson total today."]})]})},S="https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school",T="https://www.icbc.com/road-safety/crashes-happen/high-risk-driving",q={slug:"choosing-driving-school-first-time-victoria-langford",title:"Choosing a Driving School for the First Time? Here's What Actually Matters",seoTitle:"Choosing a Driving School in Victoria or Langford",description:"Compare driving schools in Victoria and Langford by instructor licensing, lesson structure, vehicle safety, scheduling, reviews, pricing and road-test preparation.",heroImage:"/why-choose/licensed-instructors.webp",author:"Shanaya's Driving School",date:"September 6, 2026",datePublished:"2026-09-06",dateModified:"2026-09-06",readTime:"9 min read",category:"Choosing a School",relatedSlugs:["how-many-driving-lessons-before-victoria-driving-test","driving-lessons-cost-victoria-bc-2026","pass-road-test"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Choosing your first driving school can feel more complicated than it should. New drivers in Victoria and Langford can find many schools offering beginner lessons and road-test preparation. The useful question is how to compare the instructor, vehicle, lesson plan, scheduling and terms before you pay."}),e.jsxs("p",{children:["ICBC's official advice is a good starting point. Its"," ",e.jsx("a",{href:S,target:"_blank",rel:"noopener noreferrer",children:"guide to choosing a driving school"})," ","says to confirm that the school is licensed under the Motor Vehicle Act and that each instructor has a professional driver training instructor licence. ICBC also recommends discussing the course outline and requesting the school's service and policy statements in writing."]}),e.jsx("h2",{children:"What to look for in a driving school"}),e.jsx("h3",{children:"1. Verify the school and instructor licences"}),e.jsx("p",{children:"Ask for the school's licence information and confirm that the person teaching you holds the required professional instructor licence. ICBC publishes a list of licensed schools, but it states that the list is not a recommendation or endorsement. A listing confirms a licensing status; it does not rank teaching quality or guarantee your result."}),e.jsx("h3",{children:"2. Find out whether lessons adapt to your pace"}),e.jsx("p",{children:"Learners do not progress on identical schedules. One person may become comfortable with steering and basic control quickly, while another needs more time before busier intersections, lane changes or highway driving."}),e.jsx("p",{children:"Ask how the instructor assesses your starting point, explains mistakes and decides when to add more difficult conditions. For nervous or first-time drivers, patience and clear reasons for each task can be as important as the task itself."}),e.jsx("h3",{children:"3. Ask about the training vehicle and dual controls"}),e.jsx("p",{children:"An instructor-side brake can provide an additional safety measure during a lesson. Confirm the type of vehicle, its dual-control equipment and any other relevant safety features before the first appointment. Also ask whether the same vehicle is normally used from one lesson to the next if vehicle familiarity matters to you."}),e.jsx("h3",{children:"4. Check actual lesson availability"}),e.jsx("p",{children:"A course only fits if you can attend it. Ask how soon lessons can begin, how often sessions are available and how confirmations or schedule changes are communicated. This is especially useful when you have school, university, work or a planned road-test date to manage."}),e.jsx("p",{children:"Reviews in the school's saved feedback include both praise for scheduling flexibility and a suggestion that communication around lesson times could be more consistent. Ask about the current process rather than assuming every learner has the same experience."}),e.jsx("h3",{children:"5. Read reviews for details"}),e.jsx("p",{children:"Look beyond the average rating. Reviews that describe what happened during a lesson can help you form better questions: Was the instructor patient? Were corrections clear? Did the learner receive useful feedback? Did the booking and pricing match what was promised?"}),e.jsx("p",{children:"Patterns across several detailed reviews are more informative than a single short comment, but reviews remain individual experiences. They do not prove a pass rate, instructor credentials, current prices or the outcome another learner will receive."}),e.jsx("h3",{children:"6. Ask how road-test preparation works"}),e.jsx("p",{children:"Depending on the learner and program, road-test preparation may address:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"observation, mirror use and shoulder checks;"}),e.jsx("li",{children:"lane changes, intersections and speed control;"}),e.jsx("li",{children:"parking and low-speed manoeuvres;"}),e.jsx("li",{children:"driving in different traffic and road conditions; and"}),e.jsx("li",{children:"a mock or assessment-style drive followed by specific feedback."})]}),e.jsx("p",{children:"Ask which items are included in the service you are buying and how the instructor identifies priorities. No school has access to an official test route, and preparation cannot guarantee a pass."}),e.jsx("h3",{children:"7. Understand the complete price"}),e.jsx("p",{children:"Request written details for:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"lesson length and number of sessions;"}),e.jsx("li",{children:"pickup and drop-off arrangements;"}),e.jsx("li",{children:"package inclusions and expiry conditions;"}),e.jsx("li",{children:"road-test preparation and test-day vehicle use;"}),e.jsx("li",{children:"cancellation, rescheduling and refund policies; and"}),e.jsx("li",{children:"taxes and any additional fees."})]}),e.jsx("p",{children:"Compare equivalent services rather than headline prices alone. ICBC specifically recommends obtaining the service and policy statements, fees, refund terms and a receipt."}),e.jsx("h2",{children:"Driving habits to build from the first lesson"}),e.jsx("h3",{children:"Check mirrors and blind spots"}),e.jsx("p",{children:"Mirror checks are part of understanding what is around the vehicle, not something reserved for a lane change. Before changing direction or road position, use the appropriate mirror and shoulder checks instead of relying on cameras or sensors alone."}),e.jsx("h3",{children:"Keep your eyes moving"}),e.jsx("p",{children:"Scan well ahead and from side to side for pedestrians, cyclists, intersections, changing signals, parked vehicles and developing traffic. Regular mirror checks keep you aware of the space behind. Good observation creates time for a smooth response."}),e.jsx("h3",{children:"Treat following distance as a safety margin"}),e.jsxs("p",{children:["ICBC's"," ",e.jsx("a",{href:T,target:"_blank",rel:"noopener noreferrer",children:"high-risk driving guidance"})," ","calls for at least two seconds in good weather and road conditions. Its driver guide increases that to three seconds on high-speed roads and four seconds in bad weather or on uneven or slippery roads. Increase the margin whenever conditions require more time."]}),e.jsx("h3",{children:"Choose a speed for the conditions"}),e.jsx("p",{children:"A posted limit does not require you to drive at that speed when rain, darkness, traffic, construction or limited visibility makes a lower speed necessary. Read the signs, monitor conditions and choose a legal speed that leaves time to identify and respond to hazards."}),e.jsx("h3",{children:"Expect other road users to make mistakes"}),e.jsx("p",{children:"Another driver may fail to signal, change lanes unexpectedly or misjudge a gap. You cannot control that choice, but you can preserve space, keep an escape option and avoid depending on another person to react perfectly."}),e.jsx("h3",{children:"Put the phone away"}),e.jsx("p",{children:"Set up navigation and music before moving, then keep the phone out of reach. Learners should also know the restrictions that apply to their licence and confirm current rules directly with ICBC."}),e.jsx("h3",{children:"Respond calmly to surprises"}),e.jsx("p",{children:"A pedestrian, sudden brake light or unexpected lane movement can tempt a new driver to freeze or make an abrupt steering input. Supervised practice helps you learn to reduce speed, check the surrounding space and choose a controlled response without trying to simulate dangerous emergencies."}),e.jsx("h2",{children:"Questions to ask before booking"}),e.jsxs("ol",{children:[e.jsx("li",{children:"Is the school licensed, and who will teach me?"}),e.jsx("li",{children:"How will the first lesson match my current experience?"}),e.jsx("li",{children:"What vehicle and dual-control equipment will I use?"}),e.jsx("li",{children:"What dates and lesson frequency are actually available?"}),e.jsx("li",{children:"What does road-test preparation include?"}),e.jsx("li",{children:"What is the full cost, including tax and optional services?"}),e.jsx("li",{children:"Can I read the service, cancellation and refund policies before paying?"})]}),e.jsx("p",{children:"The right fit is a licensed school with clear terms and instruction that helps you understand what to do, why it matters and what to practise next. Advertising size and star ratings alone cannot answer those questions."}),e.jsx("h2",{children:"Discuss your first lesson with Shanaya's"}),e.jsxs("p",{children:["Shanaya's Driving School can explain current lesson availability, vehicle arrangements, prices and how instruction may be adapted to your starting point. Review our"," ",e.jsx(r,{to:"/blog/driving-lessons-cost-victoria-bc-2026",children:"lesson-cost guide"}),", explore"," ",e.jsx(r,{to:"/courses/beginner-driving-course",children:"beginner driving lessons"}),", or"," ",e.jsx(r,{to:"/contact",children:"contact us"})," with your questions before booking."]})]})},A="https://victoriabuzz.com/2026/05/impaired-driving-suspected-in-serious-overnight-crash-on-the-malahat/",D="https://www.icbc.com/driver-licensing/driving-guides/Learn-to-Drive-Smart",P="https://www.icbc.com/driver-licensing/driving-guides/Tuning-Up-for-Drivers",R="https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",L={slug:"late-night-crash-langford-night-driving-safety",title:"A Late-Night Crash Near Langford Is a Reminder Every Driver Needs",seoTitle:"Late-Night Crash Near Langford: Safety Tips",description:"A late-night crash near Langford highlights night-driving safety for new drivers, including visibility, glare, fatigue and defensive highway habits.",heroImage:"/course-pictures/winter-driving-course.jpg",author:"Shanaya's Driving School",date:"September 6, 2026",datePublished:"2026-09-06",dateModified:"2026-09-06",readTime:"8 min read",category:"Night Driving",relatedSlugs:["mckenzie-avenue-highway-collisions-safety-lessons","six-mile-exit-pileup-lessons-student-drivers","defensive-driving"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Shortly after midnight on May 8, 2026, West Shore RCMP responded to a serious two-vehicle collision on the Trans-Canada Highway near Finlayson Arm Road, north of Langford. One driver suffered life-threatening injuries. Police reported that the other driver displayed signs of suspected impairment and that the investigation was continuing."}),e.jsxs("p",{children:["The northbound lanes between West Shore Parkway and Aspen Road were closed until about 7:10 a.m. while emergency crews and collision investigators worked at the scene. These details come from a"," ",e.jsx("a",{href:A,target:"_blank",rel:"noopener noreferrer",children:"May 8 report citing West Shore RCMP"}),". Suspected impairment is not a final finding, and the cause of the collision was not established in that report."]}),e.jsx("p",{children:"For drivers in Langford and across the West Shore, the incident is also a reason to review the parts of night driving that can be practised: visibility, speed choice, following distance, fatigue awareness and early hazard detection."}),e.jsx("h2",{children:"Why night driving can be more challenging"}),e.jsxs("p",{children:["Darkness limits how far you can see and makes distance harder to judge. Headlight glare, fatigue, wildlife and dark road edges add to the workload. ICBC's"," ",e.jsx("a",{href:D,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart guide"})," ","explains that drivers should remain able to stop within the distance they can see. That may require a speed below the posted limit."]}),e.jsx("h3",{children:"1. Reduced visibility leaves less time to respond"}),e.jsx("p",{children:"Your headlights illuminate only part of the road. Driving too fast to stop within that area is often called overdriving your headlights. Scan well ahead, keep windows and lights clean, reduce speed when visibility narrows, and increase your following distance so hazards do not force an abrupt response."}),e.jsx("h3",{children:"2. Headlight glare can affect your view"}),e.jsx("p",{children:"If an approaching vehicle's headlights create glare, avoid looking directly at them. ICBC's guidance recommends looking toward the right edge of the road until the vehicle passes. Use high beams only when appropriate and dim them for approaching road users."}),e.jsx("h3",{children:"3. Fatigue can become a serious hazard"}),e.jsx("p",{children:"Fewer vehicles do not make a tired driver safer. Fatigue reduces attention and can slow a response to hazards. If you feel drowsy, stop in a safe, appropriate place and rest. Night driving should never become a test of how long you can stay awake."}),e.jsx("h3",{children:"4. Other drivers may behave unpredictably"}),e.jsx("p",{children:"You cannot control another road user's condition or choices. Defensive driving means leaving room to respond if a vehicle drifts, brakes, changes lanes or moves unpredictably. It does not mean assuming that every unusual movement is impairment."}),e.jsx("h2",{children:"Defensive habits for a night highway drive"}),e.jsx("h3",{children:"Look farther ahead"}),e.jsx("p",{children:"Scan beyond the vehicle in front for brake lights, curves, lane changes and slowing traffic. Early information gives you time to ease off the accelerator and make a controlled decision."}),e.jsx("h3",{children:"Maintain a larger safety margin"}),e.jsx("p",{children:"Following too closely reduces the time available for braking. ICBC advises at least three seconds on high-speed roads and four seconds in bad weather or on slippery surfaces. Add more space whenever visibility, traction or traffic behaviour calls for it."}),e.jsx("h3",{children:"Keep options around your vehicle"}),e.jsx("p",{children:"Monitor the lanes beside and behind you, and avoid remaining beside another vehicle longer than necessary. Space around the vehicle can provide another option if traffic ahead stops or a neighbouring driver moves into your lane."}),e.jsx("h3",{children:"Watch for wildlife and vulnerable road users"}),e.jsx("p",{children:"Roads around Langford, Goldstream and the Malahat can combine darkness, curves and wildlife. Keep your eyes moving and scan for animals, pedestrians and cyclists rather than staring at one point ahead."}),e.jsx("h2",{children:"Why new drivers should practise after dark"}),e.jsxs("p",{children:["Being comfortable during the day does not automatically prepare a learner for glare, dark intersections and reduced depth perception. ICBC's"," ",e.jsx("a",{href:P,target:"_blank",rel:"noopener noreferrer",children:"Tuning Up for Drivers guide"})," ","recommends night practice after daytime skills have improved and suggests including at least one practice at night."]}),e.jsx("p",{children:"A supervised evening session can introduce:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"headlight use and glare management;"}),e.jsx("li",{children:"speed and following-distance adjustments;"}),e.jsx("li",{children:"dark intersections, curves and road edges;"}),e.jsx("li",{children:"changing traffic patterns and wildlife awareness; and"}),e.jsx("li",{children:"honest decisions about fatigue and whether to continue driving."})]}),e.jsx("p",{children:"Practise gradually with a qualified supervisor or licensed instructor. A learner should have reliable basic vehicle control before adding more difficult traffic or highway conditions."}),e.jsx("h2",{children:"Night driving and road-test preparation"}),e.jsxs("p",{children:["ICBC's"," ",e.jsx("a",{href:R,target:"_blank",rel:"noopener noreferrer",children:"Class 7 road-test preparation guidance"})," ","encourages practice at different times of day, in different weather and road conditions, and in unfamiliar neighbourhoods. The goal is to build skills that transfer to real driving, rather than memorizing a route."]}),e.jsx("p",{children:"A balanced plan may include lane changes, highway merging, following distance, observation and an evening drive when the learner is ready. No single session proves test readiness or guarantees a pass."}),e.jsx("h2",{children:"Build night-driving confidence before you need it"}),e.jsx("p",{children:"You cannot predict every event on the road, but you can prepare a response: maintain space, choose a speed that fits what you can see, manage glare, stay alert and identify developing hazards early."}),e.jsxs("p",{children:["Shanaya's Driving School can discuss an evening lesson for a beginner or novice driver when instructor availability, daylight hours and the learner's current ability make it suitable. Explore our ",e.jsx(r,{to:"/courses/defensive-driving-course",children:"defensive-driving instruction"})," ","or ",e.jsx(r,{to:"/contact",children:"contact the school"})," to ask what is currently available."]})]})},_="https://victoriabuzz.com/2026/08/traffic-safety-blitz-held-on-trans-canada-highway-near-helmcken-road-exit/",N="https://www.icbc.com/road-safety/crashes-happen/high-risk-driving",G="https://www.icbc.com/driver-licensing/driving-guides/Learn-to-Drive-Smart",z={slug:"mckenzie-avenue-highway-collisions-safety-lessons",title:"Two McKenzie Avenue Highway Collisions: Essential Safety Lessons for New Drivers",seoTitle:"McKenzie Avenue Collisions: New Driver Lessons",description:"Learn what two McKenzie Avenue highway collisions can teach new drivers about following distance, merging and defensive driving in Victoria, BC.",heroImage:"/landing/defensive-driving.webp",author:"Shanaya's Driving School",date:"September 6, 2026",datePublished:"2026-09-06",dateModified:"2026-09-06",readTime:"6 min read",category:"Local Road Safety",relatedSlugs:["late-night-crash-langford-night-driving-safety","six-mile-exit-pileup-lessons-student-drivers","defensive-driving"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Two separate three-vehicle collisions on the Trans-Canada Highway near McKenzie Avenue on August 18, 2026, highlighted an important safety lesson for new drivers: the space ahead of your vehicle gives you time to respond when traffic changes suddenly."}),e.jsxs("p",{children:["According to a published report based on information from Saanich Police, officers found separate crashes in the northbound and southbound lanes shortly before 6 p.m. The southbound collision closed the highway between Helmcken Road and McKenzie Avenue for about three hours. Four drivers across the two crashes were taken to hospital, and two drivers involved in the northbound crash received tickets for following too closely. Read the"," ",e.jsx("a",{href:_,target:"_blank",rel:"noopener noreferrer",children:"August 19 collision report"})," ","for the incident details. A ticket is an allegation, and the report does not establish that following distance caused every impact."]}),e.jsx("h2",{children:"Why the McKenzie Avenue interchange demands attention"}),e.jsx("p",{children:"The interchange brings together highway traffic, merging vehicles, exits and changing speeds within a short distance. A comfortable gap can disappear when another vehicle enters your lane, traffic queues develop or drivers brake for congestion ahead."}),e.jsx("p",{children:"For a learner, the answer is not to match the smallest gap other drivers accept. Scan beyond the vehicle directly ahead, identify brake lights and merging traffic early, and preserve enough space to adjust smoothly. These habits matter throughout Saanich, View Royal and the rest of Greater Victoria."}),e.jsx("h2",{children:"Use the right following distance for the conditions"}),e.jsxs("p",{children:["ICBC's"," ",e.jsx("a",{href:N,target:"_blank",rel:"noopener noreferrer",children:"guidance on following distance"})," ","says to leave at least two seconds in good weather and road conditions. The"," ",e.jsx("a",{href:G,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart guide"})," ","increases that guidance to three seconds on high-speed roads and four seconds in bad weather or on uneven or slippery roads."]}),e.jsx("p",{children:"To measure a three-second highway gap:"}),e.jsxs("ol",{children:[e.jsx("li",{children:"Choose a fixed object ahead, such as a sign, pole or overpass."}),e.jsx("li",{children:"Begin counting when the rear of the vehicle ahead passes it."}),e.jsx("li",{children:"Your vehicle should reach the same object no sooner than three seconds later."})]}),e.jsx("p",{children:"Increase the gap when visibility or traction is reduced, when traffic is unpredictable, or when a large vehicle blocks your view. The measured time matters more than the apparent number of car lengths because the physical distance grows as your speed increases."}),e.jsx("h2",{children:"Merge zones require more space"}),e.jsx("p",{children:"Busy merge areas can make drivers feel pressure to close the gap so another vehicle cannot enter. That choice removes part of your safety margin just when traffic movements are least predictable. A driver may merge, change lanes, slow for an exit or stop for a queue that you cannot yet see."}),e.jsx("p",{children:"Ease off the accelerator when you need to rebuild space. Avoid accelerating toward a closing gap, and do not depend on braking at the last moment. A usable gap protects you from your own misjudgment and gives you more room when another road user makes a mistake."}),e.jsx("h2",{children:"How a chain-reaction collision develops"}),e.jsx("p",{children:"A multi-vehicle crash can begin when one vehicle brakes or changes direction unexpectedly. The next driver reacts late, and each closely following driver has even less time and space. At highway speed, the delay between seeing a problem and beginning to brake uses part of the available stopping distance before the vehicle starts slowing."}),e.jsx("p",{children:"Defensive driving uses space as a buffer. Look well ahead, keep an appropriate gap, monitor the traffic behind and beside you, and avoid staying where another driver's single move leaves you without a safe option."}),e.jsx("h2",{children:"Practise highway skills gradually"}),e.jsx("p",{children:"Following-distance rules are simple to read and harder to apply consistently in moving traffic. Supervised practice can help a new driver learn to maintain a gap, adjust speed, enter and leave merge zones, identify hazards earlier and respond smoothly when traffic changes."}),e.jsx("p",{children:"Start on roads that match your current ability and add complexity as your observation and vehicle control become reliable. A qualified supervisor or licensed driving instructor can help you choose suitable conditions. No lesson or article can recreate a collision safely or guarantee a road-test result."}),e.jsx("h2",{children:"Build defensive driving habits for Victoria-area roads"}),e.jsx("p",{children:"These McKenzie Avenue collisions are a reminder that preparation, awareness and space work together. The practical lesson is repeatable: scan farther ahead, leave more room as speed or risk increases, and restore your safety margin after a vehicle merges in front of you."}),e.jsxs("p",{children:["Shanaya's Driving School offers driving instruction for city traffic, highway conditions, merging, hazard awareness and road-test preparation, subject to instructor availability and the learner's current skill level. Explore our"," ",e.jsx(r,{to:"/courses/defensive-driving-course",children:"Defensive Driving Course"})," or"," ",e.jsx(r,{to:"/contact",children:"contact us"})," to discuss a suitable lesson."]})]})},a="https://www.icbc.com/driver-licensing/new-drivers/For-parents-of-teen-drivers",M="https://www.icbc.com/driver-licensing/new-drivers/you-have-a-class-7l-licence",o="https://www.icbc.com/assets/en/7piwqMyGnoxb1F6ONZSMqr/tuneup-complete.pdf",W="https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",O="https://www.icbc.com/insurance/products-coverage/unlisted-driver-protection",g=[{question:"Who can supervise a teen with a Class 7L licence in B.C.?",answer:"Until October 19, 2026, a supervisor must be at least 25, hold a valid Class 1–5 licence and sit in the front passenger seat. ICBC says the minimum age becomes 22 on that date. Check the teen’s licence and ICBC’s current restrictions before driving."},{question:"How can parents make driving practice less stressful?",answer:"Choose one skill and a familiar route, keep instructions short, and save non-urgent feedback for a parked debrief. End the drive if either person becomes too upset or tired to continue safely."},{question:"Should a parent sit in during a teen’s driving lesson?",answer:"Ask the school and your teen before booking because passenger policies and lesson goals differ. Even when a parent does not ride along, they can ask the instructor for practice priorities that the teen agrees may be shared."},{question:"When might professional instruction help a teen learner?",answer:"It may help when family practice repeatedly becomes tense, the parent is unsure how to explain a skill, or the learner needs structured feedback before moving into more complex traffic. Lessons complement legal supervised practice and do not guarantee road-test success."}],F={slug:"parents-teen-drivers-victoria-bc-guide",title:"For Parents of Teen Drivers in Victoria: A Practical Guide to Safer Practice",seoTitle:"Parents of Teen Drivers in Victoria: A Practical Guide",description:"Help your teen learn to drive in Victoria with current B.C. learner rules, calmer coaching, a staged practice plan and signs that outside instruction may help.",heroImage:"/course-pictures/beginner-driving-course.jpg",author:"Shanaya's Driving School",date:"September 7, 2026",datePublished:"2026-09-07",dateModified:"2026-09-07",readTime:"7 min read",category:"Teen Driver Guide",faqs:g,relatedSlugs:["how-many-driving-lessons-before-victoria-driving-test","choosing-driving-school-first-time-victoria-langford","icbc-road-test-tips-victoria"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Teaching your teen to drive can turn an ordinary trip through Victoria into a tense family moment. You are explaining a skill while your teen processes signs, pedals, mirrors and your voice at the same time."}),e.jsx("p",{children:"A better approach is to make each drive small, planned and calm. Check the licence restrictions first, choose one main skill, match the route to your teen's current ability and discuss feedback after the car is safely parked. Your role is to provide legal supervision and useful practice, not to recreate a road test on every trip."}),e.jsxs("p",{children:["ICBC describes the same mix of excitement and worry in its"," ",e.jsx("a",{href:a,target:"_blank",rel:"noopener noreferrer",children:"information for parents of teen drivers"}),":"]}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:a,children:"“Having a teen who's learning to drive can be an exciting and stressful time.”"}),e.jsxs("figcaption",{className:"text-sm",children:["ICBC, ",e.jsx("a",{href:a,target:"_blank",rel:"noopener noreferrer",children:"For parents of teen drivers"}),"."]})]}),e.jsx("h2",{children:"Start with the rules that apply to your teen"}),e.jsxs("p",{children:["For a teen with a B.C. Class 7L learner's licence, supervision is a legal condition of driving. As of September 7, 2026, ICBC's"," ",e.jsx("a",{href:M,target:"_blank",rel:"noopener noreferrer",children:"Class 7L restrictions"})," ","require a qualified supervisor who is at least 25 and holds a valid Class 1–5 licence. The supervisor must sit beside the learner in the front passenger seat."]}),e.jsx("p",{children:"The same current restriction page says a Class 7L driver must:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"display the red L sign on the back of the vehicle;"}),e.jsx("li",{children:"have zero alcohol or drugs in their blood while driving;"}),e.jsx("li",{children:"avoid all cellphones and other electronic devices, including hands-free devices;"}),e.jsx("li",{children:"drive only between 5 a.m. and midnight; and"}),e.jsx("li",{children:"carry only one passenger in addition to the qualified supervisor."})]}),e.jsxs("p",{children:["These rules are changing soon. ICBC says that on ",e.jsx("strong",{children:"October 19, 2026"}),", the minimum supervisor age will become 22 and immediate-family passengers will receive an exemption from the one-passenger limit, subject to the published conditions. Review the"," ",e.jsx("a",{href:W,target:"_blank",rel:"noopener noreferrer",children:"official Graduated Licensing Program changes"})," ","before a drive on or after that date. The restriction printed on the licence and ICBC's current guidance should settle any uncertainty."]}),e.jsxs("p",{children:["Before using the family vehicle, also confirm that your teen is properly listed for its insurance. ICBC explains the potential consequence when an unlisted household member causes a crash on its"," ",e.jsx("a",{href:O,target:"_blank",rel:"noopener noreferrer",children:"unlisted driver protection page"}),". Ask an Autoplan broker about your own policy rather than assuming another family's setup applies to yours."]}),e.jsx("h2",{children:"Use a five-minute plan before every practice drive"}),e.jsx("p",{children:"A short conversation before moving the car prevents many arguments later. Agree on four things: the main skill, the route, the conditions and the words you will use if the teen must slow down or stop. Either person can end the session if concentration or patience is slipping."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Teen driving practice plan",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"A simple progression for family-supervised practice in Greater Victoria."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Stage"}),e.jsx("th",{scope:"col",children:"Possible focus"}),e.jsx("th",{scope:"col",children:"Move on when"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Quiet start"}),e.jsx("td",{children:"Seat and mirror setup, smooth starts and stops, steering and basic observation."}),e.jsx("td",{children:"The teen can control the car without hurried reminders."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Familiar streets"}),e.jsx("td",{children:"Intersections, signs, parked vehicles, pedestrians and speed choices."}),e.jsx("td",{children:"Checks and decisions become consistent on several drives."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"More traffic"}),e.jsx("td",{children:"Lane changes, busier junctions, cyclists and changing speed limits."}),e.jsx("td",{children:"The teen keeps safe margins while handling the added workload."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Varied conditions"}),e.jsx("td",{children:"Rain, darkness, hills and higher-speed roads, introduced separately."}),e.jsx("td",{children:"The teen adapts without losing the habits built earlier."})]})]})]})}),e.jsx("p",{children:"These are planning examples, not a fixed curriculum or readiness test. Victoria-area conditions can change quickly between a quiet residential street, a busy cycling corridor and the Trans-Canada Highway. Increase only one kind of difficulty at a time. A learner who is still working on smooth braking does not also need an unfamiliar route in heavy rain."}),e.jsx("h2",{children:"Coach without turning the passenger seat into a conflict"}),e.jsx("p",{children:"Give directions early and use the same short phrases each time. “At the next safe place, pull over” is easier to process than a long explanation delivered near the turn. If there is no immediate danger, make a note and discuss it once parked."}),e.jsxs("p",{children:["ICBC's ",e.jsx("a",{href:o,target:"_blank",rel:"noopener noreferrer",children:"Tuning up for Drivers manual"})," ","treats communication and patience as part of being a suitable supervisor. Its learning cycle is practical: discuss the exercise, demonstrate it, let the learner try, give feedback and allow time to practise. The manual also asks a candid question:"]}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:`${o}#page=9`,children:"“Can your relationship survive the frustrations of driving practice?”"}),e.jsxs("figcaption",{className:"text-sm",children:["ICBC, ",e.jsx("a",{href:`${o}#page=9`,target:"_blank",rel:"noopener noreferrer",children:"Tuning up for Drivers, page 4 of the guide"}),"."]})]}),e.jsx("p",{children:"If the answer feels uncertain, change the process. Shorten the drive, use one supervisor consistently, or let an instructor introduce a difficult skill before practising it as a family."}),e.jsx("h2",{children:"Track progress by skills, not by pressure"}),e.jsxs("p",{children:["ICBC's supervisor manual suggests planning about 60 hours of practice before the Class 7 road test. This is practice guidance, not a required number of paid lessons, and reaching an hour total does not prove readiness. Our"," ",e.jsx(r,{to:"/blog/how-many-driving-lessons-before-victoria-driving-test",children:"guide to lesson and practice planning"})," ","explains that distinction in detail."]}),e.jsx("p",{children:"Keep a simple log with the date, conditions, route type, skill practised and one next step. “Drove for 40 minutes” says little. “Chose safe gaps at familiar intersections; still needed two shoulder-check reminders” gives the next drive a clear purpose."}),e.jsx("p",{children:"Look for patterns across several drives:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"Does your teen notice hazards without being prompted?"}),e.jsx("li",{children:"Can they manage speed and following space when traffic changes?"}),e.jsx("li",{children:"Do familiar skills remain reliable on an unfamiliar road?"}),e.jsx("li",{children:"Can they accept feedback and apply it on the next attempt?"}),e.jsx("li",{children:"Are you still giving frequent instructions or intervening for safety?"})]}),e.jsx("p",{children:"Confidence matters, but confidence and independent driving ability are not identical. Delay difficult conditions while control or observation depends on constant coaching."}),e.jsx("h2",{children:"When an instructor can support the family practice plan"}),e.jsx("p",{children:"Outside instruction can be useful when the same disagreement keeps returning, when you are unsure how to explain a skill, or when your teen is ready to add complexity but family practice has stalled. Ask for specific priorities to carry into later supervised drives."}),e.jsxs("p",{children:["Ask how the instructor communicates progress, whether practice suggestions can be shared with a parent with the teen's agreement, and how the school decides when to introduce busier roads. Our guide to"," ",e.jsx(r,{to:"/blog/choosing-driving-school-first-time-victoria-langford",children:"choosing a driving school in Victoria or Langford"})," ","gives you a fuller set of questions."]}),e.jsx("p",{children:"One parent, Tanya Frenette, described her own family's experience with Shanaya's this way:"}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:s,children:"“As a parent, I like the emphasis on safety and feel very comfortable letting them drive.”"}),e.jsxs("figcaption",{className:"text-sm",children:["Tanya Frenette · excerpt from an individual Google review ·"," ",e.jsx("a",{href:s,target:"_blank",rel:"noopener noreferrer",children:"read reviews on Google"}),"."]})]}),e.jsx("p",{children:"That is one parent's account, not a promise about another learner's progress. It does show a useful standard to ask for: clear attention to safety, feedback the family can understand and a pace that fits the learner."}),e.jsx("h2",{children:"Give your teen more ownership as their skills grow"}),e.jsx("p",{children:"Let your teen help choose the practice goal and describe what felt difficult. Ask them to talk through what they noticed rather than supplying every answer. Over time, move from instructions to questions: “What is changing ahead?” or “Where is your safe space?” The goal is for the learner to make decisions before the supervisor has to speak."}),e.jsxs("p",{children:["Road-test preparation comes later in that process. When your teen is approaching the Class 7 test, use our ",e.jsx(r,{to:"/blog/icbc-road-test-tips-victoria",children:"Victoria road-test guide"})," to review skills and local conditions without relying on supposed test routes or pass promises."]}),e.jsx("h2",{children:"A calmer next drive starts before the engine does"}),e.jsx("p",{children:"Pick one skill, choose a suitable route and agree on how you will communicate. Follow the current licence and insurance conditions, then finish with one thing that improved and one thing to practise next. That rhythm gives a teen room to learn and gives a parent a clearer role than watching every mistake at once."}),e.jsxs("p",{children:["If family practice needs a fresh set of eyes, explore our"," ",e.jsx(r,{to:"/beginner-driving-lessons-victoria",children:"beginner driving lessons in Victoria"})," or"," ",e.jsx(r,{to:"/contact",children:"tell us where your teen is getting stuck"}),". You can also call"," ",e.jsx("a",{href:"tel:+12505423673",children:"250-542-3673"})," or email"," ",e.jsx("a",{href:"mailto:book@drivingschoolbc.ca",children:"book@drivingschoolbc.ca"}),". We can discuss a suitable next step around their present skills and your family's practice plan."]}),e.jsx("h2",{children:"Frequently asked questions"}),g.map(i=>e.jsxs("section",{children:[e.jsx("h3",{children:i.question}),e.jsx("p",{children:i.answer})]},i.question))]})},V="https://www.pqbnews.com/news/video-4-sent-to-hospital-after-car-drives-into-oncoming-island-traffic-7879389",U="https://www.icbc.com/driver-licensing/driving-guides/Learn-to-Drive-Smart",E={slug:"six-mile-exit-pileup-lessons-student-drivers",title:"What a Four-Vehicle Collision Near Six Mile Exit Can Teach Student Drivers",seoTitle:"Six Mile Collision: Lessons for Student Drivers",description:"A four-vehicle collision near Six Mile exit offers practical lessons for student drivers about following distance, hazard awareness and highway practice.",heroImage:"/course-pictures/advanced-driving-course.jpg",author:"Shanaya's Driving School",date:"September 6, 2026",datePublished:"2026-09-06",dateModified:"2026-09-06",readTime:"6 min read",category:"Highway Driving",relatedSlugs:["mckenzie-avenue-highway-collisions-safety-lessons","late-night-crash-langford-night-driving-safety","defensive-driving"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Rush-hour traffic on the Trans-Canada Highway near the Six Mile Road exit can already feel demanding for a new driver. On March 12, 2025, a four-vehicle collision near the exit closed both directions for about an hour, left northbound lanes closed until after midnight and sent all four drivers to hospital."}),e.jsxs("p",{children:["West Shore RCMP said two drivers suffered critical, life-threatening injuries and two had non-life-threatening injuries. Police believed a southbound sedan crossed the centre median into northbound traffic, while the investigation into the cause continued. The"," ",e.jsx("a",{href:V,target:"_blank",rel:"noopener noreferrer",children:"published collision report"})," ","also states that impairment had been ruled out at that stage."]}),e.jsx("p",{children:"For student drivers, the lesson is not to speculate about responsibility. It is to understand how quickly one impact can create several moving hazards and why space, observation and controlled decisions matter at highway speeds."}),e.jsx("h2",{children:"How one crash can involve several vehicles"}),e.jsx("p",{children:"An initial collision can leave a vehicle stopped, spinning or moving across a travel lane. Approaching drivers may suddenly face more than one hazard, with little time to brake or change position. A following driver's available response depends partly on what they saw before the collision and how much space they preserved."}),e.jsx("p",{children:"This is why following distance is central to defensive driving. Space ahead gives you time to identify a developing problem and reduce speed while maintaining control. The aim is to avoid reaching a point where every possible response is abrupt."}),e.jsx("h2",{children:"Build useful highway habits before an emergency"}),e.jsx("h3",{children:"Keep track of the space around you"}),e.jsx("p",{children:"Know what is ahead, beside and behind your vehicle. Avoid travelling for long periods in another driver's blind spot, and notice whether an adjacent lane or shoulder is occupied. This awareness helps you make an informed decision if traffic ahead changes suddenly."}),e.jsx("h3",{children:"Look toward a clear path"}),e.jsxs("p",{children:["ICBC's"," ",e.jsx("a",{href:U,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart guide"})," ","teaches drivers to look in the direction they want to go. Fixating on an object can interfere with steering control. Keep scanning so your attention includes the safest available path and the road users around it."]}),e.jsx("h3",{children:"Preserve space before you need it"}),e.jsx("p",{children:"ICBC recommends at least three seconds of following distance on high-speed roads and four seconds in bad weather or on uneven or slippery surfaces. If another vehicle enters your gap, ease off and restore the margin instead of following it closely."}),e.jsx("h3",{children:"Use braking and steering with control"}),e.jsx("p",{children:"A driver's safest response depends on speed, road conditions, surrounding traffic and the space available. Braking firmly may be necessary; steering around a hazard is only an option when the path is known to be clear and the vehicle can remain controlled. Do not practise emergency swerves in ordinary traffic. Learn emergency strategies from ICBC's guide and an appropriately qualified instructor in a suitable environment."}),e.jsx("h2",{children:"Why gradual highway practice matters"}),e.jsx("p",{children:"Highway driving combines speed control, merging, lane changes, mirror checks, shoulder checks, following distance and hazard perception. A learner who has practised mainly on quiet residential streets may find that workload overwhelming if every element is introduced at once."}),e.jsx("p",{children:"Build in stages. Begin with reliable vehicle control and observation, then practise higher speeds and simpler merges before adding heavier traffic. The conditions should match the learner's ability, the supervisor's qualifications and the restrictions on the learner's licence."}),e.jsx("h2",{children:"What supervised instruction can cover"}),e.jsx("p",{children:"A lesson should never recreate the danger of a major collision. It can help a student develop the ordinary habits that create more time and options when something unexpected occurs:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"entering a highway and matching traffic speed safely;"}),e.jsx("li",{children:"maintaining and restoring an appropriate following gap;"}),e.jsx("li",{children:"checking mirrors and blind spots before changing lanes;"}),e.jsx("li",{children:"scanning beyond the nearest vehicle for developing hazards; and"}),e.jsx("li",{children:"reducing speed smoothly while monitoring surrounding traffic."})]}),e.jsx("p",{children:"These skills also support road-test preparation because they show observation, space margin, speed control, steering and communication. They do not guarantee a pass, and a learner's test may not include highway driving."}),e.jsx("h2",{children:"The practical lesson from the Six Mile collision"}),e.jsx("p",{children:"A serious multi-vehicle crash shows how quickly conditions can change. Student drivers can respond by building habits that apply on every drive: scan beyond the vehicle ahead, leave a suitable gap, understand the space around the car, remove distractions and add highway complexity gradually."}),e.jsxs("p",{children:["If you are comfortable on quiet streets but not yet ready for heavier traffic, discuss your starting point with a licensed driving instructor. Shanaya's Driving School can explain current highway and defensive-driving lesson options in the Victoria and Langford area, subject to learner readiness and instructor availability. Explore the"," ",e.jsx(r,{to:"/courses/advanced-driving-course",children:"Advanced Driving Course"})," or"," ",e.jsx(r,{to:"/contact",children:"contact us"})," to ask what fits your experience."]})]})},n={learnToDriveSmart:"https://www.icbc.com/driver-licensing/driving-guides/Learn-to-Drive-Smart",practiceTest:"https://www.icbc.com/driver-licensing/new-drivers/practice-knowledge-test",getYourL:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-L",onlineTest:"https://www.icbc.com/driver-licensing/new-drivers/online-knowledge-test"},K=[{question:"What should I study first for the B.C. knowledge test?",answer:"Start with ICBC's Learn to Drive Smart guide. Work through signs, signals and road markings; rules of the road; See-Think-Do; sharing the road; personal strategies; emergency strategies; and the licensing chapter before relying on practice questions."},{question:"Are practice questions enough on their own?",answer:"No. Use them to find weak areas, then return to the official guide and explain the rule in your own words. Remembering an answer is less useful than recognizing the same rule in a different situation."},{question:"How do I know when I am ready to take the knowledge test?",answer:"Look for consistent understanding across mixed topics. You should be able to explain why an answer is correct, identify what changes in a new scenario and complete practice without depending on memorized question order."}],H={slug:"knowledge-test-practice-victoria-what-to-study",title:"Knowledge Test Practice Victoria: What to Study Before Your ICBC Test",seoTitle:"ICBC Knowledge Test: What to Study in Victoria",description:"Use this focused B.C. knowledge-test study map to cover road signs, rules, hazards and practice questions without relying on memorization.",heroImage:"/why-choose/knowledge-test-prep.webp",author:"Shanaya's Driving School",date:"October 8, 2026",datePublished:"2026-10-08",dateModified:"2026-10-08",readTime:"7 min read",category:"Knowledge Test",faqs:K,relatedSlugs:["knowledge-test-practice-victoria-common-questions","knowledge-test-practice-langford-road-signs","knowledge-test-practice-langford-confidence"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["If you are preparing for a passenger-vehicle knowledge test in Victoria, begin with the material ICBC says to study: ",e.jsx("a",{href:n.learnToDriveSmart,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart"}),". Practice questions are useful after that foundation because they show where your understanding is still uneven."]}),e.jsx("p",{children:"This guide gives you a study map rather than another bank of unofficial questions. It is intended for Class 5 and 7 passenger-vehicle knowledge preparation. Commercial and motorcycle applicants need the guide for their licence class."}),e.jsx("h2",{children:"Start with the official study source"}),e.jsx("p",{children:"ICBC describes Learn to Drive Smart as the guide most commonly used by new drivers to prepare for the knowledge test. The guide can be read as one document or chapter by chapter. Use the current version from ICBC so an older download does not become your only source."}),e.jsx("p",{children:"Do not try to memorize every page in one sitting. Read a section, write down the decision it asks a driver to make, and connect that decision to a road situation. That turns a rule into something you can recognize when a question is worded differently."}),e.jsx("h2",{children:"Use this seven-part study map"}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Knowledge test study map",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"Study each topic for meaning, driver action and changing conditions."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Topic"}),e.jsx("th",{scope:"col",children:"What to learn"}),e.jsx("th",{scope:"col",children:"How to check yourself"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Signs and markings"}),e.jsx("td",{children:"What the sign, signal or road marking communicates."}),e.jsx("td",{children:"State the action it requires before looking at an answer."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Rules of the road"}),e.jsx("td",{children:"Intersections, right-of-way, lane use, speed and parking rules."}),e.jsx("td",{children:"Identify every road user and traffic control in a scenario."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"See-Think-Do"}),e.jsx("td",{children:"How observation leads to a safe decision and response."}),e.jsx("td",{children:"Name the hazard, options and safest lawful action."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Sharing the road"}),e.jsx("td",{children:"Responsibilities around pedestrians, cyclists, large vehicles and other road users."}),e.jsx("td",{children:"Explain how space and visibility change."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Personal strategies"}),e.jsx("td",{children:"Attention, emotions, fatigue and impairment risks."}),e.jsx("td",{children:"Choose the action that removes or reduces the risk."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Emergencies"}),e.jsx("td",{children:"How to respond when ordinary driving conditions break down."}),e.jsx("td",{children:"Separate prevention from the immediate response."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Your licence"}),e.jsx("td",{children:"Licence stages, responsibilities and restrictions that apply to the question."}),e.jsx("td",{children:"Check the current ICBC page when a rule may have changed."})]})]})]})}),e.jsx("h2",{children:"Study road signs as decisions, not pictures"}),e.jsx("p",{children:"A sign question is not only asking whether you remember a name. Ask three things: what does the sign communicate, who or what could be affected, and what should the driver do next? Group signs by purpose, then mix the groups once recognition becomes easier."}),e.jsxs("p",{children:["ICBC provides a road-sign practice option through its ",e.jsx("a",{href:n.practiceTest,target:"_blank",rel:"noopener noreferrer",children:"official practice-test page"}),". Our ",e.jsx(r,{to:"/blog/knowledge-test-practice-langford-road-signs",children:"road-sign and rules study guide"})," explains how to turn each missed sign into a useful review note."]}),e.jsx("h2",{children:"Build a mistake log that points back to the rule"}),e.jsx("p",{children:"For each uncertain or incorrect practice answer, record the topic, what you misunderstood, the rule in the official guide and one clue you should notice next time. Avoid copying the answer alone. Your note should still help when a later question uses different details."}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Topic:"})," the section of the guide involved."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Missed clue:"})," the sign, road user, condition or word that changed the decision."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Rule:"})," your short explanation based on the official source."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Next check:"})," one new scenario you can use to test the same idea."]})]}),e.jsx("h2",{children:"Move from topic practice to mixed practice"}),e.jsx("p",{children:"Topic practice is helpful while you are learning. Mixed practice is helpful when you need to recognize which rule applies without being told the category. Use both. If your mixed results reveal the same weakness more than once, return to that chapter before doing more random questions."}),e.jsxs("p",{children:["ICBC says its passenger-vehicle knowledge test has 50 multiple-choice questions and requires 40 correct answers to pass. Treat that threshold as the test requirement, not as a reason to ignore material you find difficult. Review ICBC's ",e.jsx("a",{href:n.getYourL,target:"_blank",rel:"noopener noreferrer",children:"current Get your L instructions"})," before test day."]}),e.jsx("h2",{children:"Use a final readiness checklist"}),e.jsxs("ul",{children:[e.jsx("li",{children:"I have studied the current Learn to Drive Smart guide."}),e.jsx("li",{children:"I can explain signs and rules instead of naming answers from memory."}),e.jsx("li",{children:"I have reviewed repeated mistakes by topic."}),e.jsx("li",{children:"I can work through mixed scenarios without rushing."}),e.jsx("li",{children:"I have checked ICBC's current test and licensing instructions."})]}),e.jsxs("p",{children:["For the application process, fees, identification and online-versus-in-person options, use our ",e.jsx(r,{to:"/knowledge-test-guide",children:"B.C. Class 7 knowledge-test guide"}),". If you want structured support, review the ",e.jsx(r,{to:"/courses/knowledge-test-prep-course",children:"Knowledge Test Prep Course"})," or contact the school to confirm current availability."]})]})},Y=[{question:"Should I memorize ICBC practice questions?",answer:"No. Use practice questions to identify the rule being tested and the clues that make it apply. Memorizing one wording can fail when the same principle appears in a different scenario."},{question:"What should I do after choosing a wrong answer?",answer:"Name the topic, find the rule in Learn to Drive Smart, explain why your choice was wrong and create one changed scenario that uses the same principle. Then revisit the topic later rather than immediately repeating the same answer."},{question:"How can I avoid rushing through scenario questions?",answer:"Read the situation before the options. Identify the road environment, traffic controls, road users and changing conditions, then decide what a safe and lawful driver needs to do."}],J={slug:"knowledge-test-practice-victoria-common-questions",title:"Knowledge Test Practice Victoria: How to Prepare for Common ICBC Test Questions",seoTitle:"How to Answer ICBC Knowledge Test Questions",description:"Learn a repeatable method for B.C. knowledge-test scenarios, road-sign questions and mistake review without memorizing answer patterns.",heroImage:"/course-pictures/knowledge-test-prep-course.jpg",author:"Shanaya's Driving School",date:"October 8, 2026",datePublished:"2026-10-08",dateModified:"2026-10-08",readTime:"7 min read",category:"Knowledge Test",faqs:Y,relatedSlugs:["knowledge-test-practice-victoria-what-to-study","knowledge-test-practice-langford-road-signs","knowledge-test-practice-langford-confidence"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["The most useful way to prepare for common ICBC knowledge-test questions is to learn how to identify the rule a scenario is testing. Start with ICBC's ",e.jsx("a",{href:n.learnToDriveSmart,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart"}),", then use practice questions to find gaps—not to memorize a sequence of answers."]}),e.jsxs("p",{children:["This article focuses on question-solving technique. For a topic-by-topic syllabus, use our",e.jsx(r,{to:"/blog/knowledge-test-practice-victoria-what-to-study",children:" Victoria knowledge-test study map"}),"."]}),e.jsx("h2",{children:"Use the four-pass method for scenario questions"}),e.jsxs("ol",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Set the scene:"})," identify the road type, intersection, lane or parking situation."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Mark the controls:"})," note signs, signals, markings and any stated restriction."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Find the people and hazards:"})," include pedestrians, cyclists and vehicles you may not immediately cross."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Choose the safe lawful action:"})," decide what the driver should do before comparing the options."]})]}),e.jsx("p",{children:"This method slows down the part of the process where small words are often missed. It also stops an attractive answer from deciding your interpretation of the question."}),e.jsx("h2",{children:"Separate the general rule from the changing detail"}),e.jsx("p",{children:"Two questions may involve the same principle but change the traffic control, weather, visibility or road user. Ask which detail actually changes the driver's decision. If none of the details you noticed affect your answer, reread the question before committing."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Question review examples",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"Use the question type to choose a review method."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Question type"}),e.jsx("th",{scope:"col",children:"First check"}),e.jsx("th",{scope:"col",children:"Useful review note"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Sign or marking"}),e.jsx("td",{children:"Meaning and required response."}),e.jsx("td",{children:"Sign → meaning → driver action."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Intersection"}),e.jsx("td",{children:"Traffic controls, arrival, direction and vulnerable road users."}),e.jsx("td",{children:"Draw the movements before choosing."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Speed or following"}),e.jsx("td",{children:"Posted rule plus conditions and available space."}),e.jsx("td",{children:"What condition requires a larger margin?"})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Licence or restriction"}),e.jsx("td",{children:"The licence class and current ICBC rule."}),e.jsx("td",{children:"Link to the current official instruction."})]})]})]})}),e.jsx("h2",{children:"Use elimination carefully"}),e.jsx("p",{children:"Elimination helps only when you can explain why an option conflicts with the rule or the facts. Do not reject an answer because it feels unfamiliar. Remove options for a stated reason, then compare what remains with the official guidance."}),e.jsx("p",{children:"Watch for absolute wording such as “always” or “never,” but do not assume an absolute word automatically makes an option wrong. Some rules are stated absolutely. The source—not a test-taking trick—decides."}),e.jsx("h2",{children:"Review a mistake in four lines"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Question topic:"})," the skill or rule involved."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"My mistake:"})," the detail I ignored or misunderstood."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Correct rule:"})," a short explanation from the official guide."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Transfer:"})," how the same rule would apply if one detail changed."]})]}),e.jsx("p",{children:"Wait before repeating the same item. An immediate retry may test short-term memory rather than understanding. Mix the topic into a later session and see whether you can still explain the choice."}),e.jsx("h2",{children:"Practise with official materials"}),e.jsxs("p",{children:["ICBC says its ",e.jsx("a",{href:n.practiceTest,target:"_blank",rel:"noopener noreferrer",children:"online practice questions"})," are based on the real test and can be taken repeatedly. That does not mean the practice set is an answer key for every question you may receive. Pair it with the guide and the road-sign practice option linked on ICBC's page."]}),e.jsx("p",{children:"If a third-party question conflicts with ICBC's current material, use the official source for the rule and remove the questionable item from your study set. Shanaya's own practice tool is supplemental and is not supplied, reviewed or endorsed by ICBC."}),e.jsx("h2",{children:"Prepare for the format without letting the clock lead"}),e.jsx("p",{children:"ICBC's current passenger-vehicle test requires 40 correct answers out of 50. Its online-test page gives a 45-minute testing period. During preparation, build accuracy first, then add timed mixed practice so you can read carefully without treating every question as an emergency."}),e.jsxs("p",{children:["Review the ",e.jsx("a",{href:n.onlineTest,target:"_blank",rel:"noopener noreferrer",children:"current online-test instructions"})," if you plan to test remotely, or use our",e.jsx(r,{to:"/knowledge-test-guide",children:" knowledge-test process guide"})," for online and in-person steps."]}),e.jsx("h2",{children:"Use a short final-session checklist"}),e.jsxs("ul",{children:[e.jsx("li",{children:"Review repeated mistake topics, not every page again."}),e.jsx("li",{children:"Complete one mixed session using the four-pass method."}),e.jsx("li",{children:"Explain uncertain rules from the official guide."}),e.jsx("li",{children:"Stop cramming when your attention drops."}),e.jsx("li",{children:"Confirm the current ICBC instructions for your chosen test method."})]})]})},$=[{question:"What is the first step for a new knowledge-test learner?",answer:"Confirm which licence class and knowledge test apply to you, then use the current official guide for that class. For a passenger-vehicle Class 5 or 7 test, begin with ICBC's Learn to Drive Smart."},{question:"How long should I study before taking the test?",answer:"There is no single number of days that proves readiness. Use short sessions, track weak topics and move to mixed practice only after you can explain the main rules. Schedule based on consistent understanding rather than a rushed deadline."},{question:"Can I take the B.C. passenger-vehicle knowledge test online?",answer:"ICBC currently offers online and in-person passenger-vehicle knowledge tests. Eligibility, equipment, identification and follow-up licensing steps apply, so check ICBC's current online-test page before registering."}],Q={slug:"knowledge-test-practice-langford-step-by-step",title:"Knowledge Test Practice Langford: A Step-by-Step Guide for New Drivers",seoTitle:"ICBC Knowledge Test Study Plan for Langford Learners",description:"Follow a practical four-stage plan for studying B.C. road rules, using practice questions and preparing for an ICBC knowledge test.",heroImage:"/Course-pictures-updated/Knowledge test prep course whatsapp catalogue_.webp",author:"Shanaya's Driving School",date:"October 8, 2026",datePublished:"2026-10-08",dateModified:"2026-10-08",readTime:"7 min read",category:"Knowledge Test",faqs:$,relatedSlugs:["knowledge-test-practice-victoria-what-to-study","knowledge-test-practice-langford-road-signs","knowledge-test-practice-langford-confidence"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"A new driver in Langford does not need to study everything at once. A useful plan moves through four stages: confirm the correct test, learn from the official guide, use practice questions to find gaps, and prepare the practical details for test day."}),e.jsx("p",{children:"This guide is for passenger-vehicle knowledge preparation. ICBC publishes different study material for motorcycles and commercial licence classes, so confirm your own test before following a Class 5 or 7 plan."}),e.jsx("h2",{children:"Stage 1: confirm your path and collect the right sources"}),e.jsxs("p",{children:["Start with ICBC's ",e.jsx("a",{href:n.getYourL,target:"_blank",rel:"noopener noreferrer",children:"Get your L page"})," and ",e.jsx("a",{href:n.learnToDriveSmart,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart"}),". The first tells you how the passenger-vehicle learner process works; the second is the official study guide. Save the current links instead of depending on an old downloaded list or an answer sheet from someone else."]}),e.jsxs("ul",{children:[e.jsx("li",{children:"Confirm the licence class you are applying for."}),e.jsx("li",{children:"Use the official guide for that class."}),e.jsx("li",{children:"Choose a realistic target date without making it your only measure of progress."}),e.jsx("li",{children:"Create one place for notes and repeated mistakes."})]}),e.jsx("h2",{children:"Stage 2: learn in topic blocks"}),e.jsx("p",{children:"Work through a small group of related topics in each session. For example, pair signs and markings, then intersections and right-of-way, then sharing the road and hazard response. End each session by explaining two or three rules without looking at the text."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Four-session knowledge test plan",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"A repeatable cycle for early study sessions."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Part"}),e.jsx("th",{scope:"col",children:"Task"}),e.jsx("th",{scope:"col",children:"Evidence of progress"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Read"}),e.jsx("td",{children:"Study one manageable section of the guide."}),e.jsx("td",{children:"You can summarize its purpose."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Connect"}),e.jsx("td",{children:"Apply the rule to a road situation."}),e.jsx("td",{children:"You can identify the deciding detail."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Recall"}),e.jsx("td",{children:"Close the guide and explain the rule."}),e.jsx("td",{children:"You do not depend on the original wording."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Review"}),e.jsx("td",{children:"Reopen the source and correct your explanation."}),e.jsx("td",{children:"Your note matches the official rule."})]})]})]})}),e.jsx("h2",{children:"Stage 3: add practice questions and diagnose mistakes"}),e.jsxs("p",{children:["Use ICBC's ",e.jsx("a",{href:n.practiceTest,target:"_blank",rel:"noopener noreferrer",children:"official practice-test page"})," after you have studied the relevant material. A score tells you how that session went. A mistake log tells you what to do next."]}),e.jsx("p",{children:"Sort mistakes into a few useful groups: signs and markings, intersections, speed and space, vulnerable road users, driver condition, emergency response and licensing. If one group grows faster than the others, return to that part of the guide before continuing with more mixed questions."}),e.jsxs("p",{children:["Use our ",e.jsx(r,{to:"/blog/knowledge-test-practice-victoria-common-questions",children:"question-strategy guide"})," when your difficulty is reading scenarios rather than recalling the rule."]}),e.jsx("h2",{children:"Stage 4: prepare for the real test process"}),e.jsxs("p",{children:["ICBC currently offers passenger-vehicle knowledge testing online and at driver licensing offices. The two options have different practical requirements. Review the ",e.jsx("a",{href:n.onlineTest,target:"_blank",rel:"noopener noreferrer",children:"online-test page"})," for equipment and follow-up steps, or ICBC's appointment information for an in-person test."]}),e.jsxs("p",{children:["Passing online does not make you licensed to drive. ICBC says you must still complete the required identity, vision and licence-issuance steps at a driver licensing office. Our",e.jsx(r,{to:"/knowledge-test-guide",children:" B.C. knowledge-test guide"})," collects those process details and official links."]}),e.jsx("h2",{children:"Use a flexible two-week example"}),e.jsx("p",{children:"This is an example schedule, not a promise that every learner will be ready in two weeks. Shorten or extend it according to your understanding."}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Days 1–4:"})," study topic blocks and write brief recall notes."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Days 5–7:"})," add topic-based practice and build a mistake log."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Days 8–11:"})," revisit weak sections and begin mixed practice."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Days 12–13:"})," complete realistic sessions and review recurring gaps."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Day 14:"})," use a light review, confirm test logistics and avoid last-minute overload."]})]}),e.jsx("h2",{children:"Know when to adjust the plan"}),e.jsx("p",{children:"Extend the study stage if you keep recognizing answers without being able to explain them, if one topic remains consistently weak or if language makes the source difficult to interpret. ICBC publishes Learn to Drive Smart and practice material in several languages; use the current language options on the official pages."}),e.jsxs("p",{children:["If you want structured help organizing signs, rules and practice, review the",e.jsx(r,{to:"/courses/knowledge-test-prep-course",children:" Knowledge Test Prep Course"}),". Confirm current scheduling before relying on a course date."]})]})},Z=[{question:"What is the best way to study road signs for the ICBC knowledge test?",answer:"Group signs by purpose, learn what each one communicates and connect it to the driver's required response. Then use mixed practice so you can recognize the meaning without being told the category."},{question:"Should I study road signs and rules together?",answer:"Yes. A sign gives information or a direction, while the related road rule explains how that information affects your decision. Studying both helps when a question places the sign inside a traffic scenario."},{question:"Does ICBC provide road-sign practice?",answer:"Yes. ICBC links a road-sign practice option from its official practice knowledge-test page. Use it alongside the current Learn to Drive Smart guide."}],X={slug:"knowledge-test-practice-langford-road-signs",title:"Knowledge Test Practice Langford: Road Signs and Rules You Need to Know",seoTitle:"ICBC Road Signs and Rules Study Guide",description:"Study B.C. road signs by purpose, meaning and driver response, then connect signs with markings, intersections and right-of-way scenarios.",heroImage:"/why-choose/knowledge-test-prep.webp",author:"Shanaya's Driving School",date:"October 8, 2026",datePublished:"2026-10-08",dateModified:"2026-10-08",readTime:"7 min read",category:"Road Signs",faqs:Z,relatedSlugs:["knowledge-test-practice-victoria-what-to-study","knowledge-test-practice-victoria-common-questions","knowledge-test-practice-langford-step-by-step"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Road-sign study becomes easier when every sign is connected to a decision. Instead of learning only a name, use a three-part link: ",e.jsx("strong",{children:"sign → meaning → driver response"}),". Then place the sign beside the signals, markings and road users that may appear in the same situation."]}),e.jsxs("p",{children:["ICBC's ",e.jsx("a",{href:n.learnToDriveSmart,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart"})," includes a chapter on signs, signals and road markings. Use that current official chapter as the source for individual meanings."]}),e.jsx("h2",{children:"Learn signs by purpose first"}),e.jsx("p",{children:"Organizing signs into families reduces the amount you are trying to remember at once. The exact sign still matters, but the family gives you an early clue about the kind of response the driver may need."}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Regulatory signs:"})," communicate rules, permissions, restrictions or required actions."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Warning signs:"})," alert you to a condition or hazard ahead."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Guide and information signs:"})," help with routes, destinations and services."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Construction and temporary signs:"})," explain changed conditions, workers, detours or temporary traffic control."]})]}),e.jsx("p",{children:"After studying each family separately, shuffle the signs. Real driving does not announce the category before you see the sign, and mixed practice checks whether you recognize its purpose independently."}),e.jsx("h2",{children:"Use visual clues without guessing"}),e.jsx("p",{children:"Shape, colour, symbol, text and border can all carry information. Use them as recognition clues, then confirm the complete sign. Do not choose an answer after noticing only one feature, especially when an additional panel, arrow or time restriction changes how the sign applies."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Road sign study sheet",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"A four-column sheet keeps recognition connected to action."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Sign"}),e.jsx("th",{scope:"col",children:"Purpose"}),e.jsx("th",{scope:"col",children:"Meaning"}),e.jsx("th",{scope:"col",children:"Driver response"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Image or name"}),e.jsx("td",{children:"Regulatory, warning, guide or temporary."}),e.jsx("td",{children:"What it communicates in plain language."}),e.jsx("td",{children:"The safe and lawful action it calls for."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Added panel"}),e.jsx("td",{children:"Condition, direction, time or vehicle class."}),e.jsx("td",{children:"How it changes the main sign."}),e.jsx("td",{children:"Who must respond and when."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Road marking"}),e.jsx("td",{children:"Lane use, boundary, crossing or direction."}),e.jsx("td",{children:"How the road space is organized."}),e.jsx("td",{children:"Position, movement or yielding decision."})]})]})]})}),e.jsx("h2",{children:"Connect stop and yield controls with the whole scene"}),e.jsx("p",{children:"A stop or yield question may depend on the stopping position, traffic already in the intersection, pedestrians, vehicle movements and visibility. Read beyond the sign itself. Identify where the driver is, what is controlled and what must be clear before proceeding."}),e.jsx("p",{children:"Avoid shortcuts such as “the vehicle on this side always goes first.” A useful study note explains the conditions that make a right-of-way rule apply."}),e.jsx("h2",{children:"Study signals and markings as part of one system"}),e.jsx("p",{children:"A traffic signal does not remove the need to observe pedestrians, cyclists, turning vehicles or the lane you are entering. Likewise, a road marking may work with a sign or signal. When reviewing a diagram, list all three layers: traffic controls, road layout and road users."}),e.jsxs("ul",{children:[e.jsx("li",{children:"What movement is permitted or restricted?"}),e.jsx("li",{children:"Which lane or road user is affected?"}),e.jsx("li",{children:"What observation is still required before moving?"}),e.jsx("li",{children:"Does an additional sign or marking change the basic instruction?"})]}),e.jsx("h2",{children:"Give extra attention to parking restrictions"}),e.jsx("p",{children:"Parking signs can combine arrows, times, days, vehicle types and stopping restrictions. Read the complete sign and decide which side or section of the street it controls. Create practice examples with one detail changed so you learn how the restriction is interpreted, not only how the sign looks."}),e.jsx("h2",{children:"Use real roads as observation practice"}),e.jsx("p",{children:"While travelling as a passenger in Langford or elsewhere in Greater Victoria, notice signs and markings and explain their meaning before the vehicle reaches them. This is observation practice, not a substitute for the official guide. Do not photograph or study signs while you are the driver."}),e.jsx("p",{children:"Construction, parking and speed controls can change. The sign currently installed on the road controls the situation; a remembered sign from an older trip or map may not."}),e.jsx("h2",{children:"Finish with official mixed practice"}),e.jsxs("p",{children:["ICBC links both general and road-sign practice from its ",e.jsx("a",{href:n.practiceTest,target:"_blank",rel:"noopener noreferrer",children:"practice knowledge-test page"}),". For every missed sign, return to the relevant guide section and add it to your four-column sheet. Once sign recognition is reliable, mix signs with intersection and right-of-way scenarios."]}),e.jsxs("p",{children:["Continue with our ",e.jsx(r,{to:"/blog/knowledge-test-practice-victoria-common-questions",children:"scenario-question method"}),", or use the",e.jsx(r,{to:"/knowledge-test-guide",children:" complete knowledge-test process guide"})," for test format and application steps."]})]})},ee=[{question:"How can I feel more confident before the ICBC knowledge test?",answer:"Use a repeatable study routine, track weak topics and practise explaining the rule behind each answer. Confidence is more reliable when it comes from evidence of understanding rather than one high score."},{question:"Should I keep practising after I get a high score?",answer:"Check whether the score is consistent across mixed topics and whether you can explain uncertain answers. If the score depends on recognizing the same question order, return to the guide and vary your practice."},{question:"What should I do if a practice question confuses me?",answer:"Identify the topic and return to the current Learn to Drive Smart section. Write the rule in your own words, note the clue you missed and test it later with a changed scenario."}],re={slug:"knowledge-test-practice-langford-confidence",title:"Knowledge Test Practice Langford: How to Build Confidence Before Your ICBC Knowledge Test",seoTitle:"Build Confidence for the ICBC Knowledge Test",description:"Build knowledge-test confidence with short study sessions, a mistake log, realistic mixed practice and a calm final-day routine.",heroImage:"/course-pictures/knowledge-test-prep-course.jpg",author:"Shanaya's Driving School",date:"October 8, 2026",datePublished:"2026-10-08",dateModified:"2026-10-08",readTime:"6 min read",category:"Knowledge Test",faqs:ee,relatedSlugs:["knowledge-test-practice-langford-step-by-step","knowledge-test-practice-victoria-common-questions","knowledge-test-practice-langford-road-signs"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Feeling uncertain before a knowledge test does not mean you are incapable of passing it. A better goal than trying to “feel ready” is to collect evidence that you understand the material: you can explain rules, recognize them in new scenarios and correct repeated mistakes."}),e.jsxs("p",{children:["Begin with ICBC's ",e.jsx("a",{href:n.learnToDriveSmart,target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart"})," and use practice questions after studying. This article focuses on the routine and self-checks that make preparation feel more manageable."]}),e.jsx("h2",{children:"Replace one large task with clear topic blocks"}),e.jsx("p",{children:"“Study for the knowledge test” is too broad to guide one session. Choose a smaller target, such as warning signs, intersection controls or sharing the road. Decide what you will read, how you will practise and what you should be able to explain at the end."}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Read:"})," one section from the current official guide."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Recall:"})," summarize the main rule without looking."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Apply:"})," work through a few related scenarios."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Record:"})," note one strength and one item to revisit."]})]}),e.jsx("h2",{children:"Measure understanding, not only scores"}),e.jsx("p",{children:"A practice score is useful, but it cannot tell you whether you guessed or remembered the order of a familiar set. After each session, ask whether you can explain why the correct answer fits and why the other choices do not."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",role:"region","aria-label":"Knowledge test confidence checks",tabIndex:0,children:e.jsxs("table",{children:[e.jsx("caption",{children:"Use evidence from your study sessions to decide what comes next."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"What happened"}),e.jsx("th",{scope:"col",children:"What it may mean"}),e.jsx("th",{scope:"col",children:"Next step"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"High score, weak explanations"}),e.jsx("td",{children:"You may recognize answers without understanding the rule."}),e.jsx("td",{children:"Return to the guide and explain uncertain items."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"One topic causes repeated mistakes"}),e.jsx("td",{children:"Your mixed practice has found a specific gap."}),e.jsx("td",{children:"Use a focused topic session before retesting."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Accurate but very rushed"}),e.jsx("td",{children:"Speed may be hiding missed details."}),e.jsx("td",{children:"Use the scenario-reading method and slow the first pass."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Consistent mixed results"}),e.jsx("td",{children:"Your understanding transfers across topics."}),e.jsx("td",{children:"Prepare the practical test-day details."})]})]})]})}),e.jsx("h2",{children:"Keep a mistake journal without turning it into a punishment"}),e.jsx("p",{children:"A useful journal is short and specific. Record the topic, the clue you missed, the rule from the official guide and when you will revisit it. Do not copy pages of text or count every mistake as a failure. The journal exists to choose the next study task."}),e.jsx("p",{children:"When the same topic improves in a later mixed session, mark that progress. Confidence grows from seeing that a clear review action changed the result."}),e.jsx("h2",{children:"Practise under realistic but reasonable conditions"}),e.jsx("p",{children:"Once you understand the main topics, complete a mixed session without notes, notifications or frequent pauses. Read carefully and work independently. Afterwards, review every uncertain answer, including correct guesses."}),e.jsxs("p",{children:["ICBC's ",e.jsx("a",{href:n.practiceTest,target:"_blank",rel:"noopener noreferrer",children:"official practice test"})," can be taken repeatedly. Vary your preparation by returning to the guide and road-sign practice rather than repeating one set until its sequence feels familiar."]}),e.jsx("h2",{children:"Use a simple pre-test routine"}),e.jsxs("ul",{children:[e.jsx("li",{children:"Confirm whether you are testing online or in person and check the current instructions."}),e.jsx("li",{children:"Prepare identification, consent and payment requirements that apply to you."}),e.jsx("li",{children:"Review a short list of recurring topics rather than starting new material late."}),e.jsx("li",{children:"Remove avoidable distractions and allow enough time for the process."}),e.jsx("li",{children:"Read each question for the rule, road users and changing condition before choosing."})]}),e.jsxs("p",{children:["ICBC's ",e.jsx("a",{href:n.onlineTest,target:"_blank",rel:"noopener noreferrer",children:"online-test page"})," explains the current equipment and follow-up requirements. Passing the online test is not itself a licence; ICBC still needs to issue the learner's licence before you may drive."]}),e.jsx("h2",{children:"Decide when more review is useful"}),e.jsx("p",{children:"More practice helps when it responds to a specific weakness. Repeating random questions without reviewing the rule can create activity without progress. If you do not understand why an official answer applies, pause and return to the relevant source."}),e.jsxs("p",{children:["Use our ",e.jsx(r,{to:"/blog/knowledge-test-practice-langford-step-by-step",children:"step-by-step study plan"})," when you need structure, or the",e.jsx(r,{to:"/blog/knowledge-test-practice-victoria-common-questions",children:"scenario-question method"})," when reading the questions is the main difficulty. The ",e.jsx(r,{to:"/knowledge-test-guide",children:"knowledge-test process guide"})," covers application and test-day requirements."]})]})},t="https://www.google.com/maps/place/Shanaya's+Driving+School/@48.4514745,-123.5207662,17z/data=!4m8!3m7!1s0x548f0dbc0a227e83:0xf890ce589bc36216!8m2!3d48.451471!4d-123.5181913!9m1!1b1!16s%2Fg%2F11nk25xtf2",f="https://api.open511.gov.bc.ca/events?format=kml&status=ACTIVE",m="https://www.icbc.com/road-safety/safety-and-road-conditions/tips-for-driving-in-poor-conditions",c="/contact",l="/road-test-prep-victoria",ie="/courses/mock-test-evaluation",ne=[{question:"What should I check before a driving lesson or road test in Greater Victoria?",answer:"Check the current District of Saanich advisories, North Saanich notices and DriveBC events before leaving. Add time for a detour or traffic-control stop, follow temporary signs and confirm any time-sensitive booking details early."},{question:"Do roadwork notices show an ICBC road-test route?",answer:"No. Roadwork notices describe current traffic impacts. They do not publish an official ICBC test route. Prepare observation, speed control, lane positioning, shoulder checks and safe decisions across different roads."},{question:"Can a mock evaluation help before my road test?",answer:"A private mock evaluation can help identify skills to practise before test day. It is coaching, not an official ICBC assessment, and it cannot guarantee a result."}],se={slug:"greater-victoria-roadwork-route-alerts-november-2026",title:"Greater Victoria Roadwork and Route Alerts for Nov. 2–6, 2026",seoTitle:"Greater Victoria Roadwork Alerts: Nov. 2–6, 2026",description:"Current Saanich, North Saanich and Highway 1 traffic impacts for Greater Victoria lessons, commutes and road-test planning.",heroImage:"/landing/driving-lessons-saanich.webp",author:"Shanaya's Driving School",date:"November 1, 2026",datePublished:"2026-11-01",dateModified:"2026-11-01",readTime:"5 min read",category:"Greater Victoria Road Safety",relatedSlugs:["icbc-road-test-victoria-mckenzie-office","pass-road-test","defensive-driving"],faqs:ne,content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"If you have a driving lesson, school commute or ICBC road test in Greater Victoria this week, check the official traffic notices before leaving and allow extra time. Current notices affect Saanich, North Saanich and overnight travel on Highway 1. This is a dated summary from Shanaya's Driving School; the municipal and provincial notices remain the controlling sources."}),e.jsx("h2",{children:"Current closures and lane restrictions"}),e.jsx("h3",{children:"Saanich"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Millgrove Street:"})," A water-main upgrade is scheduled for Monday, November 2, from 8 a.m. to 3:30 p.m. The road is closed to through traffic, with local and emergency access maintained."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"McKenzie Avenue at Gordon Head Road and Shelbourne Street:"})," Single-lane traffic is scheduled for Tuesday, November 3, from 8:30 a.m. to 3 p.m."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Piedmont Drive:"})," A water-main project continues through November 30, with a road closure between Del Monte Avenue and Santa Clara Avenue during the listed work hours."]})]}),e.jsxs("p",{children:["The ",e.jsx("a",{href:"https://www.saanich.ca/EN/main/community/getting-around/roads-traffic/traffic-advisories.html",target:"_blank",rel:"noopener noreferrer",children:"District of Saanich traffic advisories"}),"say signs and traffic-control personnel will guide drivers. Follow temporary signs rather than relying on a familiar route."]}),e.jsx("h3",{children:"North Saanich"}),e.jsxs("p",{children:["Dean Park Road will be closed to through traffic during working hours from November 3 to 6 for the Capital Regional District's Bear Hill Trunk Main Extension Project. A temporary detour will be in place. Local access will be maintained, and East Saanich Road may have alternating single-lane traffic. Read the",e.jsx("a",{href:"https://www.northsaanich.ca/news-community/news-notices/dean-park-road-closure-november-3-6-2026",target:"_blank",rel:"noopener noreferrer",children:"District of North Saanich notice"}),"before travelling."]}),e.jsx("h2",{children:"Overnight Highway 1 work"}),e.jsx("p",{children:"DriveBC lists overnight blasting between the View Royal and Saanich/McKenzie Avenue areas from October 6 to November 30. The notice describes lane closures in both directions, intermittent stoppages of up to 10 minutes during blasts, weekday work from 8 p.m. to 6 a.m. and Saturday work from 8 p.m. to 8 a.m."}),e.jsxs("p",{children:["A separate DriveBC notice for the Bus on Shoulder project covers the Saanich/McKenzie Avenue and View Royal/ Colwood Bridge corridor. It lists weekday night work from 8 p.m. to 5 a.m., periodic five-minute stoppages and a 50 km/h speed restriction. This is a separate event from the blasting notice. Check the",e.jsx("a",{href:f,target:"_blank",rel:"noopener noreferrer",children:"live DriveBC feed"})," before travelling because construction details can change."]}),e.jsx("h2",{children:"A route checklist for lessons and road tests"}),e.jsxs("ol",{children:[e.jsxs("li",{children:["Check the ",e.jsx("a",{href:"https://www.saanich.ca/EN/main/community/getting-around/roads-traffic/traffic-advisories.html",target:"_blank",rel:"noopener noreferrer",children:"Saanich advisories"}),", the ",e.jsx("a",{href:"https://www.northsaanich.ca/news-community/news-notices/dean-park-road-closure-november-3-6-2026",target:"_blank",rel:"noopener noreferrer",children:"North Saanich notice"}),"and ",e.jsx("a",{href:"https://www.drivebc.ca/",target:"_blank",rel:"noopener noreferrer",children:"DriveBC"})," before leaving."]}),e.jsx("li",{children:"Add a time buffer for a detour, queue or traffic-control stop."}),e.jsx("li",{children:"Follow the posted temporary speed, lane and turn instructions."}),e.jsx("li",{children:"Contact the school or testing office early if your appointment is time-sensitive."}),e.jsx("li",{children:"Use route changes to practise transferable skills rather than trying to memorise a test route."})]}),e.jsxs("p",{children:["For road-test preparation, practise observation, speed control, lane positioning, shoulder checks and safe decisions around changing traffic. ICBC's ",e.jsx("a",{href:"https://icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"}),"describes skills an examiner may assess; it does not publish a route to memorise."]}),e.jsx("h2",{children:"Why gradual route practice matters"}),e.jsxs("p",{children:["One saved review from ",e.jsx("strong",{children:"Vanessa Nicdao"})," describes her son starting on narrow residential streets and later driving confidently on the highway after lessons. That is one family's account, not a typical timeline or a promise of readiness, but it illustrates why practice should expand by skill and traffic demand."]}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:t,children:"“My son started with little experience, driving only on narrow residential streets. … he can now drive confidently on the highway.”"}),e.jsxs("figcaption",{className:"text-sm",children:["Vanessa Nicdao · saved customer review excerpt ·"," ",e.jsx("a",{href:t,target:"_blank",rel:"noopener noreferrer",children:"Read reviews on Google"})]})]}),e.jsxs("p",{children:["If you would like help matching practice to your current experience, review our"," ",e.jsx(r,{to:l,children:"Victoria road-test preparation"}),","," ",e.jsx(r,{to:ie,children:"mock test evaluations"})," or ",e.jsx(r,{to:c,children:"contact the school"}),". Confirm the current service, price and availability before booking."]})]})},te=[{question:"What headlights should I use in fog in B.C.?",answer:"ICBC advises using low-beam headlights in fog or heavy snow. Check the road conditions and DriveBC before travelling, and adjust your speed to what you can see and the traction available."},{question:"How much following distance should I leave in poor conditions?",answer:"ICBC advises allowing at least twice the normal braking distance on wet or slippery roads. Fog can also reduce what you can see ahead, so leave room to respond smoothly."},{question:"Does a fog checklist describe an ICBC road-test route?",answer:"No. It explains safety decisions that transfer across roads. It does not identify or guarantee an official ICBC test route."}],ae={slug:"fog-malahat-island-highway-driving-checklist",title:"Fog on the Malahat and Island Highway: A Low-Visibility Checklist",seoTitle:"Fog on the Malahat: A B.C. Driving Checklist",description:"A Victoria-area fog checklist based on current DriveBC conditions and ICBC guidance for low beams, speed, braking distance and preparation.",heroImage:"/landing/defensive-driving.webp",author:"Shanaya's Driving School",date:"November 1, 2026",datePublished:"2026-11-01",dateModified:"2026-11-01",readTime:"5 min read",category:"Driving Safety",relatedSlugs:["defensive-driving","late-night-crash-langford-night-driving-safety","pass-road-test"],faqs:te,content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["At the time of this check on November 1, 2026, ",e.jsx("a",{href:f,target:"_blank",rel:"noopener noreferrer",children:"DriveBC's active events feed"}),"reported fog patches from near the Malahat through the Cobble Hill and Duncan areas toward Chemainus. Fog can be patchy: clear pavement can change to limited visibility within a short distance. Slow down, use low beams and leave more room to stop. Check the live feed again before travelling because the event can be updated or cleared."]}),e.jsx("h2",{children:"What ICBC recommends"}),e.jsxs("p",{children:[e.jsx("a",{href:m,target:"_blank",rel:"noopener noreferrer",children:"ICBC's poor-conditions guidance"})," covers rain, snow and fog. It recommends:"]}),e.jsxs("ul",{children:[e.jsx("li",{children:"Slow down when conditions reduce visibility or traction."}),e.jsx("li",{children:"Use low-beam headlights in fog or heavy snow."}),e.jsx("li",{children:"Allow at least twice the normal braking distance on wet or slippery roads."}),e.jsx("li",{children:"Keep wiper fluid topped up and check tyre pressure in colder conditions."}),e.jsxs("li",{children:["Check road and weather information on ",e.jsx("a",{href:"https://www.drivebc.ca/",target:"_blank",rel:"noopener noreferrer",children:"DriveBC"})," before travelling."]})]}),e.jsx("p",{children:"Posted speed limits are designed for ideal conditions. A lower speed may be appropriate when you cannot see as far ahead or when the road is wet, while still following the signs and driving predictably."}),e.jsx("h2",{children:"A fog-driving checklist"}),e.jsx("h3",{children:"Before leaving"}),e.jsxs("ol",{children:[e.jsx("li",{children:"Clean the windscreen, mirrors and lights."}),e.jsx("li",{children:"Confirm that low beams and windscreen wipers work."}),e.jsx("li",{children:"Check the live DriveBC events and the weather for your route."}),e.jsx("li",{children:"Leave enough time that you do not feel pressure to make up time in poor visibility."})]}),e.jsx("h3",{children:"While driving"}),e.jsxs("ol",{children:[e.jsx("li",{children:"Reduce speed before visibility drops rather than braking sharply after entering fog."}),e.jsx("li",{children:"Use low beams, as ICBC advises for fog."}),e.jsx("li",{children:"Increase the space in front of you, especially on wet pavement."}),e.jsx("li",{children:"Watch lane markings, signs, cyclists and stopped or slow-moving vehicles."}),e.jsx("li",{children:"Avoid sudden lane changes and keep steering and braking smooth."})]}),e.jsx("p",{children:"If visibility becomes too poor to continue safely, pull over only where it is legal and safe to do so. Keep well clear of travel lanes and follow official road instructions."}),e.jsx("h2",{children:"What this means for a learner"}),e.jsx("p",{children:"Fog practice is about judgement, speed control, following distance and calm observation. These are practical applications of official guidance, not additional ICBC rules. They are also not a reason to chase a particular road or claim knowledge of an ICBC test route."}),e.jsxs("p",{children:["One saved customer review from ",e.jsx("strong",{children:"Yogita Bang"})," describes a first lesson this way: “I took a trial lesson and had a great experience. The instructor was patient, knowledgeable, and made me feel comfortable even though I was nervous.” That is one learner's account, not a typical outcome or a promise that fog-related anxiety will disappear."]}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:t,children:"“I took a trial lesson and had a great experience. The instructor was patient, knowledgeable, and made me feel comfortable even though I was nervous.”"}),e.jsxs("figcaption",{className:"text-sm",children:["Yogita Bang · saved customer review excerpt ·"," ",e.jsx("a",{href:t,target:"_blank",rel:"noopener noreferrer",children:"Read reviews on Google"})]})]}),e.jsxs("p",{children:["If you want help applying the checklist, see our ",e.jsx(r,{to:"/courses/winter-driving-course",children:"winter driving instruction"}),","," ",e.jsx(r,{to:"/courses/defensive-driving-course",children:"defensive driving"})," and ",e.jsx(r,{to:l,children:"Victoria road-test preparation"}),". Ask about the lesson focus that fits your current skills, and confirm availability, service area and price before booking."]})]})},oe=[{question:"What should drivers do for Let’s Get Visible Day in Greater Victoria?",answer:"Turn on headlights, slow down in low visibility, focus on the road, watch for pedestrians and cyclists, and be ready to stop. Follow temporary signs and local road rules."},{question:"What can pedestrians and cyclists do to be more visible?",answer:"Wear bright or reflective clothing, use lights or reflectors where appropriate, use sidewalks or paths when available and make intentions clear while checking that traffic has stopped."},{question:"Can a driving lesson help with visibility and pedestrian awareness?",answer:"A lesson can provide practice with scanning, speed choice, yielding and identifying vulnerable road users. It is coaching for transferable skills, not an official ICBC assessment."}],ce={slug:"lets-get-visible-greater-victoria-driver-pedestrian-checklist",title:"Let’s Get Visible Day in Greater Victoria: A Driver and Pedestrian Checklist",seoTitle:"Let’s Get Visible Day in Greater Victoria (2026)",description:"A Greater Victoria checklist for drivers, pedestrians and cyclists ahead of Let’s Get Visible Day on November 6, 2026.",heroImage:"/landing/driving-lessons-view-royal.webp",author:"Shanaya's Driving School",date:"November 1, 2026",datePublished:"2026-11-01",dateModified:"2026-11-01",readTime:"4 min read",category:"Community Safety",relatedSlugs:["defensive-driving","icbc-road-test-tips-victoria","late-night-crash-langford-night-driving-safety"],faqs:oe,content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Greater Victoria School District 61 is taking part in the CRD-led Let's Get Visible Day on ",e.jsx("strong",{children:"November 6, 2026"}),". If you are driving, walking, cycling or rolling to school or work, make yourself easier to see, reduce speed when visibility is poor and expect other road users to be harder to spot."]}),e.jsx("p",{children:"SD61 reports that 42% of crashes involving pedestrians happen between October and January, with an ICBC attribution. That statistic describes a broader B.C. pattern; it is not a claim about Shanaya's students or a prediction of an individual's risk."}),e.jsx("h2",{children:"A checklist for drivers"}),e.jsxs("ul",{children:[e.jsx("li",{children:"Turn on your headlights before the light fades."}),e.jsx("li",{children:"Slow down where visibility is reduced and scan for people crossing or walking near the road."}),e.jsx("li",{children:"Expect pedestrians and cyclists near schools, bus stops, crosswalks and driveways."}),e.jsx("li",{children:"Keep your attention on the road and put the phone away."}),e.jsx("li",{children:"Be ready to stop when a person's intention is unclear."}),e.jsx("li",{children:"Leave extra time for a dark, wet commute."})]}),e.jsx("p",{children:"ICBC also recommends low beams in fog or heavy snow and at least twice the normal braking distance on wet or slippery roads. Apply each instruction to the condition it covers."}),e.jsx("h2",{children:"A checklist for people walking, cycling or rolling"}),e.jsxs("ul",{children:[e.jsx("li",{children:"Wear bright or reflective clothing and use lights or reflectors where appropriate."}),e.jsx("li",{children:"Use the sidewalk or path when one is available."}),e.jsx("li",{children:"Make your intentions clear with eye contact or a signal, while still checking that traffic has stopped."}),e.jsx("li",{children:"Follow signs and road rules, especially at crossings and school entrances."}),e.jsx("li",{children:"Stay alert for vehicles turning across your path."})]}),e.jsx("p",{children:"Visibility is shared responsibility. Reflective clothing does not make a person invulnerable, and headlights do not remove a driver's duty to look carefully and yield when required."}),e.jsx("h2",{children:"A useful lesson topic"}),e.jsx("p",{children:"Learners can use a darker commute to practise scanning, speed choice, intersections, yielding and identifying vulnerable road users. Ask an instructor to explain what they are looking for, then practise one skill at a time. The goal is to build habits that work across Greater Victoria rather than memorise one school route. A practice session is not an official ICBC assessment, and no lesson guarantees a result."}),e.jsxs("p",{children:["Read the ",e.jsx("a",{href:"https://www.sd61.bc.ca/news-events/news/title/lets-get-visible/",target:"_blank",rel:"noopener noreferrer",children:"SD61 event notice"})," and",e.jsx("a",{href:m,target:"_blank",rel:"noopener noreferrer",children:"ICBC's poor-conditions advice"}),". You can also review our"," ",e.jsx(r,{to:"/driving-lessons-saanich",children:"Saanich driving lessons"})," and ",e.jsx(r,{to:l,children:"Victoria road-test preparation"}),", or"," ",e.jsx(r,{to:c,children:"contact the school"})," with the skill you want to practise. Confirm the current instructor, service area, price and availability before booking."]})]})},le=[{question:"What should I do if I plan to drink or use cannabis?",answer:"Plan a safe ride before you go out. Leave the car at home, use transit or a taxi or ride-hailing service, stay with a sober designated driver or arrange an overnight stay."},{question:"Can L and N drivers drive after drinking or using drugs?",answer:"ICBC says learner and novice drivers must have zero alcohol and zero drugs in their blood while driving. If there is any doubt about safety, do not drive."},{question:"Does coffee or waiting make an impaired driver safe?",answer:"No. Coffee, food, a short nap or waiting for a particular number of hours does not turn an impaired driver into a safe driver. Arrange another way home."}],de={slug:"project-red-ribbon-sober-driving-pledge-victoria",title:"Project Red Ribbon: A Sober-Driving Pledge for Victoria Learners and Families",seoTitle:"Project Red Ribbon: Sober Driving in Victoria",description:"A practical sober-driving plan for Victoria learners and families, based on MADD Canada’s Project Red Ribbon and current ICBC guidance.",heroImage:"/landing/defensive-driving.webp",author:"Shanaya's Driving School",date:"November 1, 2026",datePublished:"2026-11-01",dateModified:"2026-11-01",readTime:"4 min read",category:"Driver Safety",relatedSlugs:["defensive-driving","parents-teen-drivers-victoria-bc-guide","icbc-road-test-tips-victoria"],faqs:le,content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"MADD Canada's Project Red Ribbon is a national holiday-season campaign reminding Canadians to never drive impaired and inviting people to take a sober-driving pledge. The campaign page does not establish a November 1 launch date, so this article uses the confirmed holiday-season message without assigning an unverified launch date."}),e.jsx("h2",{children:"Make the plan before the celebration"}),e.jsx("p",{children:"If your plans involve alcohol, cannabis or another drug, decide how you will get home before you go out. ICBC recommends leaving the car at home, taking transit or a taxi or ride-hailing service, or choosing a designated driver who will stay sober."}),e.jsx("p",{children:"For learners and novice drivers, the decision is even clearer. ICBC says L and N drivers must have zero alcohol and zero drugs in their blood while driving. If there is any doubt about your ability to drive safely, do not drive."}),e.jsx("h2",{children:"A simple sober-driving plan"}),e.jsxs("ol",{children:[e.jsx("li",{children:"Choose the person who will drive before the first drink or other intoxicant."}),e.jsx("li",{children:"Arrange a backup: transit, a taxi, a ride-hailing service, a friend or an overnight stay."}),e.jsx("li",{children:"Leave the vehicle at home if you might not be able to drive safely later."}),e.jsx("li",{children:"Keep the keys away from anyone who is impaired."}),e.jsx("li",{children:"If a friend has used alcohol, cannabis or another drug, help them find a safe ride without shaming them."})]}),e.jsx("p",{children:"Coffee, food, a short nap or waiting for a particular number of hours does not turn an impaired driver into a safe driver."}),e.jsx("h2",{children:"The pledge"}),e.jsx("blockquote",{children:"I will never drive impaired. I will plan a safe ride home, help my friends do the same and keep my keys away from anyone who cannot drive safely."}),e.jsxs("p",{children:["Take the official pledge through ",e.jsx("a",{href:"https://projectredribbon.ca/",target:"_blank",rel:"noopener noreferrer",children:"MADD Canada's Project Red Ribbon"}),". For current B.C. guidance, read ICBC's pages on ",e.jsx("a",{href:"https://www.icbc.com/road-safety/crashes-happen/alcohol-impaired-driving",target:"_blank",rel:"noopener noreferrer",children:"alcohol-impaired driving"}),"and ",e.jsx("a",{href:"https://www.icbc.com/road-safety/crashes-happen/drug-impaired-driving",target:"_blank",rel:"noopener noreferrer",children:"drug-impaired driving"}),"."]}),e.jsx("h2",{children:"A learner's perspective on safe habits"}),e.jsxs("p",{children:["In a saved review snapshot, ",e.jsx("strong",{children:"Violet Lily"})," wrote that her instructor helped her “develop safe defensive driving habits.” That is one learner's experience, not evidence of a typical outcome or a substitute for the sober-driving plan above."]}),e.jsxs("figure",{className:"my-7",children:[e.jsx("blockquote",{cite:t,children:"“develop safe defensive driving habits.”"}),e.jsxs("figcaption",{className:"text-sm",children:["Violet Lily · saved customer review excerpt ·"," ",e.jsx("a",{href:t,target:"_blank",rel:"noopener noreferrer",children:"Read reviews on Google"})]})]}),e.jsxs("p",{children:["If you want structured practice with defensive habits, see our ",e.jsx(r,{to:"/courses/defensive-driving-course",children:"defensive-driving course"})," or"," ",e.jsx(r,{to:c,children:"contact the school"})," with questions about the current service, instructor and availability. No lesson replaces the decision to leave driving to a sober person when you are impaired."]})]})},he=[H,J,Q,X,re,k,F,z,L,q,E,B,I,de,ce,ae,se,{slug:"icbc-road-test-victoria-mckenzie-office",title:"ICBC's Victoria Road Test Office on McKenzie Avenue: What the Area Asks of You",seoTitle:"ICBC Road Test Victoria: The McKenzie Ave Office",description:"ICBC's Victoria road test office on McKenzie Ave: counted traffic, school zones, hills, cyclists and the four failure reasons.",heroImage:"/landing/road-test-prep-victoria.webp",author:"Shanaya's Driving School",authorId:"azy",reviewedById:"joyce",date:"August 2, 2026",datePublished:"2026-08-02",dateModified:"2026-08-02",readTime:"7 min read",category:"Victoria Road Test",relatedSlugs:["icbc-road-test-tips-victoria","pass-road-test"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["ICBC's Victoria driver licensing office is at ",e.jsx("strong",{children:"1-1150 McKenzie Ave"}),", and it books Class 5, 6, 7 and 8 road tests online. Every few weeks someone asks us for the route that leaves it. Nobody outside ICBC has it, and ICBC says so plainly on its"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"Book a road test"})," ","page: ",e.jsx("em",{children:"“any sites which claim to sell our test routes did not obtain that information from ICBC. We do not make this information available outside ICBC.”"})]}),e.jsxs("p",{children:["What you can prepare for is the area. The streets around that office have been counted and signed by public bodies, so what they demand is on record rather than rumour. For eligibility, booking, fees and what to bring, use our"," ",e.jsx(r,{to:"/blog/pass-road-test",children:"Class 7 preparation and test-day checklist"})," instead. No article or lesson can guarantee a pass."]}),e.jsx("h2",{children:"What makes you fail an ICBC road test?"}),e.jsxs("p",{children:["In a"," ",e.jsx("a",{href:"https://www.icbc.com/about-icbc/newsroom/2023-june19",target:"_blank",rel:"noopener noreferrer",children:"July 19, 2023 announcement"}),", ICBC said ",e.jsx("strong",{children:"nearly half"})," of drivers were failing to pass their first attempt. That was a province-wide figure published in 2023, not a pass rate for the Victoria office, and ICBC publishes no office-level breakdown. Its"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"})," ","scores five competencies (Observation, Space Margin, Speed, Steering and Communication), then lists four reasons a test can be failed."]}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",children:e.jsxs("table",{children:[e.jsx("caption",{children:"ICBC's four published failure reasons, quoted from the Skills Explainer, with what each one means while you are driving."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Failure reason"}),e.jsx("th",{scope:"col",children:"ICBC's definition"}),e.jsx("th",{scope:"col",children:"What it means on the road"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Skills"}),e.jsx("td",{children:"Inability to meet the minimum criteria for the driving skills listed in each of the core competencies."}),e.jsx("td",{children:"No single dramatic event is needed; repeated errors across the five competencies can end a test."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Dangerous Action"}),e.jsx("td",{children:"An action or lack of action which could result in a collision or loss of control. Driver Examiner or other vehicle must take action to prevent collision."}),e.jsx("td",{children:"If the examiner or another road user has to act to avoid you, the outcome is effectively decided."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Violation"}),e.jsx("td",{children:"Behaviour that exceeds the range in the applicable criteria and is typically a ticketable offence, e.g. does not stop at red light."}),e.jsx("td",{children:"Speeding in a school or playground zone, running a red, missing a required stop."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Other"}),e.jsx("td",{children:"Inability to operate equipment once test has begun. Unwilling or unable to perform manoeuvre. Hitting objects, driving over curbs/sidewalks."}),e.jsx("td",{children:"Not knowing your own controls, declining a manoeuvre or mounting a curb are each enough."})]})]})]})}),e.jsxs("p",{children:["ICBC publishes no numeric pass mark, so a school or video quoting an exact “point cutoff” is not quoting ICBC. Note too one distinction people merge: ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/assets/pa/HFwP1rzxuRYALIqdQki5P/what-to-expect-road-test.pdf",target:"_blank",rel:"noopener noreferrer",children:"What to expect during your road test"})," ","sheet states that “when completing a parking manoeuvre, touching the curb is not a FAIL”, while ",e.jsx("em",{children:"driving over"})," curbs or sidewalks sits under Other. Light contact is not fatal; mounting the curb is a different matter."]}),e.jsx("h2",{children:"The traffic around the office is measurably heavy"}),e.jsxs("p",{children:["The District of Saanich counts this corridor. A week-long count on McKenzie between Borden and Blenkinsop, from October 25 to November 1, 2023, recorded an average weekday volume of"," ",e.jsx("strong",{children:"29,797 vehicles"})," at an average speed of 49 km/h. Six-hour intersection counts the same month logged 21,503 vehicles at McKenzie and Quadra and 18,031 at McKenzie and Borden."]}),e.jsxs("p",{children:["One detail beats those headline numbers. Saanich noted that westbound volumes in the weekday 3–4 p.m. hour were “significantly affected by queuing through the corridor,” causing the counter to under-report by as much as 40 per cent. The queues here defeated the counting equipment. The busiest single hour was not the afternoon but"," ",e.jsx("strong",{children:"8–9 a.m., at 2,312 vehicles"}),", so an early appointment puts you in the heaviest hour of the week and inside school-zone hours at once. Saanich states its counts are informational and not guaranteed accurate, and they say nothing about which streets an examiner will use."]}),e.jsx("h2",{children:"When does a 30 km/h school zone apply in B.C.?"}),e.jsxs("p",{children:["A school zone signed 30 km/h applies on a ",e.jsx("strong",{children:"regular school day, 8 a.m. to 5 p.m."}),", or the longer times shown on the sign. A playground zone signed 30 km/h applies ",e.jsx("strong",{children:"dawn to dusk, every day"}),", weekends and holidays included. That last difference is the one drivers miss."]}),e.jsxs("p",{children:["Both rules come from"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act section 147"}),". They matter here because Reynolds Secondary sits at ",e.jsx("strong",{children:"3963 Borden St"}),", just south of the McKenzie and Borden intersection counted above. ICBC names speeding in these zones among the most common road test mistakes, and a school warning sign without a 30 km/h tab does not by itself create the limit."]}),e.jsx("h2",{children:"Speed limits change quickly across this area"}),e.jsxs("p",{children:["The office is in Saanich, but test driving crosses municipal lines. The City of Victoria completed ",e.jsx("strong",{children:"30 km/h limits on local streets in December 2025"})," and is moving most major streets to ",e.jsx("strong",{children:"40 km/h during 2026"}),", though Blanshard and Douglas north of Caledonia stay at 50. Those changes do not apply automatically in Saanich, Oak Bay or Esquimalt. Read every sign and never inherit your speed from the car ahead. ICBC also warns that “in addition to speeding violations, you may be assessed for going too slow in low risk situations.”"]}),e.jsx("h2",{children:"Pedestrians, cyclists and turns"}),e.jsx("p",{children:"The Quadra count logged roughly 1,365 pedestrian crossings and 260 buses in six hours. That volume is why turn observation carries so much weight here. ICBC's tip sheet is specific: shoulder check right on every right turn for cyclists and pedestrians, scan the intersection before entering even on a green, stop fully behind the stop line, and mirror, signal and shoulder check before any lane or direction change."}),e.jsxs("p",{children:["When passing a cyclist or another person covered by"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05#section157.1",target:"_blank",rel:"noopener noreferrer",children:"section 157.1"})," ","and"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/26_58_16",target:"_blank",rel:"noopener noreferrer",children:"Division 48"}),", the minimum lateral distance is generally 1 metre at 50 km/h or less, 1.5 metres above 50 km/h, and 0.5 metre where the person is on a sidewalk or in a protected cycle lane. A minimum distance never makes an otherwise unsafe pass acceptable."]}),e.jsx("p",{children:"On left turns, section 174 requires you to yield to oncoming traffic in the intersection or “so close as to constitute an immediate hazard.” The weak turns we see in McKenzie congestion are rarely the reckless ones. They are indecisive, and ICBC assesses drivers for being unnecessarily cautious as well as unnecessarily aggressive. Keep the wheels straight while you wait, too: ICBC's steering criteria say to avoid angling the car or wheels to the left when waiting to turn left."}),e.jsx("h2",{children:"Which way do you turn your wheels parking on a hill?"}),e.jsxs("p",{children:["Hill parking appears on the test, and ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/7piwqMyGnoxb1F6ONZSMqr/tuneup-complete.pdf",target:"_blank",rel:"noopener noreferrer",children:"Tuning Up for Drivers"})," ","manual gives the wheel positions directly. Its own summary line is the one to memorise:"," ",e.jsx("em",{children:"the only time you leave your wheels turned out to the left is when you park uphill with a curb."})]}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",children:e.jsxs("table",{children:[e.jsx("caption",{children:"Front-wheel direction for each hill-parking situation, from ICBC's Tuning Up for Drivers manual. Left appears only once, in the second row."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Situation"}),e.jsx("th",{scope:"col",children:"Turn the front wheels"}),e.jsx("th",{scope:"col",children:"How you set it"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Downhill with a curb"}),e.jsx("td",{children:"Right"}),e.jsx("td",{children:"Move forward slowly until the right front wheel touches the curb."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Uphill with a curb"}),e.jsx("td",{children:"Left"}),e.jsx("td",{children:"Let the vehicle roll back slowly until the tire touches the curb."})]}),e.jsxs("tr",{children:[e.jsx("th",{scope:"row",children:"Uphill or downhill without a curb"}),e.jsx("td",{children:"Right"}),e.jsx("td",{children:"If the vehicle rolls, it rolls away from the street rather than into it."})]})]})]})}),e.jsx("p",{children:"In each case, park within 30 cm of the curb and apply the parking brake fully. On a very steep uphill start in an automatic, ICBC says you may need the parking brake to stop the car rolling back. The manual assumes a two-way street, so reverse right and left on the left side of a one-way."}),e.jsx("h2",{children:"What surprises people on an ICBC road test?"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Touching the curb while parking is not a fail."})," Stated in those words."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Back-up cameras do not need to be disabled"}),", but you should not rely solely on the camera while backing."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"When asked to pull over and park"}),", park as if you were leaving the vehicle overnight. Leave the engine running."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"You may ask questions"}),", best before the test starts, and the examiner will not trick you or ask you to break the law."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"GPS, navigation and recording devices must be off."})," ICBC recommends turning a phone off completely."]})]}),e.jsx("h2",{children:"Practising for these roads"}),e.jsx("p",{children:"Build practice around what the area demands: arterial pacing on McKenzie, sign recognition on a school day near Reynolds, right turns with a deliberate cyclist scan, hill parking until the wheel direction is automatic, and left-turn gap judgment at busy signals. Practise legally, with a qualified supervisor."}),e.jsx("h2",{children:"Does the October 19, 2026 change affect this?"}),e.jsxs("p",{children:["The Class 7 road test from learner to novice is unchanged. What changes is the second road test, which a Driving Record Assessment replaces for eligible novice drivers. Read our"," ",e.jsx(r,{to:"/blog/bc-glp-changes-2026",children:"GLP change summary"})," before relying on a future date."]}),e.jsx("h2",{children:"Optional local preparation"}),e.jsxs("p",{children:["A learner can prepare entirely through legal supervised practice and ICBC's free guides. For structured feedback on these specific roads,"," ",e.jsx(r,{to:"/road-test-prep-victoria",children:"road test preparation"})," and"," ",e.jsx(r,{to:"/driving-lessons",children:"driving lessons"})," are options. A lesson or mock evaluation does not reproduce an ICBC examination and cannot guarantee a passing result."]}),e.jsx("h2",{children:"Official sources"}),e.jsxs("ul",{children:[e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"})," ","(MV2959) and"," ",e.jsx("a",{href:"https://www.icbc.com/assets/pa/HFwP1rzxuRYALIqdQki5P/what-to-expect-road-test.pdf",target:"_blank",rel:"noopener noreferrer",children:"What to expect during your road test"})," ","(MV2661)."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/about-icbc/newsroom/2023-june19",target:"_blank",rel:"noopener noreferrer",children:"road test success tips"})," ","(July 19, 2023), and"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"Book a road test"}),"."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/7piwqMyGnoxb1F6ONZSMqr/tuneup-complete.pdf",target:"_blank",rel:"noopener noreferrer",children:"Tuning Up for Drivers"})," ",": hill parking and hill starts."]}),e.jsxs("li",{children:["District of Saanich traffic counts:"," ",e.jsx("a",{href:"https://www.saanich.ca/assets/Community/Documents/Engineering/Traffic/2023/MCKENZIE%20AVE%20BETWEEN%20BORDEN%20AND%20BLENKINSOP%20-%20OCT%202023.pdf",target:"_blank",rel:"noopener noreferrer",children:"McKenzie between Borden and Blenkinsop"}),","," ",e.jsx("a",{href:"https://www.saanich.ca/assets/Community/Documents/Engineering/Intersection/2023~Fall/McKenzie%20Ave%20and%20Quadra%20St%20-%20October%202023.pdf",target:"_blank",rel:"noopener noreferrer",children:"McKenzie and Quadra"})," ","and"," ",e.jsx("a",{href:"https://www.saanich.ca/assets/Community/Documents/Engineering/Intersection/2023~Fall/McKenzie%20Ave%20and%20Borden%20St%20-%20October%202023.pdf",target:"_blank",rel:"noopener noreferrer",children:"McKenzie and Borden"})," ","(October 2023)."]}),e.jsxs("li",{children:["City of Victoria,"," ",e.jsx("a",{href:"https://www.victoria.ca/getting-around/driving/lower-speed-limits",target:"_blank",rel:"noopener noreferrer",children:"Lower Speed Limits"}),"."]}),e.jsxs("li",{children:["Province of B.C.,"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act"})," ",": sections 147, 157.1 and 174."]})]}),e.jsx("p",{children:"Sources were checked on August 2, 2026. What these bodies publish can change, and posted signs always govern. Confirm the official pages and your licence conditions before booking."})]})},{slug:"bc-glp-changes-2026",title:"B.C. GLP Changes on October 19, 2026: Second Road Test, DRA and New Timelines",seoTitle:"B.C. GLP Changes: What Starts October 19, 2026",description:"A sourced guide to B.C.'s October 19, 2026 GLP changes: the Driving Record Assessment, age-based timelines, restricted Class 5 stage and transition rules.",heroImage:"/landing/bc-graduated-licensing-program.webp",author:"Shanaya's Driving School",authorId:"joyce",reviewedById:"azy",date:"July 21, 2026",datePublished:"2026-07-21",dateModified:"2026-07-21",readTime:"8 min read",category:"ICBC Updates",relatedSlugs:["pass-road-test","icbc-road-test-tips-victoria","newcomers-guide-bc"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["B.C.'s Graduated Licensing Program (GLP) changes on ",e.jsx("strong",{children:"October 19, 2026"}),". On that date, eligible drivers with a Class 7 novice or Class 7, 8 novice licence will use a"," ",e.jsx("strong",{children:"Driving Record Assessment (DRA)"})," instead of a second road test to move to a Class 5 or Class 5, 6 licence with restrictions. The Class 7 road test from learner to novice remains part of the program. These details come from"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"ICBC's GLP changes page"})," ","and the"," ",e.jsx("a",{href:"https://news.gov.bc.ca/releases/2026PSSG0061-000847",target:"_blank",rel:"noopener noreferrer",children:"Government of B.C. announcement"}),"."]}),e.jsx("p",{children:"This article explains the public rules available on July 21, 2026. Your age, current licence, driving record and the date of any booked test can change how the transition applies to you, so use ICBC's page to confirm your individual requirements."}),e.jsx("h2",{children:"What changes on October 19"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"The learner-to-novice road test stays."})," The DRA replaces the second road test for eligible novice drivers."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"The first Class 5 is restricted for 12 months."})," Restriction 55 requires zero blood alcohol and zero blood drug content while driving."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Drivers under 25"})," keep a 12-month learner stage and a 24-month novice stage, or 18 months as a novice if they complete an ICBC-approved GLP course and satisfy its other conditions. The new restricted-Class-5 year comes after that."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Drivers 25 and older"})," have a nine-month learner stage, a 12-month novice stage and then the 12-month restricted-Class-5 stage."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Second road tests booked for October 19 or later will be cancelled."})," ICBC says it will email affected drivers with next steps."]})]}),e.jsx("h2",{children:"Driving Record Assessment eligibility"}),e.jsxs("p",{children:["A DRA is an in-office review of your driving record, not an on-road test. According to"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"ICBC's published criteria"}),", you must meet all of the following to upgrade:"]}),e.jsxs("ul",{children:[e.jsx("li",{children:"If you are under 25: at least 24 months of safe driving, or 18 months if you completed an ICBC-approved GLP course during the learner stage."}),e.jsx("li",{children:"If you are 25 or older: at least 12 months of safe driving."}),e.jsx("li",{children:"No convictions for excessive speed or use of electronic devices during that time."}),e.jsx("li",{children:"No driving prohibitions or suspensions during that time."})]}),e.jsxs("p",{children:["Tickets already have consequences under the current GLP. ICBC says even one ticket may trigger a record review and a possible prohibition, and the"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-full-licence",target:"_blank",rel:"noopener noreferrer",children:"current Class 5 eligibility rule"})," ","requires 24 consecutive months without a prohibition. RoadSafetyBC also applies its Driver Improvement Program at lower point levels for new drivers. The new rule is more specific: an excessive-speed or electronic-device conviction during the required DRA period prevents the driver from meeting the published criteria. Do not assume that another type of ticket has no consequence; check your record and ask ICBC about your eligibility. See ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-L",target:"_blank",rel:"noopener noreferrer",children:"GLP penalty guidance"})," ","and the Province's"," ",e.jsx("a",{href:"https://www2.gov.bc.ca/gov/content/transportation/driving-and-cycling/roadsafetybc/high-risk-driver/driver-improvement",target:"_blank",rel:"noopener noreferrer",children:"Driver Improvement Program"}),"."]}),e.jsx("h2",{children:"How long until an unrestricted Class 5?"}),e.jsx("p",{children:"The table below adds the minimum published stages for a new driver who progresses without an interruption. It does not include extra time caused by waiting, an unsuccessful road test, a prohibition, suspension or a disqualifying conviction."}),e.jsx("div",{className:"overflow-x-auto rounded-xl border border-slate-200",children:e.jsxs("table",{children:[e.jsx("caption",{children:"Each row is one step of the licensing path, in order. The Stage column says whether that step is waiting time or a test, and the three columns beside it show what applies to you."}),e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{scope:"col",children:"Stage"}),e.jsx("th",{scope:"col",children:"Old model"}),e.jsx("th",{scope:"col",children:"New model, under 25"}),e.jsx("th",{scope:"col",children:"New model, 25 and older"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsxs("th",{scope:"row",children:["Class 7L learner",e.jsx("span",{className:"mt-1 block text-sm font-normal text-slate-500",children:"Waiting time. The minimum you must hold the learner licence before you may book the Class 7 road test. You drive only with a qualified supervisor beside you."})]}),e.jsx("td",{children:"12 months"}),e.jsx("td",{children:"12 months"}),e.jsx("td",{children:"9 months"})]}),e.jsxs("tr",{children:[e.jsxs("th",{scope:"row",children:["Learner to novice",e.jsx("span",{className:"mt-1 block text-sm font-normal text-slate-500",children:"A test, not waiting time. Passing it lets you start driving on your own. This step does not change on October 19, 2026."})]}),e.jsx("td",{children:"Class 7 road test"}),e.jsx("td",{children:"Class 7 road test"}),e.jsx("td",{children:"Class 7 road test"})]}),e.jsxs("tr",{children:[e.jsxs("th",{scope:"row",children:["Class 7 novice",e.jsx("span",{className:"mt-1 block text-sm font-normal text-slate-500",children:'Waiting time. The minimum you must hold the novice licence before you can move up. You drive alone, display an "N" sign and follow passenger limits.'})]}),e.jsx("td",{children:"24 months, or 18 with an ICBC-approved GLP course"}),e.jsx("td",{children:"24 months, or 18 with an ICBC-approved GLP course"}),e.jsx("td",{children:"12 months"})]}),e.jsxs("tr",{children:[e.jsxs("th",{scope:"row",children:["Novice to Class 5",e.jsx("span",{className:"mt-1 block text-sm font-normal text-slate-500",children:'A step, not waiting time. It removes the "N". Before the change it is a second drive with an examiner; afterwards it is an in-office check of your driving record, with no driving at all.'})]}),e.jsx("td",{children:"Second road test"}),e.jsx("td",{children:"Driving Record Assessment"}),e.jsx("td",{children:"Driving Record Assessment"})]}),e.jsxs("tr",{children:[e.jsxs("th",{scope:"row",children:["Class 5 with restriction 55",e.jsx("span",{className:"mt-1 block text-sm font-normal text-slate-500",children:"Waiting time, and a brand new stage. The minimum you must hold a Class 5 that requires zero alcohol and zero drugs while driving, before that restriction lifts."})]}),e.jsx("td",{children:"Did not exist"}),e.jsx("td",{children:"12 months"}),e.jsx("td",{children:"12 months"})]}),e.jsxs("tr",{children:[e.jsxs("th",{scope:"row",children:["Total to an unrestricted Class 5",e.jsx("span",{className:"mt-1 block text-sm font-normal text-slate-500",children:"All the waiting times added together, from your first day as a learner to a licence with no GLP conditions left."})]}),e.jsx("td",{children:"36 months, or 30 with an ICBC-approved GLP course"}),e.jsx("td",{children:"48 months, or 42 with an ICBC-approved GLP course"}),e.jsx("td",{children:"33 months"})]})]})]})}),e.jsxs("p",{children:["For drivers under 25, that is 48 months from the start of the learner stage to an unrestricted Class 5 using the ordinary minimums, or 42 months if the driver qualifies for the six-month approved-course reduction. The under-25 learner and novice minimums do not change, but the new 12-month restricted-Class-5 stage means the time to an"," ",e.jsx("em",{children:"unrestricted"})," licence does change."]}),e.jsxs("p",{children:["For drivers 25 and older, adding those minimum stages gives 33 months to an unrestricted Class 5. The Province's"," ",e.jsx("a",{href:"https://news.gov.bc.ca/releases/2026PSSG0061-000847",target:"_blank",rel:"noopener noreferrer",children:"official backgrounder"})," ","sets out both age-based paths. Totals in the table are the sum of the published stage minimums, not a figure ICBC publishes directly."]}),e.jsx("h2",{children:"What restriction 55 means"}),e.jsx("p",{children:"After a successful DRA, the Class 5 licence has restriction 55: zero blood alcohol and zero blood drug content while driving. ICBC says the expiry date will appear on the back of the licence and the restriction expires automatically after 12 months. No separate removal appointment is required."}),e.jsxs("p",{children:["If the driver receives a prohibition or suspension before the restriction expires, the full 12-month period restarts on the date the licence is reinstated. This reset is narrower than saying every ticket automatically restarts the restriction. Read ICBC's"," ",e.jsx("a",{href:"https://icbc.com/driver-licensing/new-drivers/you-have-a-class-7-licence-and-youre-under-25",target:"_blank",rel:"noopener noreferrer",children:"restriction 55 explanation"})," ","and contact ICBC if a violation appears on your record."]}),e.jsx("h2",{children:"If your second road test is booked around the change"}),e.jsxs("p",{children:["ICBC says a second road test booked for ",e.jsx("strong",{children:"October 19, 2026 or later"})," will be cancelled and it will email the driver with next steps. Until the change takes effect, an eligible novice driver can still choose to take the second road test."]}),e.jsx("p",{children:"The two outcomes are not identical. Under the existing model, passing a Class 5 road test before October 19 leads to an unrestricted Class 5. Under the new model, an eligible driver completes the DRA and then holds a Class 5 with restriction 55 for 12 months. Before changing or keeping an appointment, confirm your eligibility and options with ICBC; this article cannot determine which choice is suitable for an individual driver."}),e.jsx("h2",{children:"Passenger, supervisor and consent changes"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Learner passengers:"})," a Class 7L learner currently may carry one passenger in addition to the required supervisor. From October 19, the learner may carry more than one passenger only when all passengers other than the supervisor are immediate family. This is the new family exception described on ICBC's"," ",e.jsx("a",{href:"https://icbc.com/driver-licensing/new-drivers/you-have-a-class-7l-licence",target:"_blank",rel:"noopener noreferrer",children:"Class 7L page"}),"."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Novice passengers:"})," Class 7 novice drivers already have an immediate-family exception. Their existing rule allows one passenger unless all passengers are immediate family or a qualified supervisor is seated beside the driver."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Supervisors:"})," from October 19, the minimum age drops from 25 to 22. ICBC says the supervisor must have an unrestricted Class 5 licence, be legally able to drive and sit beside the learner or novice driver."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Consent:"})," the age at which a person can apply for a driver's licence without parental or guardian consent drops from 19 to 18."]})]}),e.jsx("h2",{children:"Other transition details"}),e.jsx("p",{children:"The Province says some drivers who are already in the GLP may qualify for a one-time automatic upgrade from Class 7 to Class 5 without an in-office DRA. Its July 20 announcement does not define the eligible group. It says ICBC will begin sending letters in early fall 2026 explaining how current GLP drivers are affected. Rely on that notice or confirm directly with ICBC rather than assuming an automatic upgrade."}),e.jsx("p",{children:"The B.C. release says DRAs will be available at Service BC offices, driver licensing agent offices and ICBC driver licensing offices. ICBC's booking instructions say online DRA appointments can be made only for an ICBC driver licensing office, not for Service BC or a driver licensing agent; walk-in service is also described. Confirm service availability at the location before travelling."}),e.jsx("h2",{children:"Approved GLP course: what the reduction requires"}),e.jsxs("p",{children:["A driving-school licence and approval of a GLP course are different things. ICBC licenses driving schools to operate; a licensed school must complete a separate process before ICBC approves a particular Class 7 GLP course. Confirm both the school and the course in ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school",target:"_blank",rel:"noopener noreferrer",children:"licensed-school directory"})," ","and"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school/glp-schools",target:"_blank",rel:"noopener noreferrer",children:"approved-GLP-school list"}),"."]}),e.jsxs("p",{children:["ICBC describes the approved Class 7 course as 32 hours: 16 hours of classroom theory, 12 hours of individual on-road instruction and four discretionary hours. For an under-25 driver to qualify for the six-month novice-stage reduction, ICBC says the course must be completed within 365 days while the student holds a Class 7 learner's licence. The student must then have no violations or at-fault crashes during the first 18 months of the novice stage. Starting but not completing the course does not shorten the 24-month requirement. See ICBC's full"," ",e.jsx("a",{href:"https://www.partners.icbc.com/driver-training/driving-schools/teach-approved-course",target:"_blank",rel:"noopener noreferrer",children:"approved-course requirements"}),"."]}),e.jsx("h2",{children:"Practical checklist"}),e.jsxs("ol",{children:[e.jsx("li",{children:"Check your current licence type and age against ICBC's GLP changes page."}),e.jsx("li",{children:"Review your driving record against every DRA criterion, not only the time requirement."}),e.jsx("li",{children:"If a second road test is booked, compare its date with October 19 and wait for ICBC's email if it will be cancelled."}),e.jsx("li",{children:"If considering the course reduction, verify that the provider and specific course are on ICBC's approved GLP list before paying."}),e.jsx("li",{children:"Confirm your DRA location and whether it accepts appointments or walk-ins."})]}),e.jsx("h2",{children:"Independent-school disclosure"}),e.jsxs("p",{children:["Shanaya's Driving School is an independent driving school. It is not ICBC and cannot decide DRA eligibility, change a driving record, guarantee a test result or issue a licence. For official decisions, contact ICBC. If you choose optional professional practice for the learner-to-novice road test, see our ",e.jsx(r,{to:"/driving-lessons",children:"driving lessons"})," or"," ",e.jsx(r,{to:"/road-test-prep-victoria",children:"road-test preparation"}),". These services are separate from an ICBC-approved GLP course unless ICBC's current approved-course list says otherwise."]}),e.jsx("h2",{children:"Official sources"}),e.jsx("p",{children:"Sources were reviewed on July 21, 2026. ICBC may refine operational details before the October 19 effective date."}),e.jsxs("ul",{children:[e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Changes to the Graduated Licensing Program"})}),e.jsx("li",{children:e.jsx("a",{href:"https://news.gov.bc.ca/releases/2026PSSG0061-000847",target:"_blank",rel:"noopener noreferrer",children:"Government of B.C.: Supporting road safety, streamlining licensing for new drivers"})}),e.jsx("li",{children:e.jsx("a",{href:"https://icbc.com/driver-licensing/new-drivers/you-have-a-class-7-licence-and-youre-under-25",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Class 7 licence and under-25 transition details"})}),e.jsx("li",{children:e.jsx("a",{href:"https://icbc.com/driver-licensing/new-drivers/you-have-a-class-7l-licence",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Class 7L transition and passenger rules"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.partners.icbc.com/driver-training/driving-schools/teach-approved-course",target:"_blank",rel:"noopener noreferrer",children:"ICBC Driver Training: Approved GLP course requirements"})}),e.jsxs("li",{children:[e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Choosing a licensed driving school"})," ","and the"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driver-training/Choosing-your-driving-school/glp-schools",target:"_blank",rel:"noopener noreferrer",children:"approved GLP school list"})]}),e.jsxs("li",{children:[e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-L",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Penalties for GLP drivers"})," ","and"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-full-licence",target:"_blank",rel:"noopener noreferrer",children:"current Class 5 road-test eligibility"})]}),e.jsx("li",{children:e.jsx("a",{href:"https://www2.gov.bc.ca/gov/content/transportation/driving-and-cycling/roadsafetybc/high-risk-driver/driver-improvement",target:"_blank",rel:"noopener noreferrer",children:"RoadSafetyBC: Driver Improvement Program"})})]}),e.jsx("p",{children:"Last substantive review: July 21, 2026. Always confirm current requirements with ICBC before changing an appointment or making a licensing decision."})]})},{slug:"how-to-pass-driving-test-victoria-bc",title:"B.C. Class 7 Road Test: Victoria Preparation Guide",seoTitle:"Class 7 Road Test Victoria: Preparation Guide",description:"Prepare for a B.C. Class 7 road test in Victoria with verified ICBC eligibility, practice, booking, fee, vehicle and test-day information.",heroImage:"/blog/how-to-pass-driving-test-victoria-bc.webp",author:"Shanaya's Driving School",authorId:"azy",reviewedById:"joyce",date:"July 21, 2026",datePublished:"2026-07-05",dateModified:"2026-07-21",readTime:"8 min read",category:"Road Test Guide",relatedSlugs:["bc-glp-changes-2026","icbc-road-test-tips-victoria","pass-road-test"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"This guide is for a B.C. Class 7 learner preparing to take the first road test and obtain a novice (N) licence. It explains the current eligibility rule, what ICBC says to practise, how to book, what to bring, and what happens during and after the test. No guide or lesson can guarantee a pass: the result depends on the driving you demonstrate during the test."}),e.jsx("h2",{children:"1. Check when you are eligible"}),e.jsxs("p",{children:["Under the rules in effect on July 21, 2026, a Class 7 learner must complete at least 12 consecutive months as a learner without a driving prohibition before taking the Class 7 road test. ICBC prints the earliest test date on the licence. Holding the licence for the minimum period makes you eligible to test; it does not by itself mean you are ready. See ICBC's current ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"Get your N guidance"})," and the eligibility date on your own licence."]}),e.jsxs("p",{children:["A scheduled change takes effect on October 19, 2026: learners who are 25 or older will have a minimum learner period of nine months, while the 12-month minimum will continue for learners under 25. The first Class 7 road test remains part of the process. The change to the second road test does not remove this test. Read ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"Graduated Licensing Program changes"})," and our plain-language"," ",e.jsx(r,{to:"/blog/bc-glp-changes-2026",children:"GLP change summary"})," before relying on a future date."]}),e.jsx("h2",{children:"2. Build readiness before choosing a test date"}),e.jsxs("p",{children:["ICBC recommends at least 60 hours of practice for the Class 7 road test. That number is preparation guidance, not a statutory minimum and not a promise that a particular number of hours will produce a pass. Some learners need more time. ICBC's free"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/documents/tuneup-complete.pdf",target:"_blank",rel:"noopener noreferrer",children:"Tuning Up for Drivers guide"})," provides structured sessions and a practice log to use with a qualified supervisor."]}),e.jsx("p",{children:"Build practice gradually and include different legal driving environments, traffic levels, times of day and weather conditions with your supervisor. In Greater Victoria, useful transferable practice may include hills, multi-lane roads, roundabouts and areas with pedestrians and cyclists. These are examples of varied practice, not a prediction of what will be on a test or which streets an examiner will use."}),e.jsx("h3",{children:"Use ICBC's five core skill groups"}),e.jsxs("p",{children:["ICBC's ",e.jsx("a",{href:"https://www.icbc.com/assets/pa/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"})," organizes the driving criteria into five core competencies:"]}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Observation:"})," scan for hazards, use mirrors, shoulder-check before a change in direction or road position, look all around before backing, and look in the direction of travel."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Space margin:"})," choose a safe and legal lane position, maintain a safe following distance, select safe gaps, stop in the correct position, and leave adequate clearance when parking."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Speed:"})," stay within the limit while choosing a speed appropriate for conditions, stop fully when required, respond safely to amber lights, and accelerate or slow smoothly."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Steering:"})," maintain control, use an appropriate steering-wheel position, and position the wheels correctly when parked on a hill."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Communication:"})," signal before turning, changing lanes, pulling out or pulling over; time the signal so it gives useful warning; and cancel it afterwards."]})]}),e.jsx("p",{children:"The Skills Explainer also defines a dangerous action as conduct, or a failure to act, that could cause a collision or loss of control and requires another person to intervene. A violation is observed behaviour outside the applicable criteria that is typically a ticketable offence. ICBC does not publish a simple points target, so prepare to perform all core skills consistently rather than trying to calculate an unofficial passing score."}),e.jsx("h2",{children:"3. Book directly through ICBC"}),e.jsxs("p",{children:["Use ICBC's official ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"road-test booking page"})," to book, reschedule or cancel. Third-party booking services are not affiliated with ICBC, and ICBC says phoning does not reveal different appointment times from those available online. Choose an office and date for which you can arrive prepared; do not assume that a particular location will be easier."]}),e.jsx("p",{children:"ICBC does not make its road-test routes available outside ICBC and warns that sites selling routes did not obtain them from ICBC. Practising memorized streets is therefore not a reliable preparation strategy. If you need to cancel or reschedule, give at least 48 hours' notice to avoid the current $25 cancellation fee."}),e.jsx("h2",{children:"4. Bring every required item"}),e.jsxs("p",{children:["Check the official ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Prepare-road-test-appointment",target:"_blank",rel:"noopener noreferrer",children:"appointment-preparation page"})," again shortly before the test. ICBC's current passenger-vehicle guidance calls for:"]}),e.jsxs("ul",{children:[e.jsx("li",{children:"your current driver's licence;"}),e.jsx("li",{children:"one accepted primary ID and one accepted secondary ID;"}),e.jsx("li",{children:"a safe, reliable and properly insured vehicle with a Canadian licence plate, along with its registration and insurance papers; be ready to give the plate number at the counter and make sure the coverage permits you to drive it;"}),e.jsx("li",{children:"a licensed driver who meets the supervisor requirements, because you must continue to obey the conditions of your learner's licence before the test and will still need supervised driving if you do not pass;"}),e.jsx("li",{children:"glasses or contact lenses if you require them to drive;"}),e.jsx("li",{children:"your Declaration of Completion if you successfully completed an ICBC-approved GLP driver-training course; and"}),e.jsx("li",{children:"payment for the road-test and licence fees."})]}),e.jsx("p",{children:"If you are not the named member for a car-share vehicle, ICBC requires an original, signed and dated authorization letter on the company's letterhead for each test attempt. The current preparation page also says the test vehicle must be clean, scent-free and free of items that could affect health or safety. Audio and video recording devices cannot be used, and GPS and navigation systems must be turned off."}),e.jsx("h3",{children:"Check the vehicle before leaving home"}),e.jsx("p",{children:"ICBC may cancel a test if a vehicle is unsafe or does not meet legal requirements. Its published common rejection reasons include illegally tinted or cracked glass, safety-related dashboard warning lights, damaged seatbelts, non-working lights, an unsafe or cluttered interior, illegal modifications, a non-working horn, unsafe tires, doors or windows that do not operate, and too little fuel or battery charge. Check for an outstanding serious safety recall as well. This check should happen before test day, leaving time to repair a problem or arrange another eligible vehicle."}),e.jsx("h2",{children:"5. Know the current fees"}),e.jsxs("p",{children:["As checked on July 21, 2026, ICBC lists a $35 fee for a Class 7 road-test attempt and a $75 fee for the five-year novice licence issued after a pass. A test fee applies to each attempt. Fees can change, so confirm them on ICBC's ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Fees",target:"_blank",rel:"noopener noreferrer",children:"driver-licensing fees page"})," rather than relying on an old checklist."]}),e.jsx("h2",{children:"6. What happens during the Class 7 test"}),e.jsx("p",{children:"ICBC says the Class 7 road test, including the feedback afterwards, takes about 35 minutes. Before driving, the examiner checks the vehicle and may ask you to locate or operate items such as the horn, parking brake, high beams and turn signals, and to demonstrate hand signals. If the vehicle is not test-ready, the drive may not proceed."}),e.jsx("p",{children:"On the road, the examiner gives directions with advance warning and assesses whether you demonstrate skills safely, smoothly and under control. The test may draw from such tasks as intersections and turns, entering traffic, pulling over, lane changes, hill parking, backing, parking and two- or three-point turns. It may also include identifying potential hazards. Not every skill is necessarily included, and ICBC says examiners are not looking for perfection. Follow the examiner's directions, but never make an illegal or unsafe move; ICBC states that examiners will not ask you to do one."}),e.jsx("p",{children:"Only the examiner and examinee are permitted in the vehicle during the road test. A translator cannot ride along, although ICBC allows someone to translate during the feedback session after the drive. Review the official materials in advance if English driving terms are unfamiliar."}),e.jsx("h2",{children:"7. Use the result as specific feedback"}),e.jsx("p",{children:"After the drive, the examiner tells you the result and provides a copy of the road-test form. The Skills Explainer on the form identifies the areas demonstrated and any skills to improve. If you pass, complete the licensing process and make sure you understand every novice restriction before driving as an N."}),e.jsx("p",{children:"If you do not pass, ICBC's current minimum waits are 14 days after the first unsuccessful attempt, 30 days after the second, and 60 days after a third or later attempt. These are minimums, not readiness targets. Use the examiner's written feedback and supervised practice to decide when to try again, and remember that the test fee applies again."}),e.jsx("h2",{children:"Are professional lessons required?"}),e.jsxs("p",{children:["No. A learner can prepare through legal, supervised practice and ICBC's free guides. Professional ",e.jsx(r,{to:"/driving-lessons",children:"driving lessons in Victoria"})," or a"," ",e.jsx(r,{to:"/road-test-prep-victoria",children:"road-test preparation lesson"})," are optional ways to receive structured feedback. A lesson, assessment or practice drive does not reproduce an ICBC examination and cannot guarantee a passing result."]}),e.jsx("h2",{children:"Official sources"}),e.jsxs("ul",{children:[e.jsxs("li",{children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"Get your N"})," — eligibility, test duration, feedback and retest waits."]}),e.jsxs("li",{children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"Book a road test"})," — direct booking, route confidentiality and cancellation notice."]}),e.jsxs("li",{children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Prepare-road-test-appointment",target:"_blank",rel:"noopener noreferrer",children:"Prepare for your road-test appointment"})," — ID, vehicle and test-day requirements."]}),e.jsxs("li",{children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/assets/pa/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"})," — official assessment criteria."]}),e.jsxs("li",{children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/documents/tuneup-complete.pdf",target:"_blank",rel:"noopener noreferrer",children:"Tuning Up for Drivers"})," — guided practice sessions and the 60-hour recommendation."]}),e.jsxs("li",{children:["ICBC, ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"Graduated Licensing Program changes"})," — changes effective October 19, 2026."]})]}),e.jsx("p",{children:"Sources and fees were checked on July 21, 2026. ICBC can change eligibility, fees, documentation and appointment rules. Confirm the official pages and your own licence conditions before booking or attending a test."})]})},{slug:"icbc-road-test-tips-victoria",canonicalPath:"/road-test-prep-victoria/",title:"Class 7 Road Test Tips for Victoria Driving Conditions",seoTitle:"Class 7 Road Test Tips for Victoria, B.C.",description:"Apply ICBC's Class 7 road-test skills across Greater Victoria hills, one-way streets, roundabouts and cyclist traffic without relying on route claims.",heroImage:"/blog/icbc-road-test-tips-victoria.webp",author:"Shanaya's Driving School",authorId:"azy",reviewedById:"joyce",date:"July 21, 2026",datePublished:"2026-07-05",dateModified:"2026-07-21",readTime:"8 min read",category:"Road Test Tips",relatedSlugs:["icbc-road-test-victoria-mckenzie-office","bc-glp-changes-2026","pass-road-test"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"The B.C. Class 7 road test measures whether a learner can apply safe driving skills as conditions change. This guide uses ICBC's published skill categories and shows how to practise them in driving environments found around Greater Victoria. It is not a route guide, a scoring formula or a prediction of what will appear on an individual test. No article or lesson can guarantee a result."}),e.jsx("h2",{children:"Do not build preparation around a claimed test route"}),e.jsxs("p",{children:["ICBC says it does not make road-test routes available outside ICBC and warns that sites claiming to sell those routes did not get the information from ICBC. Book directly through ICBC and prepare for transferable skills rather than memorizing a sequence of streets. See ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"road-test booking guidance"}),"."]}),e.jsx("h2",{children:"Use ICBC's five road-test skill groups"}),e.jsxs("p",{children:["ICBC's one-page"," ",e.jsx("a",{href:"https://icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"})," ","groups its criteria under observation, space margin, speed, steering and communication. The document lists specific behaviours within each group; it does not publish a simple points target or say that one group is worth most of the test."]}),e.jsxs("p",{children:["A useful way to combine the five groups is ICBC's ",e.jsx("strong",{children:"See-Think-Do"})," strategy: scan for hazards and other road users, decide which hazards create the greatest risk, then respond through speed control, steering, space margins and communication. ICBC explains that method in"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/4y4ZwCc9FaBYZTxC5LVmue/drivers5.pdf",target:"_blank",rel:"noopener noreferrer",children:"chapter 5 of Learn to Drive Smart"}),"."]}),e.jsx("h2",{children:"1. Make observation a continuous cycle"}),e.jsx("p",{children:"Looking only at the vehicle ahead is not enough. ICBC advises scanning at least 12 seconds ahead and completing an observation cycle every five to eight seconds: look well ahead, scan from side to side for potential hazards, glance in the mirrors, then repeat. Those timings come from the See-Think-Do chapter above; they are practice guidance, not a claim about how points are awarded."}),e.jsxs("ul",{children:[e.jsx("li",{children:"Scan intersections and crosswalks early, including the areas partly hidden by parked vehicles, buses, vegetation, hills or curves."}),e.jsx("li",{children:"Check the appropriate mirror and blind spot before changing direction or road position, pulling away from a curb or pulling over. Driver-assistance alerts do not replace a shoulder check."}),e.jsx("li",{children:"Before reversing, complete the 360-degree check identified in the Skills Explainer and keep looking in the direction of travel while backing."})]}),e.jsx("h2",{children:"2. Identify a hazard, then make a measured response"}),e.jsx("p",{children:"Hazard perception means noticing what could affect you or another road user before it becomes an emergency. In Greater Victoria practice, examples can include a cyclist beside parked cars, a pedestrian near a crossing, a bus blocking the view, reduced visibility in rain, or a curve or hill hiding what is ahead. These are practice scenarios, not route predictions."}),e.jsx("p",{children:"Name the hazard while practising with a qualified supervisor, assess what could happen, and identify the safest available space. ICBC's Skills Explainer says that when a potential hazard appears, the driver should take their foot off the accelerator and cover the brake in preparation to stop. That does not mean braking suddenly for every possible hazard; the response still needs to fit traffic, traction, visibility and the space around the vehicle."}),e.jsx("h2",{children:"3. Protect space around the vehicle"}),e.jsxs("p",{children:["The official criteria include a safe following distance, legal lane position, safe gaps, correct stopping position and adequate parking clearance. A gap is not safe if another road user must change speed or position because you entered it. Stop behind a crosswalk rather than blocking it, and leave enough space to finish a turn or parking manoeuvre without touching a curb or object. These behaviours are described in ICBC's"," ",e.jsx("a",{href:"https://icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"official criteria"}),"."]}),e.jsxs("p",{children:["Around cyclists, first observe, then preserve a safe side and following margin. Before a right turn or any move toward the curb, check the mirror and blind spot for a person riding beside the vehicle. ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/2nzdWqYvb055vGu78wiXoN/drivers6.pdf",target:"_blank",rel:"noopener noreferrer",children:"Sharing the Road chapter"})," ","also tells drivers to scan carefully for cyclists at intersections and wait for a clear, safe opportunity rather than crowding a cyclist while passing."]}),e.jsx("h2",{children:"4. Match speed to the limit and the conditions"}),e.jsx("p",{children:"ICBC's published criterion is a speed that is consistent, within the posted limit and appropriate for the conditions. A slower speed may be necessary when visibility or traction is reduced, but unnecessary slowing can also disrupt traffic. Anticipate changes so acceleration and braking stay smooth. Come to a complete stop where required, and on an amber light stop before entering the intersection unless a safe stop is no longer possible."}),e.jsx("p",{children:"Hills are useful for practising controlled speed, steering and space together. Prevent the vehicle from rolling back when starting uphill, manage downhill speed before it builds, and set the front wheels in the appropriate direction when hill parking. Each of those behaviours appears in the Skills Explainer or ICBC's See-Think-Do chapter."}),e.jsx("h2",{children:"5. Communicate early enough to be useful"}),e.jsx("p",{children:"Signal before turning, changing lanes, pulling out or pulling over. ICBC says a signal should give useful advance warning without being so early that it confuses other road users, and it should be cancelled after the manoeuvre. A signal communicates intent; it does not create a safe gap or replace mirror and shoulder checks."}),e.jsx("h2",{children:"Apply the skills in varied Greater Victoria conditions"}),e.jsx("p",{children:"Varied practice is more useful than repeating a claimed route. The following environments let a learner combine the official skills while driving legally with a qualified supervisor:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"One-way streets and multiple turn lanes:"})," read signs, signals and pavement markings early, choose the correct approach lane, and finish in the correct lane. For example, ICBC's rule guide shows a left turn from a one-way road to another beginning in the left lane and ending in the left lane."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Roundabouts:"})," choose the correct lane before entering, slow on approach, yield to pedestrians at the approach crosswalk and to traffic already in the roundabout, stay in the same lane, and signal right before exiting."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Hills and curves:"})," look beyond the crest or curve as far as visibility permits, reduce speed before a curve, and maintain control without cutting across the lane."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Pedestrian and cyclist activity:"})," keep the observation cycle moving, check the blind spot before turning or moving laterally, and leave safe space."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Rain or limited visibility:"})," increase the time available to respond by reducing speed appropriately and preserving space; do not drive faster than the distance you can see to stop."]})]}),e.jsxs("p",{children:["ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/assets/en/DhxStHw3HmhFhbL8v150h/drivers4.pdf",target:"_blank",rel:"noopener noreferrer",children:"Rules of the Road chapter"})," ","provides the one-way, lane-tracking and roundabout instructions. Follow the signs and markings at the location; they control the movement available there."]}),e.jsx("h2",{children:"Practise the behaviours ICBC actually documents"}),e.jsx("p",{children:"The Skills Explainer specifically identifies missed shoulder, mirror and 360-degree checks; inadequate scanning or hazard perception; unsafe gaps and following distance; blocking a crosswalk; incorrect turn or stop position; rolling stops; speed that is inconsistent or unsuitable for conditions; rollback on a hill; steering-control issues; and signal timing or cancellation problems. This is an official list of assessed behaviours, not a ranking of the most frequent reasons people are unsuccessful."}),e.jsx("p",{children:"During practice, record one observable behaviour at a time. For example: “I checked the mirror but missed the shoulder check before moving away from the curb.” That is more useful than a vague goal such as “be more confident,” because the next practice drive can repeat and verify the exact sequence."}),e.jsx("h2",{children:"Test timing, feedback and another attempt"}),e.jsxs("p",{children:["ICBC says the Class 7 road test takes about 35 minutes and includes feedback at the end. If the result is unsuccessful, ICBC's current waiting periods are 14 days after the first attempt, 30 days after the second, and 60 days after three or more attempts. Use the feedback to choose what to practise before booking again. Confirm the current details on ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"Get your N page"}),"."]}),e.jsx("h2",{children:"The first Class 7 road test remains after October 19, 2026"}),e.jsxs("p",{children:["B.C.'s GLP change on October 19, 2026 replaces the later novice-to-Class-5 road test with a Driving Record Assessment for eligible drivers. It does not remove the learner-to-novice Class 7 road test discussed here. Read ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"GLP changes page"})," ","for the transition rules."]}),e.jsx("h2",{children:"Optional instruction and independent practice"}),e.jsxs("p",{children:["Professional lessons are optional; they cannot determine or ensure the test result. A learner can use ICBC's free practice materials with a qualified supervisor, choose a licensed school for targeted feedback, or combine both. If you want optional support, see our"," ",e.jsx(r,{to:"/road-test-prep-victoria",children:"road-test preparation"})," or"," ",e.jsx(r,{to:"/driving-lessons",children:"driving lessons"}),". Shanaya's Driving School is independent from ICBC and does not set test routes, assessment criteria or licensing decisions."]}),e.jsx("h2",{children:"Official sources"}),e.jsx("p",{children:"Sources were reviewed on July 21, 2026."}),e.jsxs("ul",{children:[e.jsx("li",{children:e.jsx("a",{href:"https://icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Road Test Skills Explainer"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/assets/en/4y4ZwCc9FaBYZTxC5LVmue/drivers5.pdf",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Learn to Drive Smart, chapter 5 — See-Think-Do"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/assets/en/DhxStHw3HmhFhbL8v150h/drivers4.pdf",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Learn to Drive Smart, chapter 4 — Rules of the Road"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/assets/en/2nzdWqYvb055vGu78wiXoN/drivers6.pdf",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Learn to Drive Smart, chapter 6 — Sharing the Road"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Get your N"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Book a road test"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Changes to the Graduated Licensing Program"})})]}),e.jsx("p",{children:"Last substantive review: July 21, 2026. ICBC can change test procedures and licensing rules. Check the official pages before booking or relying on a future date."})]})},{slug:"pass-road-test",title:"B.C. Class 7 Road Test: Readiness and Test-Day Checklist",seoTitle:"B.C. Class 7 Road Test Checklist",description:"A source-checked Class 7 checklist for eligibility, practice, booking, ID, vehicle readiness, fees, test day, results and novice restrictions.",heroImage:"/blog/road-test-tips.webp",author:"Shanaya's Driving School",authorId:"azy",reviewedById:"alden",date:"July 21, 2026",datePublished:"2026-03-01",dateModified:"2026-07-21",readTime:"8 min read",category:"Road Test Checklist",relatedSlugs:["bc-glp-changes-2026","icbc-road-test-tips-victoria","icbc-road-test-victoria-mckenzie-office"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"This checklist is for a B.C. Class 7 learner preparing for the road test that leads to a novice (N) licence. It separates official requirements from preparation advice and covers what to check before booking, what to bring, what happens at the appointment and what to do with either result. No checklist, lesson or number of practice hours can guarantee a pass; the outcome depends on the driving demonstrated during the test."}),e.jsx("h2",{children:"Before booking: confirm eligibility"}),e.jsxs("p",{children:["Under the rules in effect on July 21, 2026, you may take the Class 7 road test after holding your learner's licence for at least 12 consecutive months without a driving prohibition. ICBC prints the earliest test date on the licence. Check that date and the current"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"Get your N requirements"})," ","before selecting an appointment."]}),e.jsxs("p",{children:["A scheduled change starts on ",e.jsx("strong",{children:"October 19, 2026"}),": ICBC says the minimum learner stage will be nine months for people age 25 or older and will remain 12 months for people under 25. The Class 7 learner-to-novice road test remains required. It is the later, novice-to-Class-5 road test that the new Driving Record Assessment replaces for eligible drivers. If your eligibility is near or after that date, use ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"GLP changes page"})," ","rather than assuming that the first road test disappears."]}),e.jsx("h2",{children:"Readiness check: practise skills, not a route"}),e.jsxs("p",{children:["ICBC recommends ",e.jsx("strong",{children:"at least 60 hours of practice"})," before the Class 7 road test. This is preparation guidance, not a legal minimum and not a prediction of the result. Use supervised practice in varied, legal conditions and record it in ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/documents/tuneup-complete.pdf",target:"_blank",rel:"noopener noreferrer",children:"Tuning Up for Drivers guide"}),"."]}),e.jsxs("p",{children:["Before booking, ask whether you can repeatedly perform the five core competencies in ICBC's"," ",e.jsx("a",{href:"https://icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"})," ","without prompts from your supervisor:"]}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Observation:"})," scan for hazards, use mirrors, shoulder-check before a change in direction or road position, look all around before backing and look where the vehicle is travelling."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Space margin:"})," choose a safe and legal lane position, maintain following distance, select safe gaps, stop in the correct place and leave adequate parking space."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Speed:"})," stay within the limit, adjust for conditions, stop fully when required and accelerate or slow smoothly."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Steering:"})," maintain control and position the wheels correctly when parked on a hill."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Communication:"})," signal at a useful time before turns, lane changes, pulling out or pulling over, then cancel the signal."]})]}),e.jsx("p",{children:"The Explainer also describes dangerous actions, violations and other problems; it does not publish a simple points target for learners to calculate. Readiness means applying the whole skill set safely and consistently. Practise different road environments rather than memorizing streets. ICBC states that it does not make its road-test routes available outside ICBC and that sites claiming to sell those routes did not get them from ICBC."}),e.jsx("h2",{children:"When booking: use ICBC directly"}),e.jsxs("ul",{children:[e.jsxs("li",{children:["Book, reschedule or cancel through ICBC's official"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"road-test booking page"}),". ICBC says third-party booking sites are not affiliated with it."]}),e.jsx("li",{children:"Choose a date when both you and an eligible test vehicle will be ready."}),e.jsx("li",{children:"Cancel or rebook with at least 48 hours' notice to avoid ICBC's current $25 late cancellation fee."}),e.jsx("li",{children:"Review the confirmation email and arrive at the check-in time it gives you."})]}),e.jsx("h2",{children:"What to bring: Class 7 appointment checklist"}),e.jsxs("p",{children:["Recheck ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Prepare-road-test-appointment",target:"_blank",rel:"noopener noreferrer",children:"road-test appointment page"})," ","shortly before your test. For a Class 7 appointment, prepare all of the following:"]}),e.jsxs("ul",{children:[e.jsx("li",{children:"your current learner's licence;"}),e.jsx("li",{children:"one piece of ICBC-accepted primary identification and one piece of accepted secondary identification;"}),e.jsx("li",{children:"payment for the road test and, if you pass, the novice licence; ICBC driver licensing offices currently list cash, major credit cards, debit and personal cheques as accepted methods;"}),e.jsx("li",{children:"a safe, reliable and properly insured vehicle with a Canadian licence plate, plus its registration and insurance papers; know the plate number for check-in and confirm that the insurance permits you to drive it;"}),e.jsx("li",{children:"a qualified supervisor so you can legally travel to the appointment as a learner and leave under learner conditions if you do not pass. Through October 18, 2026, the supervisor must be at least 25 and hold a valid Class 1, 2, 3, 4 or 5 licence; effective October 19, 2026, the minimum supervisor age drops to 22 and the supervisor must hold an unrestricted Class 5 licence. In either case they sit in the front passenger seat;"}),e.jsx("li",{children:"glasses or contact lenses if they are required for you to drive; and"}),e.jsx("li",{children:"a Declaration of Completion if you completed an ICBC-approved GLP driver-training course during the learner stage."})]}),e.jsx("p",{children:"For a car-share vehicle when you are not the named member, ICBC also requires a new original authorization letter for each attempt. It must be on the company's letterhead and signed and dated by a company representative."}),e.jsx("h2",{children:"Vehicle check: fix the problem or reschedule"}),e.jsx("p",{children:"ICBC may cancel a test if the vehicle is unsafe or does not meet legal requirements. Check it early enough to arrange a repair or another eligible vehicle. ICBC's published common rejection reasons include cracked or illegally tinted glass, safety-related dashboard warning lights, damaged seatbelts, non-working lights or horn, unsafe tires, doors or windows that do not work, unsafe or illegal modifications, an unclean or hazardous interior and too little fuel or battery charge. Check for an outstanding serious vehicle safety recall too."}),e.jsx("p",{children:"Reschedule if you cannot bring the required ID, payment, qualified supervisor or a legal, insured, test-ready vehicle. Giving at least 48 hours' notice avoids the current $25 cancellation fee. Do not rely on the examiner overlooking a defect: the inspection happens before the on-road portion."}),e.jsx("h2",{children:"Current fees"}),e.jsxs("p",{children:["As checked on July 21, 2026, ICBC lists ",e.jsx("strong",{children:"$35 for each Class 7 road-test attempt"})," ","and ",e.jsx("strong",{children:"$75 for the five-year novice licence"})," issued after a pass. Confirm the"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Fees",target:"_blank",rel:"noopener noreferrer",children:"current driver-licensing fees"})," ","before attending because published fees can change."]}),e.jsx("h2",{children:"Test day: what happens in order"}),e.jsxs("ol",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Check in."})," Arrive at the time in your confirmation, present the required ID, give the plate number and pay the test fee."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Complete the vehicle check."})," The examiner assesses whether the vehicle is test-ready and may ask you to locate or operate controls such as the horn, parking brake, high beams and turn signals, or demonstrate hand signals."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Take the on-road test."})," Only the examiner and examinee may be in the vehicle. Recording devices cannot be used, and GPS and navigation systems must be off. The examiner gives directions and assesses whether the published skills are demonstrated safely, smoothly and under control. Never make an illegal or unsafe movement to follow a direction."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Receive the result and feedback."})," ICBC says the complete Class 7 test, including the feedback afterwards, takes about 35 minutes. The examiner tells you the result and gives you a paper copy of the road-test form identifying demonstrated skills and areas to improve."]})]}),e.jsx("h2",{children:"If you pass: finish licensing and follow N restrictions"}),e.jsxs("p",{children:["Complete the novice licensing transaction and pay the current licence fee. ICBC's published card guidance says an interim paper driver's licence is valid for 90 days and that most physical licence or ID cards take up to 60 days to arrive. Keep the interim document valid and use ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/getting-licensed/Card-status-tracking",target:"_blank",rel:"noopener noreferrer",children:"card-status service"})," ","if needed."]}),e.jsx("p",{children:"Before driving independently, review the restrictions printed on your new licence. Current N restrictions include:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"zero alcohol and zero drugs in your blood while driving;"}),e.jsx("li",{children:"displaying the official N sign on the back of the vehicle;"}),e.jsx("li",{children:"no hand-held or hands-free cellphones or other electronic devices; and"}),e.jsx("li",{children:"one passenger, not counting immediate family, unless a qualified supervisor is seated beside you. Through October 18, 2026, that supervisor must be at least 25 with a valid Class 1, 2, 3, 4 or 5 licence; effective October 19, 2026, the minimum age drops to 22 and the supervisor must hold an unrestricted Class 5 licence."})]}),e.jsx("p",{children:"Licensing rules change and individual licences can carry additional restrictions, so the conditions printed on your licence and ICBC's current guidance control."}),e.jsx("h2",{children:"If you do not pass: use the form, then rebook when ready"}),e.jsxs("p",{children:["An unsuccessful attempt does not change the skills you need to build. Review the road-test form and the examiner's specific feedback, then practise those areas legally with a qualified supervisor. ICBC's current minimum waits are ",e.jsx("strong",{children:"14 days"})," after the first unsuccessful attempt, ",e.jsx("strong",{children:"30 days"})," after the second and"," ",e.jsx("strong",{children:"60 days"})," after a third or later attempt. A new test fee applies each time. These are waiting periods, not evidence that a learner is ready on the first available day."]}),e.jsx("p",{children:"Continue following every learner restriction until a novice licence is issued. Recheck the ID and vehicle lists before the new appointment instead of assuming the previous documents or car-share letter will carry over."}),e.jsx("h2",{children:"Optional preparation support"}),e.jsxs("p",{children:["Learners may prepare with a qualified supervisor and ICBC's free materials. Professional"," ",e.jsx(r,{to:"/driving-lessons",children:"driving lessons in Victoria"})," or a"," ",e.jsx(r,{to:"/road-test-prep-victoria",children:"road-test preparation lesson"})," are optional ways to receive structured feedback. A practice assessment is not an ICBC examination, cannot use confidential ICBC routes and cannot guarantee a result."]}),e.jsx("h2",{children:"Official source ledger"}),e.jsxs("ul",{children:[e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/Get-your-N",target:"_blank",rel:"noopener noreferrer",children:"Get your N"})," ","— current eligibility, duration, result form, retest waits and N restrictions."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Book-a-road-test",target:"_blank",rel:"noopener noreferrer",children:"Book a road test"})," ","— direct booking, cancellation notice and route confidentiality."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Prepare-road-test-appointment",target:"_blank",rel:"noopener noreferrer",children:"Prepare for your road-test appointment"})," ","— ID, payment, vehicle, car-share and in-vehicle requirements."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://icbc.com/assets/en/49OS8RJMWgWKgOx4U0EGOa/skills-explainer.pdf",target:"_blank",rel:"noopener noreferrer",children:"Road Test Skills Explainer"})," ","— the five core competencies and skill definitions."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Fees",target:"_blank",rel:"noopener noreferrer",children:"Fees"})," ","— Class 7 test and novice-licence fees and payment methods."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"Graduated Licensing Program changes"})," ","— changes effective October 19, 2026."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/getting-licensed/Card-status-tracking",target:"_blank",rel:"noopener noreferrer",children:"Card status tracking"}),", and"," ",e.jsx("a",{href:"https://www.icbc.com/about-icbc/newsroom/icbc-services-during-canada-post-disruption-05-2025",target:"_blank",rel:"noopener noreferrer",children:"interim-licence guidance"})," ","— card delivery and the validity period of the paper interim licence."]})]}),e.jsx("p",{children:"Sources, fees and future-rule descriptions were last substantively checked on July 21, 2026. ICBC can change requirements, restrictions, fees and appointment procedures. Confirm the official pages and your own licence before booking or driving."})]})},{slug:"defensive-driving",canonicalPath:"/courses/defensive-driving-course/",title:"Defensive Driving in B.C.: A Practical Risk-Management Guide",seoTitle:"Defensive Driving in B.C.: Practical Guide",description:"Use ICBC's See–Think–Do method to scan, manage space, choose a safe speed and respond calmly to common driving risks in B.C.",heroImage:"/blog/what-is-defensive-driving.webp",author:"Shanaya's Driving School",authorId:"azy",reviewedById:"joyce",date:"July 21, 2026",datePublished:"2026-02-20",dateModified:"2026-07-21",readTime:"8 min read",category:"Driving Skills",relatedSlugs:["pass-road-test","newcomers-guide-bc"],content:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Defensive driving is not a promise that every collision can be avoided. It is a repeatable way to identify risk early, preserve time and space, and choose a response that leaves a margin for mistakes by you or someone else. For B.C. drivers, a useful starting point is ICBC's ",e.jsx("strong",{children:"See–Think–Do"})," method."]}),e.jsx("h2",{children:"1. Use See–Think–Do as a continuous cycle"}),e.jsxs("p",{children:["ICBC presents See–Think–Do in Chapter 5 of its official"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driving-guides/Learn-to-Drive-Smart",target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart guide"}),". It is a decision cycle, not a single manoeuvre:"]}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"See:"})," keep your eyes moving, look well ahead, scan from side to side and use your mirrors. Look for road users, signs, surface changes, restricted sight lines and anything else that could create a conflict."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Think:"})," assess the risk. Ask what could happen, whether your current speed and space are enough, and which response creates the lowest risk."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Do:"})," act early and smoothly. That may mean communicating, changing lane position, increasing following distance, reducing speed or deciding not to proceed."]})]}),e.jsx("p",{children:"The cycle continues throughout the drive. Looking without assessing the risk is incomplete; identifying a hazard without making a timely adjustment is also incomplete."}),e.jsx("h2",{children:"2. Build an observation routine"}),e.jsxs("p",{children:["ICBC advises drivers to scan ",e.jsx("strong",{children:"at least 12 seconds ahead"}),". In city driving, its guide describes that as roughly one to two blocks; on a highway, roughly half a kilometre. The purpose is to notice developing situations before they demand abrupt action. ICBC also says to repeat the full observation cycle—look ahead, scan side to side and glance in the mirrors—every ",e.jsx("strong",{children:"five to eight seconds"}),". These are scanning habits, not a reason to stare away from the path immediately in front of the vehicle."]}),e.jsxs("p",{children:["Mirrors do not show every area around a vehicle. Do a shoulder check whenever you plan to change direction or road position, including pulling away, pulling over, changing lanes and turning. Check again before opening a vehicle door. Blind-spot monitors and cameras can provide useful information, but ICBC says they do not replace turning your head to check the relevant blind spot or looking behind when required. See the observation and blind-spot guidance in"," ",e.jsx("a",{href:"https://icbc.com/assets/en/4y4ZwCc9FaBYZTxC5LVmue/drivers5.pdf",target:"_blank",rel:"noopener noreferrer",children:"ICBC's See–Think–Do chapter (PDF)"}),"."]}),e.jsx("h2",{children:"3. Match following distance to the conditions"}),e.jsx("p",{children:"Use a fixed object beside the road to measure a time gap. When the rear of the vehicle ahead passes it, count the seconds until the front of your vehicle reaches the same point. ICBC's current guidance is:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"At least two seconds"})," in good weather and road conditions."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"At least three seconds"})," on high-speed roads; behind a large vehicle that blocks your view; behind a motorcycle that may stop quickly; when a vehicle is following closely behind you; or on an unpaved road where dust or gravel may reduce visibility or traction."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"At least four seconds"})," in bad weather or on uneven or slippery roads."]})]}),e.jsxs("p",{children:["Those time gaps are ICBC driving guidance, not a universal legal safe harbour. Section 162 of B.C.'s"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05#section162",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act"})," ","prohibits following more closely than is reasonable and prudent, having regard to speed, traffic and highway conditions. Increase the gap beyond the guide's examples whenever visibility, traction, load, fatigue, vehicle condition or another hazard means you need more time or stopping distance."]}),e.jsx("h2",{children:"4. Keep space around the vehicle and preserve an escape option"}),e.jsx("p",{children:"Space in front is only one part of the plan. Avoid travelling beside another vehicle for longer than necessary, stay out of other drivers' blind spots and leave room beside parked vehicles for an opening door or a person stepping out. On a multi-lane road, notice whether an adjacent clear area could provide an escape route if traffic ahead stops suddenly. An escape option is something to preserve through positioning and observation—it is not permission to make an unsafe lane movement."}),e.jsxs("p",{children:["If another driver follows too closely, do not brake-check, compete or make abrupt changes. ICBC recommends staying calm and slightly increasing the space in front so that, if you must slow, you can do so more gradually. When it is safe, move to another lane or pull over and let the driver pass. ICBC provides the same guidance on its"," ",e.jsx("a",{href:"https://www.icbc.com/about-icbc/newsroom/2025-06-24-tailgating-survey",target:"_blank",rel:"noopener noreferrer",children:"tailgating safety page"}),"."]}),e.jsx("h2",{children:"5. Treat the posted limit as a limit, not a target for every condition"}),e.jsxs("p",{children:["Read the road, traffic, visibility and weather before selecting a speed. Section 144 of the"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05#section144",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act"})," ","prohibits driving at a speed that is excessive relative to those conditions. A posted speed limit therefore does not mean that speed is suitable in rain, glare, fog, darkness, congestion or on a slippery surface. Reduce speed before the hazard, make steering and braking inputs smoothly, and keep enough clear distance to stop within what you can see."]}),e.jsx("h2",{children:"6. Remove risks that observation cannot compensate for"}),e.jsx("h3",{children:"Distraction"}),e.jsxs("p",{children:["Set navigation, climate controls and audio before moving, and keep the phone out of sight and reach. B.C.'s electronic-device rules apply even when stopped at a red light. Learner and novice drivers may not use personal electronic devices while driving, including hands-free devices. ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/road-safety/crashes-happen/distracted-driving",target:"_blank",rel:"noopener noreferrer",children:"distracted-driving page"})," ","explains the current restrictions and links to the law."]}),e.jsx("h3",{children:"Alcohol, drugs and medication"}),e.jsxs("p",{children:["Do not drive while impaired. Arrange another way home before consuming alcohol or cannabis. Prescription and over-the-counter medicines can also affect driving; ICBC advises checking with a physician or pharmacist about how a medication may affect you. Do not guess at a supposedly safe waiting period for cannabis—the effects vary by person, dose and method of consumption. See ICBC's current"," ",e.jsx("a",{href:"https://www.icbc.com/road-safety/crashes-happen/drug-impaired-driving",target:"_blank",rel:"noopener noreferrer",children:"drug-impaired-driving guidance"}),"."]}),e.jsx("h3",{children:"Fatigue"}),e.jsxs("p",{children:["Difficulty holding your lane, drifting speed, heavy eyes, blurred vision, loss of focus or not recalling the last few minutes are warning signs. If they appear, stop in a safe place and rest or change drivers; opening a window or turning up music does not resolve the need for sleep. ICBC recommends beginning a long trip rested, planning breaks and understanding whether medication can cause drowsiness. Its"," ",e.jsx("a",{href:"https://www.icbc.com/about-icbc/newsroom/2025-07-29-fatigue",target:"_blank",rel:"noopener noreferrer",children:"driver-fatigue guidance"})," ","lists the warning signs and practical responses."]}),e.jsx("h2",{children:"7. Give pedestrians, cyclists and other vulnerable road users room"}),e.jsx("p",{children:"Search sidewalks, crosswalks, driveways, parked-vehicle gaps and cycle lanes rather than looking only for cars. Shoulder-check for a cyclist before turning right, and look for an oncoming cyclist before turning left. Approach a blocked view at a speed that gives you time to respond to someone who appears late."}),e.jsx("p",{children:"When passing a pedestrian, cyclist or another person covered by section 157.1 of B.C.'s Motor Vehicle Act, the movement must be safe and the minimum lateral distance is generally:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"1 metre"})," where the speed limit is 50 km/h or less;"]}),e.jsxs("li",{children:[e.jsx("strong",{children:"1.5 metres"})," where the speed limit is more than 50 km/h; or"]}),e.jsxs("li",{children:[e.jsx("strong",{children:"0.5 metre"})," when the person is on a sidewalk or in a protected cycle lane."]})]}),e.jsxs("p",{children:["The governing text is"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05#section157.1",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act section 157.1"})," ","and"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/26_58_16",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act Regulations, Division 48"}),". A minimum distance does not make an otherwise unsafe pass acceptable. Wait for a safe opportunity and allow more space when conditions call for it."]}),e.jsx("h2",{children:"A short practice routine"}),e.jsx("p",{children:"During lawful practice, have the learner quietly identify one developing hazard, the space available and the lowest-risk response. At the end of the drive, review one situation in this order: what was visible, what risk developed, what choice was made, and whether an earlier adjustment would have created more margin. Keep the discussion away from busy moments so it does not become a distraction."}),e.jsx("h2",{children:"Defensive-driving lessons and insurance"}),e.jsxs("p",{children:["A defensive-driving lesson does not automatically create an ICBC insurance discount. ICBC says premiums are affected by factors including listed drivers, driving experience, crash history, vehicle use and territory. Its"," ",e.jsx("a",{href:"https://www.icbc.com/insurance/costs/drivers-experience-crash-history",target:"_blank",rel:"noopener noreferrer",children:"premium-factor explanation"})," ","says experience and crash history help determine driver risk; it does not promise a discount for completing this type of lesson. Ask an Autoplan broker about your own policy rather than relying on a course-marketing claim."]}),e.jsx("h2",{children:"Where to get help"}),e.jsxs("p",{children:["Drivers can study the official guide and practise these routines independently when they are legally qualified and, for learners, with the required supervisor. Someone who wants structured feedback can also review our optional"," ",e.jsx(r,{to:"/courses/defensive-driving-course",children:"defensive-driving lesson information"})," or"," ",e.jsx(r,{to:"/driving-lessons",children:"driving lessons in Greater Victoria"}),". Lessons cannot eliminate road risk or guarantee a particular driving, test or insurance outcome."]}),e.jsx("h2",{children:"Official source ledger"}),e.jsxs("ul",{children:[e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/driving-guides/Learn-to-Drive-Smart",target:"_blank",rel:"noopener noreferrer",children:"Learn to Drive Smart"})," ","and its"," ",e.jsx("a",{href:"https://icbc.com/assets/en/4y4ZwCc9FaBYZTxC5LVmue/drivers5.pdf",target:"_blank",rel:"noopener noreferrer",children:"See–Think–Do chapter (PDF)"}),": observation, blind spots, following distance, space margins and speed selection."]}),e.jsxs("li",{children:["Province of British Columbia,"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_00_multi",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act"})," ","and"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/26_58_00_multi",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act Regulations"}),": conditional speed, prudent following and minimum passing-distance requirements."]}),e.jsxs("li",{children:["ICBC road-safety pages on"," ",e.jsx("a",{href:"https://www.icbc.com/road-safety/crashes-happen/distracted-driving",target:"_blank",rel:"noopener noreferrer",children:"distraction"}),","," ",e.jsx("a",{href:"https://www.icbc.com/road-safety/crashes-happen/drug-impaired-driving",target:"_blank",rel:"noopener noreferrer",children:"drug impairment and medication"})," ","and"," ",e.jsx("a",{href:"https://www.icbc.com/about-icbc/newsroom/2025-07-29-fatigue",target:"_blank",rel:"noopener noreferrer",children:"fatigue"}),": avoidable driver-state risks and response guidance."]}),e.jsxs("li",{children:["ICBC,"," ",e.jsx("a",{href:"https://www.icbc.com/insurance/costs/drivers-experience-crash-history",target:"_blank",rel:"noopener noreferrer",children:"Drivers, experience and crash history"}),": factors ICBC uses when determining premiums."]})]}),e.jsx("p",{children:"Sources and legal references were checked on July 21, 2026. Laws and ICBC guidance can change. Consult the current official text for your circumstances; this article is general educational information, not legal or insurance advice."})]})},{slug:"newcomers-guide-bc",canonicalPath:"/courses/new-to-canada/",title:"Moving to B.C.: Licence Deadlines and Five Road Rules to Check",seoTitle:"Moving to B.C.: Licence Deadlines & 5 Road Rules",description:"A source-checked overview of B.C.'s 90-day licence deadline, newcomer licensing paths, vehicle deadline, and five road rules for passenger drivers.",heroImage:"/blog/newcomers-guide-bc.webp",author:"Shanaya's Driving School",authorId:"alden",reviewedById:"azy",date:"July 21, 2026",datePublished:"2026-02-10",dateModified:"2026-07-21",readTime:"7 min read",category:"Newcomer Resources",relatedSlugs:["bc-glp-changes-2026","defensive-driving","pass-road-test"],content:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"This article is a focused starting point for an ordinary passenger-vehicle driver moving to British Columbia. It covers the main licence and vehicle deadlines, shows where to find the correct licensing path, and explains five road rules that are easy to misread. It does not cover commercial or motorcycle licensing, and ICBC must decide how a particular licence and driving record are recognized."}),e.jsx("h2",{children:"The general licence deadline is 90 days"}),e.jsxs("p",{children:["ICBC says that after moving to B.C., a person generally has ",e.jsx("strong",{children:"90 days"})," to switch a valid licence to a B.C. driver's licence. Start early if testing or document verification may be required. See ICBC's current"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc",target:"_blank",rel:"noopener noreferrer",children:"moving-to-B.C. hub"})," ","before relying on the deadline."]}),e.jsxs("p",{children:["ICBC identifies exceptions to that general rule for a tourist visiting for up to six months, a full-time student who has a valid exemption at a designated educational institution, a person ordinarily resident outside B.C., and a temporary foreign worker whose federal work permit places them in the Seasonal Agricultural Worker Program. ICBC says a qualifying worker in that program may drive on a valid home-jurisdiction licence for up to 12 months. Each exception has conditions; moving to B.C. does not by itself prove that an exception applies. Check the live list on ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc/moving-from-another-country",target:"_blank",rel:"noopener noreferrer",children:"moving from outside Canada page"})," ","or ask ICBC about your status."]}),e.jsx("h2",{children:"Use the path that matches your licence and provable experience"}),e.jsx("p",{children:"The following four planning categories summarize common passenger-vehicle cases. They are not a substitute for ICBC's assessment, and the current exchange-jurisdiction list should be checked rather than copied from an old article."}),e.jsxs("ol",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Licence from another Canadian province or territory:"})," follow ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc/Moving-from-within-canada",target:"_blank",rel:"noopener noreferrer",children:"within-Canada exchange instructions"}),"."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Licence from an exchange jurisdiction outside Canada:"})," an eligible non-commercial licence may be exchanged without the usual knowledge and road tests. Confirm that the jurisdiction and licence class appear on ICBC's live exchange list."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Licence from a non-exchange jurisdiction:"})," ICBC says a knowledge test and road test are required. Provable full-privilege driving experience affects whether the driver can seek a Class 5 licence without entering GLP."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Less than two years of full-privilege experience, or no acceptable proof:"})," ","ICBC says the driver enters the Graduated Licensing Program (GLP). A person who does not already hold a licence follows ICBC's new-driver process."]})]}),e.jsxs("p",{children:["ICBC's complete"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc/moving-from-another-country",target:"_blank",rel:"noopener noreferrer",children:"outside-Canada instructions"})," ","explain the exchange and testing routes. Our separate"," ",e.jsx(r,{to:"/blog/newcomers-guide-bc",children:"B.C. driver's licence guide"})," walks through these paths in more detail."]}),e.jsx("h2",{children:"Bring documents ICBC accepts, not a generic checklist"}),e.jsxs("p",{children:["ICBC's outside-Canada application list includes accepted identification, the current driver's licence, the applicable licence fees and proof of driving experience. Its"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/visit-dl-office/Accepted-ID",target:"_blank",rel:"noopener noreferrer",children:"accepted-ID page"})," ","currently calls for one primary and one secondary piece of ID and explains additional requirements. Document needs can vary with immigration status, issuing jurisdiction, licence class and name history, so verify the current list for your appointment."]}),e.jsxs("p",{children:["Proof of at least ",e.jsx("strong",{children:"two years"})," with a full-privilege, non-learner licence is needed for a GLP exemption. ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc/Proving-your-driving-experience",target:"_blank",rel:"noopener noreferrer",children:"driving-experience page"})," ","describes acceptable records and special instructions by jurisdiction. If a licence, driving record or ID needs translation, use an ICBC-approved translator and present the original document, or a copy that a driver licensing office has approved and stamped, with the translation. ICBC may also hold an application while it verifies documents."]}),e.jsx("p",{children:"A person may legally hold only one driver's licence in B.C. ICBC says the previous licence must be surrendered when the person qualifies for the new B.C. licence. If a required road test is unsuccessful, ICBC says it issues a B.C. learner's licence and does not return the previous licence."}),e.jsx("h2",{children:"A personal vehicle has a separate 30-day deadline"}),e.jsxs("p",{children:["The driver's-licence deadline and the vehicle deadline are different. If you bring your personal vehicle to B.C., ICBC says you have ",e.jsx("strong",{children:"30 days after arriving"})," to register, license and insure it in B.C.; commercial vehicles must be handled immediately. Import, inspection and exemption requirements depend on the vehicle and where it came from. Start with ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/insurance/moving-travelling/moving-BC",target:"_blank",rel:"noopener noreferrer",children:"moving and insurance page"})," ","and confirm the required documents with an Autoplan broker."]}),e.jsx("h2",{children:"Five B.C. road rules to check"}),e.jsx("h3",{children:"1. A right turn may be made on a steady red only after stopping and yielding"}),e.jsxs("p",{children:["Under section 129 of B.C.'s Motor Vehicle Act, a driver facing a steady red light must stop before the near crosswalk, or before the intersection if there is no marked crosswalk. A right turn may then be made only if a sign does not prohibit it and after yielding to pedestrians and vehicles lawfully proceeding through the intersection. The turn must also be safe. This permission applies to a ",e.jsx("strong",{children:"steady red light"}),"; it is not permission to turn against a red arrow or another signal controlling the lane. See the official"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act, sections 129–130"}),"."]}),e.jsx("h3",{children:"2. A signed school zone is 30 km/h on regular school days"}),e.jsxs("p",{children:["Where a school-zone sign displays 30 km/h, section 147 requires a maximum of 30 km/h on a regular school day from ",e.jsx("strong",{children:"8 a.m. to 5 p.m."}),", or for the longer times stated on the sign. A school warning sign without a 30 km/h tab does not create that 30 km/h limit; read the whole sign and continue to watch for children."]}),e.jsx("h3",{children:"3. A signed public playground zone is 30 km/h from dawn to dusk"}),e.jsxs("p",{children:["The same section sets a 30 km/h maximum when approaching or passing a public playground between ",e.jsx("strong",{children:"dawn and dusk"})," where signs display that limit or prominently show “30.” Unlike the school-zone rule, the statute does not restrict the playground rule to school days. Read B.C.'s current"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05",target:"_blank",rel:"noopener noreferrer",children:"Motor Vehicle Act, section 147"})," ","for both zone rules."]}),e.jsx("h3",{children:"4. Class 7 L and N drivers have a broader electronic-device ban"}),e.jsxs("p",{children:["All drivers are prohibited from holding or operating a hand-held communication or computing device, watching its screen, or sending and receiving text-based messages while driving. The regulation permits limited hands-free, audio and navigation uses for drivers who meet its installation and operation conditions—but those permissions do not apply to drivers with a Class 7 learner or novice licence. RoadSafetyBC describes the Class 7 rule as a ban on electronic-device use while driving, including hands-free units and navigation devices, with limited exceptions for being safely parked off the roadway or making an emergency call. Check the Government of B.C.'s"," ",e.jsx("a",{href:"https://www2.gov.bc.ca/gov/content/transportation/driving-and-cycling/roadsafetybc/high-risk/distracted/electronic-devices",target:"_blank",rel:"noopener noreferrer",children:"electronic-device rules"})," ","and the current"," ",e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/308_2009",target:"_blank",rel:"noopener noreferrer",children:"regulation"}),"."]}),e.jsx("h3",{children:"5. Winter-tire dates apply on designated, signed routes"}),e.jsxs("p",{children:["Winter tires or chains are required on most designated routes from ",e.jsx("strong",{children:"October 1 to April 30"}),"; requirements on some routes end March 31. The regulatory signs on the highway identify where the rule applies, and authorities may restrict travel when conditions require it. For a standard passenger vehicle, a legal winter tire must show either the letters M and S or the three-peaked mountain-and-snowflake symbol and have at least ",e.jsx("strong",{children:"3.5 mm"})," of tread depth. Review the Province's current"," ",e.jsx("a",{href:"https://www2.gov.bc.ca/gov/content/transportation/driving-and-cycling/traveller-information/seasonal/winter-driving/winter-tire-and-chain-up-routes",target:"_blank",rel:"noopener noreferrer",children:"designated-route maps and dates"})," ","and"," ",e.jsx("a",{href:"https://www2.gov.bc.ca/gov/content/transportation/driving-and-cycling/traveller-information/seasonal/winter-driving/about-winter-tires",target:"_blank",rel:"noopener noreferrer",children:"passenger-tire requirements"})," ","before travelling."]}),e.jsx("h2",{children:"GLP changes on October 19, 2026"}),e.jsxs("p",{children:["B.C.'s passenger-vehicle GLP changes on ",e.jsx("strong",{children:"October 19, 2026"}),". The learner-to- novice road test remains. For eligible novice drivers, a Driving Record Assessment replaces the later road test used to move to a Class 5 licence, followed by a 12-month restricted Class 5 stage. Age, time in the novice stage and the driving record affect eligibility. These changes do not turn a non-exchange foreign licence into an exchangeable licence. Read ICBC's"," ",e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"official GLP changes page"})," ","and our source-linked"," ",e.jsx(r,{to:"/blog/bc-glp-changes-2026",children:"October 19 GLP guide"})," for the transition details."]}),e.jsx("h2",{children:"Optional local driving feedback"}),e.jsxs("p",{children:["Professional instruction is optional. Shanaya's Driving School is independent from ICBC; it cannot decide licence-exchange eligibility, approve documents, issue a licence or guarantee a test result. A driver who wants optional local feedback can review our"," ",e.jsx(r,{to:"/driving-lessons",children:"driving lessons"}),". Official licensing decisions and current legal requirements remain with ICBC and the Province of B.C."]}),e.jsx("h2",{children:"Official sources"}),e.jsx("p",{children:"Sources were reviewed on July 21, 2026. Rules and service procedures can change; use the linked official pages to confirm the current requirements for your circumstances."}),e.jsxs("ul",{children:[e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc/moving-from-another-country",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Moving from outside Canada"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc/Moving-from-within-canada",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Moving from within Canada"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/moving-bc/Proving-your-driving-experience",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Proving your driving experience"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/insurance/moving-travelling/moving-BC",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Moving to, from or within B.C."})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/96318_05",target:"_blank",rel:"noopener noreferrer",children:"B.C. Laws: Motor Vehicle Act, Part 3"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www2.gov.bc.ca/gov/content/transportation/driving-and-cycling/roadsafetybc/high-risk/distracted/electronic-devices",target:"_blank",rel:"noopener noreferrer",children:"Government of B.C.: Use of electronic devices while driving"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www2.gov.bc.ca/gov/content/transportation/driving-and-cycling/traveller-information/seasonal/winter-driving/winter-tire-and-chain-up-routes",target:"_blank",rel:"noopener noreferrer",children:"Government of B.C.: Designated winter tire and chain routes"})}),e.jsx("li",{children:e.jsx("a",{href:"https://www.icbc.com/driver-licensing/new-drivers/graduated-licensing-program-changes",target:"_blank",rel:"noopener noreferrer",children:"ICBC: Changes to the Graduated Licensing Program"})})]})]})}],ge=he.filter(i=>i.slug!=="how-to-pass-driving-test-victoria-bc");export{ge as a,he as b};
